mod lexer;
mod parser;
mod ast;
mod interpreter;
mod stdlib;

use std::io::{self, Read, Write};
use std::process;

fn print_usage() {
    eprintln!("Hush 0.1.4");
    eprintln!("gahag <gabriel.s.b@live.com>");
    eprintln!("Hush is a unix shell scripting language based on the Lua programming language");
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("    hush [FLAGS] [arguments]...");
    eprintln!();
    eprintln!("FLAGS:");
    eprintln!("        --ast        Print the AST");
    eprintln!("        --check      Perform only static analysis instead of executing.");
    eprintln!("    -h, --help       Prints help information");
    eprintln!("        --lex        Print the lexemes");
    eprintln!("        --program    Print the PROGAM");
    eprintln!("    -V, --version    Prints version information");
    eprintln!();
    eprintln!("ARGS:");
    eprintln!("    <arguments>...    Script and/or arguments");
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut show_ast = false;
    let mut show_lex = false;
    let mut show_program = false;
    let mut check_only = false;
    let mut script_args: Vec<String> = Vec::new();

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--ast" => show_ast = true,
            "--lex" => show_lex = true,
            "--program" => show_program = true,
            "--check" => check_only = true,
            "-h" | "--help" => {
                print_usage();
                process::exit(0);
            }
            "-V" | "--version" => {
                println!("Hush 0.1.4");
                process::exit(0);
            }
            _ => {
                script_args.push(args[i].clone());
            }
        }
        i += 1;
    }

    if script_args.is_empty() {
        // REPL mode
        run_repl();
    } else {
        let script_path = script_args[0].clone();
        let script_args_rest: Vec<String> = script_args[1..].to_vec();

        let source = match std::fs::read_to_string(&script_path) {
            Ok(s) => s,
            Err(e) => {
                eprintln!("Error reading file '{}': {}", script_path, e);
                process::exit(1);
            }
        };

        run_script(&source, &script_path, script_args_rest, show_lex, show_ast, show_program, check_only);
    }
}

fn run_script(source: &str, path: &str, args: Vec<String>, show_lex: bool, show_ast: bool, show_program: bool, check_only: bool) {
    let mut had_error = false;

    // Lex
    let (tokens, lex_errors) = lexer::lex(source, path);

    for err in &lex_errors {
        eprintln!("{}", err);
        had_error = true;
    }

    if show_lex {
        println!("--------------------------------------------------");
        for tok in &tokens {
            println!("{}", tok);
        }
        println!("--------------------------------------------------");
    }

    // Parse
    let (program, parse_errors) = parser::parse(&tokens, path);

    for err in &parse_errors {
        eprintln!("{}", err);
        had_error = true;
    }

    if show_ast {
        println!("--------------------------------------------------");
        println!("AST for {}", path);
        for stmt in &program.stmts {
            print!("{}", ast::fmt_stmt(stmt, 0));
        }
        println!("--------------------------------------------------");
    }

    // Semantic analysis
    let sem_errors = interpreter::analyze(&program, path);
    for err in &sem_errors {
        eprintln!("{}", err);
        had_error = true;
    }

    if show_program {
        println!("--------------------------------------------------");
        println!("Program for {}", path);
        // Print compiled program representation
        let prog_str = interpreter::fmt_program(&program);
        print!("{}", prog_str);
        println!("--------------------------------------------------");
    }

    if had_error {
        process::exit(2);
    }

    if check_only {
        return;
    }

    // Execute
    let exit_code = interpreter::execute(&program, path, args);
    process::exit(exit_code);
}

fn run_repl() {
    let stdin = io::stdin();
    let mut source = String::new();

    if atty::is_stdin() {
        // Interactive mode - but we don't have atty crate, check differently
    }

    // Read all stdin and execute
    match io::stdin().lock().read_to_string(&mut source) {
        Ok(_) => {}
        Err(e) => {
            eprintln!("Error reading stdin: {}", e);
            process::exit(1);
        }
    }

    if source.is_empty() {
        return;
    }

    run_script(&source, "<stdin>", vec![], false, false, false, false);
}

mod atty {
    pub fn is_stdin() -> bool {
        unsafe {
            libc_isatty(0) != 0
        }
    }

    extern "C" {
        fn isatty(fd: i32) -> i32;
    }

    unsafe fn libc_isatty(fd: i32) -> i32 {
        isatty(fd)
    }
}
RUST_EOF

