        eprintln!("{}", err);
        had_error = true;
    }

    if show_program {
        println!("--------------------------------------------------");
        println!("Program for {}", path);
        // Print compiled program representation
        let prog_str = interpreter::fmt_program(&program);
        print!("{}", prog_str);
        println!("--------------------------------------------------");
    }

    if had_error {
        process::exit(2);
    }

    if check_only {
        return;
    }

    // Execute
    let exit_code = interpreter::execute(&program, path, args);
    process::exit(exit_code);
}

fn run_repl() {
    let stdin = io::stdin();
    let mut source = String::new();

    if atty::is_stdin() {
        // Interactive mode - but we don't have atty crate, check differently
    }

    // Read all stdin and execute
    match io::stdin().lock().read_to_string(&mut source) {
        Ok(_) => {}
        Err(e) => {
            eprintln!("Error reading stdin: {}", e);
            process::exit(1);
        }
    }

    if source.is_empty() {
        return;
    }

    run_script(&source, "<stdin>", vec![], false, false, false, false);
