#[derive(Debug, Clone, PartialEq)]
pub enum TokenKind {
    // Literals
    Nil,
    True,
    False,
    Int(i64),
    Float(f64),
    Str(String),
    Char(u8),
    // Identifiers
    Ident(String),
    // Keywords
    Let,
    Function,
    If,
    Then,
    Else,
    ElseIf,
    End,
    While,
    Do,
    For,
    In,
    Return,
    Break,
    // Operators
    Plus,
    Minus,
    Star,
    Slash,
    Percent,
    Eq,       // ==
    NotEq,    // !=
    Lt,       // <
    LtEq,     // <=
    Gt,       // >
    GtEq,     // >=
    And,      // and
    Or,       // or
    Not,      // not
    Assign,   // =
    PlusPlus, // ++
    // Delimiters
    LParen,
    RParen,
    LBracket,
    RBracket,
    LBrace,
    RBrace,
    At,       // @
    AtLBracket, // @[
    Comma,
    Colon,
    Dot,
    Semicolon,
    // Command block tokens
    DollarLBrace, // ${
    AmpersandLBrace, // &{
    Pipe,         // |
    Arrow,        // >
    Append,       // >>
    StdinHeredoc, // <<
    Question,     // ?
    Number(i64),   // for redirect fd numbers (2, 1, etc.)
    // End of file
    Eof,
}

#[derive(Debug, Clone)]
pub struct Token {
    pub kind: TokenKind,
    pub line: usize,
    pub col: usize,
    pub source_repr: String, // original source representation for display
}

impl std::fmt::Display for Token {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        // For lex output: path (line X, column Y):\tTOKEN
        // We need the path - will be set externally
        write!(f, "{}:{}", self.line, self.col)
    }
}

pub struct LexToken {
    pub path: String,
    pub token: Token,
}

impl std::fmt::Display for LexToken {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{} (line {}, column {}):\t{}", 
            self.path, self.token.line + 1, self.token.col, self.token.source_repr)
    }
}

pub struct Lexer<'a> {
    source: &'a [u8],
    pos: usize,
    line: usize,
    col: usize,
    path: String,
    in_cmd_block: usize, // depth of command blocks
}

impl<'a> Lexer<'a> {
    pub fn new(source: &'a str, path: &str) -> Self {
        Lexer {
            source: source.as_bytes(),
            pos: 0,
            line: 0,
            col: 0,
            path: path.to_string(),
            in_cmd_block: 0,
        }
    }

    fn peek(&self) -> Option<u8> {
        self.source.get(self.pos).copied()
    }

    fn peek2(&self) -> Option<u8> {
        self.source.get(self.pos + 1).copied()
    }

    fn advance(&mut self) -> Option<u8> {
        let ch = self.source.get(self.pos).copied();
        if let Some(c) = ch {
            self.pos += 1;
            if c == b'\n' {
                self.line += 1;
                self.col = 0;
            } else {
                self.col += 1;
            }
        }
        ch
    }

    fn skip_whitespace_and_comments(&mut self) {
        loop {
            match self.peek() {
                Some(b' ') | Some(b'\t') | Some(b'\r') | Some(b'\n') => {
                    self.advance();
                }
                Some(b'#') => {
                    // Comment - skip to end of line
                    while let Some(c) = self.peek() {
                        if c == b'\n' {
                            break;
                        }
                        self.advance();
                    }
                }
                _ => break,
            }
        }
    }

    fn lex_string(&mut self, errors: &mut Vec<String>) -> Option<TokenKind> {
        // Opening " already consumed
        let mut s = String::new();
        let mut raw = String::from("\"");

        loop {
            match self.peek() {
                None => {
                    errors.push(format!("{} (line {}, column {}) - unterminated string", 
                        self.path, self.line + 1, self.col));
                    return None;
                }
                Some(b'"') => {
                    self.advance();
                    raw.push('"');
                    break;
                }
                Some(b'\\') => {
                    let esc_col = self.col;
                    self.advance();
                    raw.push('\\');
                    match self.peek() {
                        Some(b'n') => { self.advance(); s.push('\n'); raw.push('n'); }
                        Some(b't') => { self.advance(); s.push('\t'); raw.push('t'); }
                        Some(b'0') => { self.advance(); s.push('\0'); raw.push('0'); }
                        Some(b'\\') => { self.advance(); s.push('\\'); raw.push('\\'); }
                        Some(b'"') => { self.advance(); s.push('"'); raw.push('"'); }
                        Some(b'\'') => { self.advance(); s.push('\''); raw.push('\''); }
                        Some(c) => {
                            let ch = c as char;
                            self.advance();
                            raw.push(ch);
                            errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                                self.path, self.line + 1, esc_col, ch));
                            s.push(ch); // still add the char
                        }
                        None => {
                            errors.push(format!("{} (line {}, column {}) - unterminated escape",
                                self.path, self.line + 1, esc_col));
                        }
                    }
                }
                Some(c) => {
                    let ch = c as char;
                    self.advance();
                    s.push(ch);
                    raw.push(ch);
                }
            }
        }

        Some(TokenKind::Str(s))
    }

    fn lex_char(&mut self, errors: &mut Vec<String>) -> Option<(TokenKind, String)> {
        // Opening ' already consumed
        let start_col = self.col - 1;
        let byte = match self.peek() {
            Some(b'\\') => {
                self.advance();
                match self.peek() {
                    Some(b'n') => { self.advance(); b'\n' }
                    Some(b't') => { self.advance(); b'\t' }
                    Some(b'0') => { self.advance(); b'\0' }
                    Some(b'\\') => { self.advance(); b'\\' }
                    Some(b'\'') => { self.advance(); b'\'' }
                    Some(b'"') => { self.advance(); b'"' }
                    Some(c) => {
                        let ch = c as char;
                        let esc_col = self.col;
                        self.advance();
                        // consume rest and close quote
                        while let Some(cc) = self.peek() {
                            if cc == b'\'' { self.advance(); break; }
                            self.advance();
                        }
                        errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                            self.path, self.line + 1, esc_col - 1, ch));
                        return None;
                    }
                    None => {
                        errors.push(format!("{} (line {}, column {}) - unterminated char", 
                            self.path, self.line + 1, start_col));
                        return None;
                    }
                }
            }
            Some(c) => {
                let b = c;
                self.advance();
                b
            }
            None => {
                errors.push(format!("{} (line {}, column {}) - unterminated char", 
                    self.path, self.line + 1, start_col));
                return None;
            }
        };

        match self.peek() {
            Some(b'\'') => {
                self.advance();
            }
            _ => {
                errors.push(format!("{} (line {}, column {}) - unterminated char literal", 
                    self.path, self.line + 1, start_col));
            }
        }

        let raw = format!("'{}'", byte as char);
        Some((TokenKind::Char(byte), raw))
    }

    fn lex_number(&mut self, first: u8) -> (TokenKind, String) {
        let mut s = String::new();
        s.push(first as char);

        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                s.push(c as char);
                self.advance();
            } else {
                break;
            }
        }

        // Check for decimal or exponent
        let is_float = match (self.peek(), self.peek2()) {
            (Some(b'.'), Some(d)) if d.is_ascii_digit() => true,
            (Some(b'e'), _) | (Some(b'E'), _) => true,
            _ => false,
        };

        if is_float {
            if self.peek() == Some(b'.') {
                s.push('.');
                self.advance();
                while let Some(c) = self.peek() {
                    if c.is_ascii_digit() {
                        s.push(c as char);
                        self.advance();
                    } else {
                        break;
                    }
                }
            }

            if self.peek() == Some(b'e') || self.peek() == Some(b'E') {
                self.advance();
                // Parse exponent
                let mut exp_str = String::new();
                if self.peek() == Some(b'-') {
                    exp_str.push('-');
                    self.advance();
                } else if self.peek() == Some(b'+') {
                    self.advance();
                }
                while let Some(c) = self.peek() {
                    if c.is_ascii_digit() {
                        exp_str.push(c as char);
                        self.advance();
                    } else {
                        break;
                    }
                }
                // Compute the float
                let base: f64 = s.parse().unwrap_or(0.0);
                let exp: i32 = exp_str.parse().unwrap_or(0);
                let result = base * 10f64.powi(exp);
                // Check if it's an integer (no fractional part after scientific notation)
                if result.fract() == 0.0 && result.abs() < 9.007199254740992e15 {
                    // Return as int
                    let i = result as i64;
                    let repr = format!("{}", i);
                    return (TokenKind::Int(i), repr);
                } else {
                    let repr = format!("{}", result);
                    return (TokenKind::Float(result), repr);
                }
            }

            let val: f64 = s.parse().unwrap_or(0.0);
            // Check if whole number
            if val.fract() == 0.0 && val.abs() < 9.007199254740992e15 {
                // still a float
                (TokenKind::Float(val), format!("{}", val))
            } else {
                (TokenKind::Float(val), format!("{}", val))
            }
        } else {
            let val: i64 = s.parse().unwrap_or(0);
            (TokenKind::Int(val), s)
        }
    }

    fn lex_ident_or_keyword(&mut self, first: u8) -> (TokenKind, String) {
        let mut s = String::new();
        s.push(first as char);

        while let Some(c) = self.peek() {
            if c.is_ascii_alphanumeric() || c == b'_' {
                s.push(c as char);
                self.advance();
            } else {
                break;
            }
        }

        let kind = match s.as_str() {
            "nil" => TokenKind::Nil,
            "true" => TokenKind::True,
            "false" => TokenKind::False,
            "let" => TokenKind::Let,
            "function" => TokenKind::Function,
            "if" => TokenKind::If,
            "then" => TokenKind::Then,
            "else" => TokenKind::Else,
            "elseif" => TokenKind::ElseIf,
            "end" => TokenKind::End,
            "while" => TokenKind::While,
            "do" => TokenKind::Do,
            "for" => TokenKind::For,
            "in" => TokenKind::In,
            "return" => TokenKind::Return,
            "break" => TokenKind::Break,
            "and" => TokenKind::And,
            "or" => TokenKind::Or,
            "not" => TokenKind::Not,
            _ => TokenKind::Ident(s.clone()),
        };

        (kind, s)
    }

    // Lex a command word (in command block context)
    fn lex_cmd_word(&mut self, errors: &mut Vec<String>) -> Option<(String, String)> {
        // Returns (value, display)
        // A command word can contain: regular chars, $var, ${var}, globs (*, ?), ~ 
        // and single/double quoted strings
        let mut value = String::new();
        let mut raw = String::new();
        let mut empty = true;

        loop {
            match self.peek() {
                Some(b'"') => {
                    empty = false;
                    self.advance();
                    raw.push('"');
                    // Parse double-quoted string
                    loop {
                        match self.peek() {
                            None | Some(b'"') => {
                                if self.peek() == Some(b'"') {
                                    self.advance();
                                    raw.push('"');
                                }
                                break;
                            }
                            Some(b'\\') => {
                                self.advance();
                                raw.push('\\');
                                match self.peek() {
                                    Some(b'n') => { self.advance(); value.push('\n'); raw.push('n'); }
                                    Some(b't') => { self.advance(); value.push('\t'); raw.push('t'); }
                                    Some(b'0') => { self.advance(); value.push('\0'); raw.push('0'); }
                                    Some(b'\\') => { self.advance(); value.push('\\'); raw.push('\\'); }
                                    Some(b'"') => { self.advance(); value.push('"'); raw.push('"'); }
                                    Some(b'\'') => { self.advance(); value.push('\''); raw.push('\''); }
                                    Some(b'$') => { self.advance(); value.push('$'); raw.push('$'); }
                                    Some(c) => {
                                        let ch = c as char;
                                        let esc_col = self.col;
                                        self.advance();
                                        raw.push(ch);
                                        errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                                            self.path, self.line + 1, esc_col - 1, ch));
                                        value.push(ch);
                                    }
                                    None => break,
                                }
                            }
                            Some(c) => {
                                let ch = c as char;
                                self.advance();
                                value.push(ch);
                                raw.push(ch);
                            }
                        }
                    }
                }
                Some(b'\'') => {
                    empty = false;
                    self.advance();
                    raw.push('\'');
                    // Single-quoted: everything literal except \' and \\
                    loop {
                        match self.peek() {
                            None | Some(b'\'') => {
                                if self.peek() == Some(b'\'') {
                                    self.advance();
                                    raw.push('\'');
                                }
                                break;
                            }
                            Some(b'\\') => {
                                self.advance();
                                raw.push('\\');
                                match self.peek() {
                                    Some(b'\'') => { self.advance(); value.push('\''); raw.push('\''); }
                                    Some(b'\\') => { self.advance(); value.push('\\'); raw.push('\\'); }
                                    Some(b'n') => { self.advance(); value.push('\n'); raw.push('n'); }
                                    Some(b't') => { self.advance(); value.push('\t'); raw.push('t'); }
                                    Some(b'0') => { self.advance(); value.push('\0'); raw.push('0'); }
                                    Some(c) => {
                                        let ch = c as char;
                                        let esc_col = self.col;
                                        self.advance();
                                        raw.push(ch);
                                        errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                                            self.path, self.line + 1, esc_col - 1, ch));
                                        value.push(ch);
                                    }
                                    None => break,
                                }
                            }
                            Some(c) => {
                                let ch = c as char;
                                self.advance();
                                value.push(ch);
                                raw.push(ch);
                            }
                        }
                    }
                }
                Some(c) if is_cmd_word_char(c) => {
                    empty = false;
                    let ch = c as char;
                    self.advance();
                    value.push(ch);
                    raw.push(ch);
                }
                _ => break,
            }
        }

        if empty { None } else { Some((value, raw)) }
    }
}

fn is_cmd_word_char(c: u8) -> bool {
    !matches!(c, b' ' | b'\t' | b'\n' | b'\r' | b';' | b'|' | b'>' | b'<' | b'{' | b'}' | b'$' | b'#' | b'"' | b'\'')
}

// The main lexing function
// Returns (tokens_for_lex_display, parse_tokens, errors)
pub fn lex(source: &str, path: &str) -> (Vec<LexToken>, Vec<String>) {
    let mut lexer = Lexer::new(source, path);
    let mut tokens = Vec::new();
    let mut errors = Vec::new();

    lex_tokens(&mut lexer, &mut tokens, &mut errors, false);

    (tokens, errors)
}

fn lex_tokens(lexer: &mut Lexer, tokens: &mut Vec<LexToken>, errors: &mut Vec<String>, in_cmd: bool) {
    loop {
        lexer.skip_whitespace_and_comments();

        let start_line = lexer.line;
        let start_col = lexer.col;

        match lexer.peek() {
            None => {
                // EOF
                tokens.push(LexToken {
                    path: lexer.path.clone(),
                    token: Token {
                        kind: TokenKind::Eof,
                        line: start_line,
                        col: start_col,
                        source_repr: "<eof>".to_string(),
                    }
                });
                break;
            }
            Some(c) => {
                let (kind, repr) = lex_token(lexer, c, errors, in_cmd);
                tokens.push(LexToken {
                    path: lexer.path.clone(),
                    token: Token {
                        kind,
                        line: start_line,
                        col: start_col,
                        source_repr: repr,
                    }
                });
            }
        }
    }
}

fn lex_token(lexer: &mut Lexer, c: u8, errors: &mut Vec<String>, in_cmd: bool) -> (TokenKind, String) {
    match c {
        b'+' => {
            lexer.advance();
            if lexer.peek() == Some(b'+') {
                lexer.advance();
                (TokenKind::PlusPlus, "++".to_string())
            } else {
                (TokenKind::Plus, "+".to_string())
            }
        }
        b'-' => {
            lexer.advance();
            (TokenKind::Minus, "-".to_string())
        }
        b'*' => {
            lexer.advance();
            (TokenKind::Star, "*".to_string())
        }
        b'/' => {
            lexer.advance();
            (TokenKind::Slash, "/".to_string())
        }
        b'%' => {
            lexer.advance();
            (TokenKind::Percent, "%".to_string())
        }
        b'=' => {
            lexer.advance();
            if lexer.peek() == Some(b'=') {
                lexer.advance();
                (TokenKind::Eq, "==".to_string())
            } else {
                (TokenKind::Assign, "=".to_string())
            }
        }
        b'!' => {
            lexer.advance();
            if lexer.peek() == Some(b'=') {
                lexer.advance();
                (TokenKind::NotEq, "!=".to_string())
            } else {
                errors.push(format!("{} (line {}, column {}) - unexpected '!'",
                    lexer.path, lexer.line + 1, lexer.col - 1));
                (TokenKind::Eof, "!".to_string()) // Error token
            }
        }
        b'<' => {
            lexer.advance();
            if lexer.peek() == Some(b'=') {
                lexer.advance();
                (TokenKind::LtEq, "<=".to_string())
            } else if lexer.peek() == Some(b'<') {
                lexer.advance();
                (TokenKind::StdinHeredoc, "<<".to_string())
            } else {
                (TokenKind::Lt, "<".to_string())
            }
        }
        b'>' => {
            lexer.advance();
            if lexer.peek() == Some(b'=') {
                lexer.advance();
                (TokenKind::GtEq, ">=".to_string())
            } else if lexer.peek() == Some(b'>') {
                lexer.advance();
                (TokenKind::Append, ">>".to_string())
            } else {
                (TokenKind::Arrow, ">".to_string())
            }
        }
        b'(' => {
            lexer.advance();
            (TokenKind::LParen, "(".to_string())
        }
        b')' => {
            lexer.advance();
            (TokenKind::RParen, ")".to_string())
        }
        b'[' => {
            lexer.advance();
            (TokenKind::LBracket, "[".to_string())
        }
        b']' => {
            lexer.advance();
            (TokenKind::RBracket, "]".to_string())
        }
        b'{' => {
            lexer.advance();
            (TokenKind::LBrace, "{".to_string())
        }
        b'}' => {
            lexer.advance();
            (TokenKind::RBrace, "}".to_string())
        }
        b'@' => {
            lexer.advance();
            if lexer.peek() == Some(b'[') {
                lexer.advance();
                (TokenKind::AtLBracket, "@[".to_string())
            } else {
                errors.push(format!("{} (line {}, column {}) - unexpected '@'",
                    lexer.path, lexer.line + 1, lexer.col - 1));
                (TokenKind::Eof, "@".to_string())
            }
        }
        b',' => {
            lexer.advance();
            (TokenKind::Comma, ",".to_string())
        }
        b':' => {
            lexer.advance();
            (TokenKind::Colon, ":".to_string())
        }
        b'.' => {
            lexer.advance();
            (TokenKind::Dot, ".".to_string())
        }
        b';' => {
            lexer.advance();
            (TokenKind::Semicolon, ";".to_string())
        }
        b'|' => {
            lexer.advance();
            (TokenKind::Pipe, "|".to_string())
        }
        b'?' => {
            lexer.advance();
            (TokenKind::Question, "?".to_string())
        }
        b'$' => {
            lexer.advance();
            if lexer.peek() == Some(b'{') {
                lexer.advance();
                (TokenKind::DollarLBrace, "${".to_string())
            } else {
                errors.push(format!("{} (line {}, column {}) - unexpected '$'",
                    lexer.path, lexer.line + 1, lexer.col - 1));
                (TokenKind::Eof, "$".to_string())
            }
        }
        b'&' => {
            lexer.advance();
            if lexer.peek() == Some(b'{') {
                lexer.advance();
                (TokenKind::AmpersandLBrace, "&{".to_string())
            } else {
                errors.push(format!("{} (line {}, column {}) - unexpected '&'",
                    lexer.path, lexer.line + 1, lexer.col - 1));
                (TokenKind::Eof, "&".to_string())
            }
        }
        b'"' => {
            lexer.advance();
            let start_repr = lexer.col - 1;
            // Need to re-lex the string with raw capture
            let mut s = String::new();
            let mut raw = String::from("\"");
            loop {
                match lexer.peek() {
                    None => {
                        errors.push(format!("{} (line {}, column {}) - unterminated string",
                            lexer.path, lexer.line + 1, start_repr));
                        break;
                    }
                    Some(b'"') => {
                        lexer.advance();
                        raw.push('"');
                        break;
                    }
                    Some(b'\\') => {
                        let esc_col = lexer.col;
                        lexer.advance();
                        raw.push('\\');
                        match lexer.peek() {
                            Some(b'n') => { lexer.advance(); s.push('\n'); raw.push('n'); }
                            Some(b't') => { lexer.advance(); s.push('\t'); raw.push('t'); }
                            Some(b'0') => { lexer.advance(); s.push('\0'); raw.push('0'); }
                            Some(b'\\') => { lexer.advance(); s.push('\\'); raw.push('\\'); }
                            Some(b'"') => { lexer.advance(); s.push('"'); raw.push('"'); }
                            Some(b'\'') => { lexer.advance(); s.push('\''); raw.push('\''); }
                            Some(cc) => {
                                let ch = cc as char;
                                lexer.advance();
                                raw.push(ch);
                                errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                                    lexer.path, lexer.line + 1, esc_col - 1, ch));
                                // Don't add to s
                            }
                            None => break,
                        }
                    }
                    Some(cc) => {
                        let ch = cc as char;
                        lexer.advance();
                        s.push(ch);
                        raw.push(ch);
                    }
                }
            }
            (TokenKind::Str(s), raw)
        }
        b'\'' => {
            lexer.advance();
            let start_col = lexer.col - 1;
            // Char literal
            let mut raw = String::from("'");
            let byte = match lexer.peek() {
                Some(b'\\') => {
                    lexer.advance();
                    raw.push('\\');
                    match lexer.peek() {
                        Some(b'n') => { lexer.advance(); raw.push('n'); b'\n' }
                        Some(b't') => { lexer.advance(); raw.push('t'); b'\t' }
                        Some(b'0') => { lexer.advance(); raw.push('0'); b'\0' }
                        Some(b'\\') => { lexer.advance(); raw.push('\\'); b'\\' }
                        Some(b'\'') => { lexer.advance(); raw.push('\''); b'\'' }
                        Some(b'"') => { lexer.advance(); raw.push('"'); b'"' }
                        Some(cc) => {
                            let ch = cc as char;
                            let esc_col = lexer.col;
                            lexer.advance();
                            raw.push(ch);
                            // consume rest until '
                            while let Some(ccc) = lexer.peek() {
                                if ccc == b'\'' { lexer.advance(); break; }
                                lexer.advance();
                            }
                            errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                                lexer.path, lexer.line + 1, esc_col - 1, ch));
                            return (TokenKind::Char(0), raw);
                        }
                        None => {
                            errors.push(format!("{} (line {}, column {}) - unterminated char",
                                lexer.path, lexer.line + 1, start_col));
                            return (TokenKind::Char(0), raw);
                        }
                    }
                }
                Some(cc) => {
                    let b = cc;
                    lexer.advance();
                    raw.push(b as char);
                    b
                }
                None => {
                    errors.push(format!("{} (line {}, column {}) - unterminated char",
                        lexer.path, lexer.line + 1, start_col));
                    return (TokenKind::Char(0), raw);
                }
            };

            match lexer.peek() {
                Some(b'\'') => {
                    lexer.advance();
                    raw.push('\'');
                }
                _ => {
                    errors.push(format!("{} (line {}, column {}) - unterminated char literal",
                        lexer.path, lexer.line + 1, start_col));
                }
            }

            (TokenKind::Char(byte), raw)
        }
        c if c.is_ascii_digit() => {
            lexer.advance();
            let (kind, repr) = lexer.lex_number(c);
            (kind, repr)
        }
        c if c.is_ascii_alphabetic() || c == b'_' => {
            lexer.advance();
            let (kind, repr) = lexer.lex_ident_or_keyword(c);
            (kind, repr)
        }
        c => {
            lexer.advance();
            let ch = c as char;
            errors.push(format!("{} (line {}, column {}) - unexpected '{}'",
                lexer.path, lexer.line + 1, lexer.col - 1, ch));
            (TokenKind::Eof, ch.to_string()) // Error
        }
    }
}
