// AST for Hush

#[derive(Debug, Clone)]
pub struct Pos {
    pub line: usize,   // 0-indexed
    pub col: usize,
    pub file: String,
}

impl Pos {
    pub fn fmt(&self) -> String {
        format!("{} (line {}, column {})", self.file, self.line + 1, self.col)
    }
}

impl std::fmt::Display for Pos {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{}", self.fmt())
    }
}

#[derive(Debug, Clone)]
pub struct Program {
    pub body: Vec<Stmt>,
}

#[derive(Debug, Clone)]
pub enum Stmt {
    Let {
        name: String,
        value: Option<Expr>,
        pos: Pos,
    },
    Assign {
        target: AssignTarget,
        value: Expr,
        pos: Pos,
    },
    ExprStmt(Expr),
    Return(Option<Expr>, Pos),
    Break(Pos),
    CmdBlock(CmdBlock, Pos),
}

#[derive(Debug, Clone)]
pub enum AssignTarget {
    Ident(String, Pos),
    Index(Box<Expr>, Box<Expr>, Pos),
    Field(Box<Expr>, String, Pos),
}

#[derive(Debug, Clone)]
pub enum Expr {
    Nil(Pos),
    True(Pos),
    False(Pos),
    Int(i64, Pos),
    Float(f64, Pos),
    Str(String, Pos),
    Char(u8, Pos),
    Ident(String, Pos),
    Unary { op: UnaryOp, operand: Box<Expr>, pos: Pos },
    Binary { op: BinOp, left: Box<Expr>, right: Box<Expr>, pos: Pos },
    Array(Vec<Expr>, Pos),
    Dict(Vec<(String, Expr)>, Pos),
    Function { params: Vec<String>, body: Vec<Stmt>, pos: Pos },
    Call { callee: Box<Expr>, args: Vec<Expr>, pos: Pos },
    MethodCall { obj: Box<Expr>, method: String, args: Vec<Expr>, pos: Pos },
    Index { obj: Box<Expr>, key: Box<Expr>, pos: Pos },
    Field { obj: Box<Expr>, field: String, pos: Pos },
    If { cond: Box<Expr>, then_body: Vec<Stmt>, elseif_clauses: Vec<(Expr, Vec<Stmt>)>, else_body: Option<Vec<Stmt>>, pos: Pos },
    While { cond: Box<Expr>, body: Vec<Stmt>, pos: Pos },
    For { var: String, iter: Box<Expr>, body: Vec<Stmt>, pos: Pos },
    CmdCapture(CmdBlock, Pos),
    AsyncCmd(CmdBlock, Pos),
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum UnaryOp {
    Neg,
    Not,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum BinOp {
    Add, Sub, Mul, Div, Mod,
    Eq, NotEq, Lt, LtEq, Gt, GtEq,
    And, Or,
    Concat, // ++
}

// Command block
#[derive(Debug, Clone)]
pub struct CmdBlock {
    pub cmds: Vec<CmdSeq>,
}

// A sequence of commands separated by ';'
#[derive(Debug, Clone)]
pub struct CmdSeq {
    pub pipeline: CmdPipeline,
    pub allow_fail: bool,  // has ? at end
}

#[derive(Debug, Clone)]
pub struct CmdPipeline {
    pub cmds: Vec<Command>,
}

#[derive(Debug, Clone)]
pub struct Command {
    pub args: Vec<CmdWord>,
    pub redirects: Vec<Redirect>,
    pub allow_fail: bool, // has ? at end (in pipeline)
}

#[derive(Debug, Clone)]
pub enum Redirect {
    Out { fd: i32, target: CmdWord, append: bool },
    Err2Out,    // 2>1
    Out2Err,    // 1>2
    Stdin(String), // << 'content'
}

// A command word, which can be a mix of literal strings and variable references
#[derive(Debug, Clone)]
pub enum CmdWord {
    Literal(String),           // A literal string
    Variable(String, Pos),     // $var or ${var}
    Quoted(Vec<CmdWordPart>),  // double-quoted with possible expansions
    Unquoted(Vec<CmdWordPart>),// unquoted with possible expansions + globbing
    SingleQuoted(String),      // single-quoted literal
}

#[derive(Debug, Clone)]
pub enum CmdWordPart {
    Literal(String),
    Variable(String, Pos),
}

// AST display functions

pub fn print_stmt(stmt: &Stmt, indent: usize) {
    let tabs = "\t".repeat(indent);
    match stmt {
        Stmt::Let { name, value, .. } => {
            if let Some(val) = value {
                println!("{}let {} = {}", tabs, name, fmt_expr(val));
            } else {
                println!("{}let {} = nil", tabs, name);
            }
        }
        Stmt::Assign { target, value, .. } => {
            let t = fmt_assign_target(target);
            println!("{}{} = {}", tabs, t, fmt_expr(value));
        }
        Stmt::ExprStmt(e) => {
            println!("{}{}", tabs, fmt_expr(e));
        }
        Stmt::Return(val, _) => {
            if let Some(v) = val {
                println!("{}return {}", tabs, fmt_expr(v));
            } else {
                println!("{}return", tabs);
            }
        }
        Stmt::Break(_) => {
            println!("{}break", tabs);
        }
        Stmt::CmdBlock(block, _) => {
            print!("{}", fmt_cmd_block_stmt(block, indent));
        }
    }
}

fn fmt_assign_target(t: &AssignTarget) -> String {
    match t {
        AssignTarget::Ident(name, _) => name.clone(),
        AssignTarget::Index(obj, key, _) => format!("{}[{}]", fmt_expr(obj), fmt_expr(key)),
        AssignTarget::Field(obj, field, _) => format!("{}.{}", fmt_expr(obj), field),
    }
}

pub fn fmt_expr(e: &Expr) -> String {
    match e {
        Expr::Nil(_) => "nil".to_string(),
        Expr::True(_) => "true".to_string(),
        Expr::False(_) => "false".to_string(),
        Expr::Int(n, _) => format!("{}", n),
        Expr::Float(f, _) => {
            if f.fract() == 0.0 && f.is_finite() {
                format!("{:.1}", f)
            } else {
                format!("{}", f)
            }
        }
        Expr::Str(s, _) => format!("\"{}\"", escape_string(s)),
        Expr::Char(b, _) => format!("'{}'", *b as char),
        Expr::Ident(name, _) => name.clone(),
        Expr::Unary { op, operand, .. } => {
            match op {
                UnaryOp::Neg => format!("(-{})", fmt_expr(operand)),
                UnaryOp::Not => format!("(not {})", fmt_expr(operand)),
            }
        }
        Expr::Binary { op, left, right, .. } => {
            let op_str = match op {
                BinOp::Add => "+",
                BinOp::Sub => "-",
                BinOp::Mul => "*",
                BinOp::Div => "/",
                BinOp::Mod => "%",
                BinOp::Eq => "==",
                BinOp::NotEq => "!=",
                BinOp::Lt => "<",
                BinOp::LtEq => "<=",
                BinOp::Gt => ">",
                BinOp::GtEq => ">=",
                BinOp::And => "and",
                BinOp::Or => "or",
                BinOp::Concat => "++",
            };
            format!("({} {} {})", fmt_expr(left), op_str, fmt_expr(right))
        }
        Expr::Array(items, _) => {
            if items.is_empty() {
                return "[\n]".to_string(); // Will be handled specially in context
            }
            // Single line for small arrays, multi-line for bigger
            let parts: Vec<String> = items.iter().map(|i| fmt_expr(i)).collect();
            format!("[ {} ]", parts.join(", "))
        }
        Expr::Dict(pairs, _) => {
            if pairs.is_empty() {
                return "@[\n]".to_string();
            }
            let parts: Vec<String> = pairs.iter().map(|(k, v)| format!("{}: {}", k, fmt_expr(v))).collect();
            format!("@[ {} ]", parts.join(", "))
        }
        Expr::Function { params, body, pos } => {
            let params_str = params.join(", ");
            format!("function({})\n{}\tend",
                params_str,
                body.iter().map(|s| { let mut buf = String::new(); fmt_stmt_to_string(s, 1, &mut buf); buf }).collect::<Vec<_>>().join("")
            )
        }
        Expr::Call { callee, args, .. } => {
            let callee_str = fmt_expr(callee);
            let args_str: Vec<String> = args.iter().map(|a| fmt_expr(a)).collect();
            format!("{}({})", callee_str, args_str.join(", "))
        }
        Expr::MethodCall { obj, method, args, .. } => {
            let args_str: Vec<String> = args.iter().map(|a| fmt_expr(a)).collect();
            format!("{}.{}({})", fmt_expr(obj), method, args_str.join(", "))
        }
        Expr::Index { obj, key, .. } => {
            format!("{}[{}]", fmt_expr(obj), fmt_expr(key))
        }
        Expr::Field { obj, field, .. } => {
            format!("{}.{}", fmt_expr(obj), field)
        }
        Expr::If { cond, then_body, elseif_clauses, else_body, .. } => {
            let mut s = format!("if {} then\n", fmt_expr(cond));
            for stmt in then_body {
                let mut buf = String::new();
                fmt_stmt_to_string(stmt, 1, &mut buf);
                s.push_str(&buf);
            }
            for (econd, ebody) in elseif_clauses {
                s.push_str(&format!("elseif {} then\n", fmt_expr(econd)));
                for stmt in ebody {
                    let mut buf = String::new();
                    fmt_stmt_to_string(stmt, 1, &mut buf);
                    s.push_str(&buf);
                }
            }
            if let Some(else_b) = else_body {
                s.push_str("else\n");
                for stmt in else_b {
                    let mut buf = String::new();
                    fmt_stmt_to_string(stmt, 1, &mut buf);
                    s.push_str(&buf);
                }
            }
            s.push_str("end");
            s
        }
        Expr::While { cond, body, .. } => {
            let mut s = format!("while {} do\n", fmt_expr(cond));
            for stmt in body {
                let mut buf = String::new();
                fmt_stmt_to_string(stmt, 1, &mut buf);
                s.push_str(&buf);
            }
            s.push_str("end");
            s
        }
        Expr::For { var, iter, body, .. } => {
            let mut s = format!("for {} in {} do\n", var, fmt_expr(iter));
            for stmt in body {
                let mut buf = String::new();
                fmt_stmt_to_string(stmt, 1, &mut buf);
                s.push_str(&buf);
            }
            s.push_str("end");
            s
        }
        Expr::CmdCapture(block, _) => {
            format!("${{\n{}}}", fmt_cmd_block_inner(block, 1))
        }
        Expr::AsyncCmd(block, _) => {
            format!("&{{\n{}}}", fmt_cmd_block_inner(block, 1))
        }
    }
}

fn escape_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '\n' => result.push_str("\\n"),
            '\t' => result.push_str("\\t"),
            '\0' => result.push_str("\\0"),
            '\\' => result.push_str("\\\\"),
            '"' => result.push_str("\\\""),
            c => result.push(c),
        }
    }
    result
}

fn fmt_cmd_block_stmt(block: &CmdBlock, indent: usize) -> String {
    let tabs = "\t".repeat(indent);
    let mut s = format!("{}{{\n", tabs);
    for (i, seq) in block.cmds.iter().enumerate() {
        s.push_str(&format!("{}\t", tabs));
        s.push_str(&fmt_cmd_pipeline(&seq.pipeline));
        if seq.allow_fail {
            s.push_str(" ?");
        }
        if i + 1 < block.cmds.len() {
            s.push(';');
        }
        s.push('\n');
    }
    s.push_str(&format!("{}}}\n", tabs));
    s
}

fn fmt_cmd_block_inner(block: &CmdBlock, indent: usize) -> String {
    let tabs = "\t".repeat(indent);
    let mut s = String::new();
    for (i, seq) in block.cmds.iter().enumerate() {
        s.push_str(&tabs);
        s.push_str(&fmt_cmd_pipeline(&seq.pipeline));
        if seq.allow_fail {
            s.push_str(" ?");
        }
        if i + 1 < block.cmds.len() {
            s.push(';');
        }
        s.push('\n');
    }
    s
}

fn fmt_cmd_pipeline(pipeline: &CmdPipeline) -> String {
    let mut parts = Vec::new();
    for (i, cmd) in pipeline.cmds.iter().enumerate() {
        let mut s = fmt_command(cmd);
        if cmd.allow_fail && i + 1 < pipeline.cmds.len() {
            s.push_str(" ?");
        }
        parts.push(s);
    }
    parts.join(" | ")
}

fn fmt_command(cmd: &Command) -> String {
    let mut parts: Vec<String> = cmd.args.iter().map(|w| fmt_cmd_word_display(w)).collect();

    for redir in &cmd.redirects {
        match redir {
            Redirect::Out { fd, target, append } => {
                let op = if *append { ">>" } else { ">" };
                if *fd == 1 {
                    parts.push(format!("{}{}", op, fmt_cmd_word_display(target)));
                } else {
                    parts.push(format!("{}{}{}", fd, op, fmt_cmd_word_display(target)));
                }
            }
            Redirect::Err2Out => parts.push("2>1".to_string()),
            Redirect::Out2Err => parts.push("1>2".to_string()),
            Redirect::Stdin(s) => parts.push(format!("<<\"{}\"", escape_string(s))),
        }
    }

    parts.join(" ")
}

fn fmt_cmd_word_display(word: &CmdWord) -> String {
    match word {
        CmdWord::Literal(s) => format!("\"{}\"", escape_string(s)),
        CmdWord::Variable(name, _) => format!("\"${{{}}}\"", name),
        CmdWord::Quoted(parts) => {
            let mut s = String::from("\"");
            for part in parts {
                match part {
                    CmdWordPart::Literal(l) => s.push_str(&escape_string(l)),
                    CmdWordPart::Variable(name, _) => s.push_str(&format!("${{{}}}", name)),
                }
            }
            s.push('"');
            s
        }
        CmdWord::Unquoted(parts) => {
            let mut s = String::new();
            for part in parts {
                match part {
                    CmdWordPart::Literal(l) => s.push_str(l),
                    CmdWordPart::Variable(name, _) => s.push_str(&format!("${{{}}}", name)),
                }
            }
            s
        }
        CmdWord::SingleQuoted(s) => format!("'{}'", s),
    }
}

fn fmt_stmt_to_string(stmt: &Stmt, indent: usize, buf: &mut String) {
    let tabs = "\t".repeat(indent);
    match stmt {
        Stmt::Let { name, value, .. } => {
