pub fn fmt_expr(e: &Expr) -> String {
    match e {
        Expr::Nil(_) => "nil".to_string(),
        Expr::True(_) => "true".to_string(),
        Expr::False(_) => "false".to_string(),
        Expr::Int(n, _) => format!("{}", n),
        Expr::Float(f, _) => {
            if f.fract() == 0.0 && f.is_finite() {
                format!("{:.1}", f)
            } else {
                format!("{}", f)
            }
        }
        Expr::Str(s, _) => format!("\"{}\"", escape_string(s)),
        Expr::Char(b, _) => format!("'{}'", *b as char),
        Expr::Ident(name, _) => name.clone(),
        Expr::Unary { op, operand, .. } => {
            match op {
                UnaryOp::Neg => format!("(-{})", fmt_expr(operand)),
                UnaryOp::Not => format!("(not {})", fmt_expr(operand)),
            }
        }
        Expr::Binary { op, left, right, .. } => {
            let op_str = match op {
                BinOp::Add => "+",
                BinOp::Sub => "-",
                BinOp::Mul => "*",
                BinOp::Div => "/",
                BinOp::Mod => "%",
                BinOp::Eq => "==",
                BinOp::NotEq => "!=",
                BinOp::Lt => "<",
                BinOp::LtEq => "<=",
                BinOp::Gt => ">",
                BinOp::GtEq => ">=",
                BinOp::And => "and",
                BinOp::Or => "or",
                BinOp::Concat => "++",
            };
            format!("({} {} {})", fmt_expr(left), op_str, fmt_expr(right))
        }
        Expr::Array(items, _) => {
            if items.is_empty() {
                return "[\n]".to_string(); // Will be handled specially in context
            }
            // Single line for small arrays, multi-line for bigger
            let parts: Vec<String> = items.iter().map(|i| fmt_expr(i)).collect();
            format!("[ {} ]", parts.join(", "))
        }
        Expr::Dict(pairs, _) => {
            if pairs.is_empty() {
                return "@[\n]".to_string();
            }
            let parts: Vec<String> = pairs.iter().map(|(k, v)| format!("{}: {}", k, fmt_expr(v))).collect();
            format!("@[ {} ]", parts.join(", "))
        }
        Expr::Function { params, body, pos } => {
            let params_str = params.join(", ");
            format!("function({})\n{}\tend",
                params_str,
                body.iter().map(|s| { let mut buf = String::new(); fmt_stmt_to_string(s, 1, &mut buf); buf }).collect::<Vec<_>>().join("")
            )
        }
        Expr::Call { callee, args, .. } => {
            let callee_str = fmt_expr(callee);
            let args_str: Vec<String> = args.iter().map(|a| fmt_expr(a)).collect();
            format!("{}({})", callee_str, args_str.join(", "))
        }
        Expr::MethodCall { obj, method, args, .. } => {
            let args_str: Vec<String> = args.iter().map(|a| fmt_expr(a)).collect();
            format!("{}.{}({})", fmt_expr(obj), method, args_str.join(", "))
        }
        Expr::Index { obj, key, .. } => {
            format!("{}[{}]", fmt_expr(obj), fmt_expr(key))
        }
        Expr::Field { obj, field, .. } => {
            format!("{}.{}", fmt_expr(obj), field)
        }
        Expr::If { cond, then_body, elseif_clauses, else_body, .. } => {
            let mut s = format!("if {} then\n", fmt_expr(cond));
            for stmt in then_body {
                let mut buf = String::new();
                fmt_stmt_to_string(stmt, 1, &mut buf);
                s.push_str(&buf);
            }
            for (econd, ebody) in elseif_clauses {
                s.push_str(&format!("elseif {} then\n", fmt_expr(econd)));
                for stmt in ebody {
                    let mut buf = String::new();
                    fmt_stmt_to_string(stmt, 1, &mut buf);
                    s.push_str(&buf);
                }
            }
            if let Some(else_b) = else_body {
                s.push_str("else\n");
                for stmt in else_b {
                    let mut buf = String::new();
                    fmt_stmt_to_string(stmt, 1, &mut buf);
                    s.push_str(&buf);
                }
            }
            s.push_str("end");
            s
        }
        Expr::While { cond, body, .. } => {
            let mut s = format!("while {} do\n", fmt_expr(cond));
            for stmt in body {
                let mut buf = String::new();
                fmt_stmt_to_string(stmt, 1, &mut buf);
                s.push_str(&buf);
            }
            s.push_str("end");
            s
        }
        Expr::For { var, iter, body, .. } => {
            let mut s = format!("for {} in {} do\n", var, fmt_expr(iter));
            for stmt in body {
                let mut buf = String::new();
                fmt_stmt_to_string(stmt, 1, &mut buf);
                s.push_str(&buf);
            }
            s.push_str("end");
            s
        }
        Expr::CmdCapture(block, _) => {
            format!("${{\n{}}}", fmt_cmd_block_inner(block, 1))
        }
        Expr::AsyncCmd(block, _) => {
            format!("&{{\n{}}}", fmt_cmd_block_inner(block, 1))
        }
    }
}

fn escape_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '\n' => result.push_str("\\n"),
            '\t' => result.push_str("\\t"),
            '\0' => result.push_str("\\0"),
            '\\' => result.push_str("\\\\"),
            '"' => result.push_str("\\\""),
            c => result.push(c),
        }
    }
    result
}

fn fmt_cmd_block_stmt(block: &CmdBlock, indent: usize) -> String {
    let tabs = "\t".repeat(indent);
    let mut s = format!("{}{{\n", tabs);
    for (i, seq) in block.cmds.iter().enumerate() {
        s.push_str(&format!("{}\t", tabs));
        s.push_str(&fmt_cmd_pipeline(&seq.pipeline));
        if seq.allow_fail {
            s.push_str(" ?");
        }
        if i + 1 < block.cmds.len() {
            s.push(';');
        }
        s.push('\n');
    }
    s.push_str(&format!("{}}}\n", tabs));
    s
}

fn fmt_cmd_block_inner(block: &CmdBlock, indent: usize) -> String {
    let tabs = "\t".repeat(indent);
    let mut s = String::new();
    for (i, seq) in block.cmds.iter().enumerate() {
        s.push_str(&tabs);
        s.push_str(&fmt_cmd_pipeline(&seq.pipeline));
        if seq.allow_fail {
            s.push_str(" ?");
        }
        if i + 1 < block.cmds.len() {
            s.push(';');
        }
        s.push('\n');
    }
    s
}

fn fmt_cmd_pipeline(pipeline: &CmdPipeline) -> String {
    let mut parts = Vec::new();
    for (i, cmd) in pipeline.cmds.iter().enumerate() {
        let mut s = fmt_command(cmd);
        if cmd.allow_fail && i + 1 < pipeline.cmds.len() {
            s.push_str(" ?");
        }
        parts.push(s);
    }
    parts.join(" | ")
}

