}

fn fmt_cmd_word_display(word: &CmdWord) -> String {
    match word {
        CmdWord::Literal(s) => format!("\"{}\"", escape_string(s)),
        CmdWord::Variable(name, _) => format!("\"${{{}}}\"", name),
