                    CmdWordPart::Variable(name, _) => s.push_str(&format!("${{{}}}", name)),
                }
            }
            s
        }
        CmdWord::SingleQuoted(s) => format!("'{}'", s),
    }
}

fn fmt_stmt_to_string(stmt: &Stmt, indent: usize, buf: &mut String) {
