        Expr::Ident(name, _) => name.clone(),
        Expr::Unary { op, operand, .. } => {
            match op {
                UnaryOp::Neg => format!("(-{})", fmt_expr(operand)),
                UnaryOp::Not => format!("(not {})", fmt_expr(operand)),
            }
        }
        Expr::Binary { op, left, right, .. } => {
            let op_str = match op {
                BinOp::Add => "+",
                BinOp::Sub => "-",
                BinOp::Mul => "*",
                BinOp::Div => "/",
                BinOp::Mod => "%",
                BinOp::Eq => "==",
                BinOp::NotEq => "!=",
                BinOp::Lt => "<",
                BinOp::LtEq => "<=",
                BinOp::Gt => ">",
                BinOp::GtEq => ">=",
                BinOp::And => "and",
                BinOp::Or => "or",
                BinOp::Concat => "++",
            };
            format!("({} {} {})", fmt_expr(left), op_str, fmt_expr(right))
        }
        Expr::Array(items, _) => {
            if items.is_empty() {
