        }
        Expr::Dict(pairs, _) => {
            if pairs.is_empty() {
                return "@[\n]".to_string();
            }
            let parts: Vec<String> = pairs.iter().map(|(k, v)| format!("{}: {}", k, fmt_expr(v))).collect();
            format!("@[ {} ]", parts.join(", "))
        }
