fn fmt_stmt_to_string(stmt: &Stmt, indent: usize, buf: &mut String) {
    let tabs = "\t".repeat(indent);
    match stmt {
        Stmt::Let { name, value, .. } => {
            if let Some(val) = value {
                buf.push_str(&format!("{}let {} = {}\n", tabs, name, fmt_expr(val)));
            } else {
                buf.push_str(&format!("{}let {} = nil\n", tabs, name));
            }
        }
        Stmt::Assign { target, value, .. } => {
            buf.push_str(&format!("{}{} = {}\n", tabs, fmt_assign_target(target), fmt_expr(value)));
        }
        Stmt::ExprStmt(e) => {
            buf.push_str(&format!("{}{}\n", tabs, fmt_expr(e)));
        }
        Stmt::Return(val, _) => {
            if let Some(v) = val {
                buf.push_str(&format!("{}return {}\n", tabs, fmt_expr(v)));
            } else {
                buf.push_str(&format!("{}return\n", tabs));
            }
        }
        Stmt::Break(_) => {
            buf.push_str(&format!("{}break\n", tabs));
        }
        Stmt::CmdBlock(block, _) => {
            buf.push_str(&fmt_cmd_block_stmt(block, indent));
        }
    }
}
