pub fn lex(source: &str, path: &str) -> (Vec<Token>, Vec<String>) {
    let mut lexer = Lexer {
        source: source.as_bytes().to_vec(),
        pos: 0,
        line: 0,
        col: 0,
        path: path.to_string(),
