struct Lexer {
    source: Vec<u8>,
    pos: usize,
    line: usize,
    col: usize,
    path: String,
}

impl Lexer {
    fn peek(&self) -> Option<u8> {
        self.source.get(self.pos).copied()
    }

    fn peek2(&self) -> Option<u8> {
        self.source.get(self.pos + 1).copied()
    }

    fn advance(&mut self) -> Option<u8> {
        let c = self.source.get(self.pos).copied()?;
        self.pos += 1;
        if c == b'\n' {
            self.line += 1;
            self.col = 0;
        } else {
            self.col += 1;
        }
        Some(c)
    }

    fn skip_whitespace_comments(&mut self) {
        loop {
            match self.peek() {
                Some(b' ') | Some(b'\t') | Some(b'\r') | Some(b'\n') => { self.advance(); }
                Some(b'#') => {
                    while self.peek().map_or(false, |c| c != b'\n') {
                        self.advance();
                    }
                }
                _ => break,
            }
        }
    }

    fn lex_normal(&mut self, tokens: &mut Vec<Token>, errors: &mut Vec<String>) {
        loop {
            self.skip_whitespace_comments();

            match self.peek() {
                None => {
                    tokens.push(Token {
                        kind: TokenKind::Eof,
                        line: self.line,
                        col: self.col,
                        display: String::new(),
                    });
                    break;
                }
                Some(c) => {
                    let line = self.line;
                    let col = self.col;

                    if let Some((kind, display)) = self.lex_one_token(c, false, errors) {
                        tokens.push(Token { kind, line, col, display });

                        // After { or ${ or &{, switch to command context
                        // We'll handle this in the parser
                    }
                }
            }
        }
    }

    fn lex_one_token(&mut self, c: u8, in_cmd: bool, errors: &mut Vec<String>) -> Option<(TokenKind, String)> {
        match c {
            b'+' => {
                self.advance();
                if self.peek() == Some(b'+') {
                    self.advance();
                    Some((TokenKind::PlusPlus, "++".to_string()))
                } else {
                    Some((TokenKind::Plus, "+".to_string()))
                }
            }
            b'-' => {
                self.advance();
                Some((TokenKind::Minus, "-".to_string()))
            }
            b'*' => {
                self.advance();
                Some((TokenKind::Star, "*".to_string()))
            }
            b'/' => {
                self.advance();
                Some((TokenKind::Slash, "/".to_string()))
            }
            b'%' => {
                self.advance();
                Some((TokenKind::Percent, "%".to_string()))
            }
            b'=' => {
                self.advance();
                if self.peek() == Some(b'=') {
                    self.advance();
                    Some((TokenKind::Eq, "==".to_string()))
                } else {
                    Some((TokenKind::Assign, "=".to_string()))
                }
            }
            b'!' => {
                self.advance();
                if self.peek() == Some(b'=') {
                    self.advance();
                    Some((TokenKind::NotEq, "!=".to_string()))
                } else {
                    let col = self.col - 1;
                    errors.push(format!("{} (line {}, column {}) - unexpected '!'",
                        self.path, self.line + 1, col));
                    Some((TokenKind::Eof, "!".to_string()))
                }
            }
            b'<' => {
                self.advance();
                if self.peek() == Some(b'=') {
                    self.advance();
                    Some((TokenKind::LtEq, "<=".to_string()))
                } else if self.peek() == Some(b'<') {
                    self.advance();
                    Some((TokenKind::StdinHeredoc, "<<".to_string()))
                } else {
                    Some((TokenKind::Lt, "<".to_string()))
                }
            }
            b'>' => {
                self.advance();
                if self.peek() == Some(b'=') {
                    self.advance();
                    Some((TokenKind::GtEq, ">=".to_string()))
                } else if self.peek() == Some(b'>') {
                    self.advance();
                    Some((TokenKind::Append, ">>".to_string()))
                } else {
                    Some((TokenKind::Arrow, ">".to_string()))
                }
            }
            b'(' => { self.advance(); Some((TokenKind::LParen, "(".to_string())) }
            b')' => { self.advance(); Some((TokenKind::RParen, ")".to_string())) }
            b'[' => { self.advance(); Some((TokenKind::LBracket, "[".to_string())) }
            b']' => { self.advance(); Some((TokenKind::RBracket, "]".to_string())) }
            b'{' => { self.advance(); Some((TokenKind::LBrace, "{".to_string())) }
            b'}' => { self.advance(); Some((TokenKind::RBrace, "}".to_string())) }
            b'@' => {
                self.advance();
                if self.peek() == Some(b'[') {
                    self.advance();
                    Some((TokenKind::AtLBracket, "@[".to_string()))
                } else {
                    let col = self.col - 1;
                    errors.push(format!("{} (line {}, column {}) - unexpected '@'",
                        self.path, self.line + 1, col));
                    Some((TokenKind::Eof, "@".to_string()))
                }
            }
            b',' => { self.advance(); Some((TokenKind::Comma, ",".to_string())) }
            b':' => { self.advance(); Some((TokenKind::Colon, ":".to_string())) }
            b'.' => { self.advance(); Some((TokenKind::Dot, ".".to_string())) }
            b';' => { self.advance(); Some((TokenKind::Semicolon, ";".to_string())) }
            b'|' => { self.advance(); Some((TokenKind::Pipe, "|".to_string())) }
            b'?' => { self.advance(); Some((TokenKind::Question, "?".to_string())) }
            b'$' => {
                self.advance();
                if self.peek() == Some(b'{') {
                    self.advance();
                    Some((TokenKind::DollarLBrace, "${".to_string()))
                } else {
                    let col = self.col - 1;
                    errors.push(format!("{} (line {}, column {}) - unexpected '$'",
                        self.path, self.line + 1, col));
                    Some((TokenKind::Eof, "$".to_string()))
                }
            }
            b'&' => {
                self.advance();
                if self.peek() == Some(b'{') {
                    self.advance();
                    Some((TokenKind::AmpersandLBrace, "&{".to_string()))
                } else {
                    let col = self.col - 1;
                    errors.push(format!("{} (line {}, column {}) - unexpected '&'",
                        self.path, self.line + 1, col));
                    Some((TokenKind::Eof, "&".to_string()))
                }
            }
            b'"' => {
                self.advance();
                let (s, raw) = self.lex_double_quoted(errors);
                Some((TokenKind::Str(s), raw))
            }
            b'\'' => {
                self.advance();
                let (b, raw) = self.lex_char(errors);
                if let Some(byte) = b {
                    Some((TokenKind::Char(byte), raw))
                } else {
                    None
                }
            }
            c if c.is_ascii_digit() => {
                self.advance();
                let (kind, raw) = self.lex_number(c);
                Some((kind, raw))
            }
            c if c.is_ascii_alphabetic() || c == b'_' => {
                self.advance();
                let (kind, raw) = self.lex_ident(c);
                Some((kind, raw))
            }
            c => {
                self.advance();
                let col = self.col - 1;
                errors.push(format!("{} (line {}, column {}) - unexpected '{}'",
                    self.path, self.line + 1, col, c as char));
                None
            }
        }
    }

    fn lex_double_quoted(&mut self, errors: &mut Vec<String>) -> (String, String) {
        let mut s = String::new();
        let mut raw = String::from("\"");
        let start_col = self.col.saturating_sub(1);

        loop {
            match self.peek() {
                None => {
                    errors.push(format!("{} (line {}, column {}) - unterminated string",
                        self.path, self.line + 1, start_col));
                    break;
                }
                Some(b'"') => {
                    self.advance();
                    raw.push('"');
                    break;
                }
                Some(b'\\') => {
                    let esc_col = self.col;
                    self.advance();
                    raw.push('\\');
                    match self.peek() {
                        Some(b'n') => { self.advance(); s.push('\n'); raw.push('n'); }
                        Some(b't') => { self.advance(); s.push('\t'); raw.push('t'); }
                        Some(b'0') => { self.advance(); s.push('\0'); raw.push('0'); }
                        Some(b'\\') => { self.advance(); s.push('\\'); raw.push('\\'); }
                        Some(b'"') => { self.advance(); s.push('"'); raw.push('"'); }
                        Some(b'\'') => { self.advance(); s.push('\''); raw.push('\''); }
                        Some(cc) => {
                            let ch = cc as char;
                            self.advance();
                            raw.push(ch);
                            errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                                self.path, self.line + 1, esc_col - 1, ch));
                        }
                        None => {}
                    }
                }
                Some(cc) => {
                    let ch = cc as char;
                    self.advance();
                    s.push(ch);
                    raw.push(ch);
                }
            }
        }

        (s, raw)
    }

    fn lex_char(&mut self, errors: &mut Vec<String>) -> (Option<u8>, String) {
        let start_col = self.col.saturating_sub(1);
        let mut raw = String::from("'");

        let byte = match self.peek() {
            Some(b'\\') => {
                self.advance();
                raw.push('\\');
                match self.peek() {
                    Some(b'n') => { self.advance(); raw.push('n'); b'\n' }
                    Some(b't') => { self.advance(); raw.push('t'); b'\t' }
                    Some(b'0') => { self.advance(); raw.push('0'); b'\0' }
                    Some(b'\\') => { self.advance(); raw.push('\\'); b'\\' }
                    Some(b'\'') => { self.advance(); raw.push('\''); b'\'' }
                    Some(b'"') => { self.advance(); raw.push('"'); b'"' }
                    Some(cc) => {
                        let ch = cc as char;
                        let esc_col = self.col;
                        self.advance();
                        raw.push(ch);
                        // consume rest until '
                        while let Some(c) = self.peek() {
                            if c == b'\'' { self.advance(); break; }
                            self.advance();
                        }
                        errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                            self.path, self.line + 1, esc_col - 1, ch));
                        return (None, raw);
                    }
                    None => {
                        errors.push(format!("{} (line {}, column {}) - unterminated char",
                            self.path, self.line + 1, start_col));
                        return (None, raw);
                    }
                }
            }
            Some(cc) => {
                let b = cc;
                self.advance();
                raw.push(b as char);
                b
            }
            None => {
                errors.push(format!("{} (line {}, column {}) - unterminated char",
                    self.path, self.line + 1, start_col));
                return (None, raw);
            }
        };

        match self.peek() {
            Some(b'\'') => {
                self.advance();
                raw.push('\'');
            }
            _ => {
                errors.push(format!("{} (line {}, column {}) - unterminated char literal",
                    self.path, self.line + 1, start_col));
            }
        }

        (Some(byte), raw)
    }

    fn lex_number(&mut self, first: u8) -> (TokenKind, String) {
        let mut s = String::new();
        s.push(first as char);

        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                s.push(c as char);
                self.advance();
            } else {
                break;
            }
        }

        // Check for decimal or exponent
        let has_dot = self.peek() == Some(b'.') && 
            self.source.get(self.pos + 1).map_or(false, |c| c.is_ascii_digit());
        let has_exp = matches!(self.peek(), Some(b'e') | Some(b'E'));

        if has_dot || has_exp {
            if has_dot {
                s.push('.');
                self.advance(); // consume '.'
                while let Some(c) = self.peek() {
                    if c.is_ascii_digit() {
                        s.push(c as char);
                        self.advance();
                    } else {
                        break;
                    }
                }
            }

            if matches!(self.peek(), Some(b'e') | Some(b'E')) {
                self.advance(); // consume 'e'
                let mut exp_s = String::new();
                if self.peek() == Some(b'-') {
                    exp_s.push('-');
                    self.advance();
                } else if self.peek() == Some(b'+') {
                    self.advance();
                }
                while let Some(c) = self.peek() {
                    if c.is_ascii_digit() {
                        exp_s.push(c as char);
                        self.advance();
                    } else {
                        break;
                    }
                }

                let base: f64 = s.parse().unwrap_or(0.0);
                let exp: i32 = exp_s.parse().unwrap_or(0);
                let result = base * 10f64.powi(exp);

                // If result is a whole number, return as int
                if result.fract() == 0.0 && result.is_finite() && result.abs() < 9.007199254740992e15 {
                    let i = result as i64;
                    return (TokenKind::Int(i), format!("{}", i));
                } else {
                    // Display the float value
                    let display = format!("{}", result);
                    return (TokenKind::Float(result), display);
                }
            }

            let val: f64 = s.parse().unwrap_or(0.0);
            let display = format!("{}", val);
            (TokenKind::Float(val), display)
        } else {
            let val: i64 = s.parse().unwrap_or(0);
            (TokenKind::Int(val), s)
        }
    }

    fn lex_ident(&mut self, first: u8) -> (TokenKind, String) {
        let mut s = String::new();
        s.push(first as char);

        while let Some(c) = self.peek() {
            if c.is_ascii_alphanumeric() || c == b'_' {
                s.push(c as char);
                self.advance();
            } else {
                break;
            }
        }

        let kind = match s.as_str() {
            "nil" => TokenKind::Nil,
            "true" => TokenKind::True,
            "false" => TokenKind::False,
            "let" => TokenKind::Let,
            "function" => TokenKind::Function,
            "if" => TokenKind::If,
            "then" => TokenKind::Then,
            "else" => TokenKind::Else,
            "elseif" => TokenKind::ElseIf,
            "end" => TokenKind::End,
            "while" => TokenKind::While,
            "do" => TokenKind::Do,
            "for" => TokenKind::For,
            "in" => TokenKind::In,
            "return" => TokenKind::Return,
            "break" => TokenKind::Break,
            "and" => TokenKind::And,
            "or" => TokenKind::Or,
            "not" => TokenKind::Not,
            _ => TokenKind::Ident(s.clone()),
        };

        (kind, s)
    }

    // Lex command words (in command block context)
    // Returns list of (parts, display_string) for each word
    pub fn lex_cmd_words(&mut self, errors: &mut Vec<String>) -> Vec<(Vec<CmdPart>, String)> {
        let mut words = Vec::new();

        loop {
            // skip spaces (not newlines)
            while matches!(self.peek(), Some(b' ') | Some(b'\t')) {
                self.advance();
            }

            match self.peek() {
                None | Some(b'\n') | Some(b'\r') | Some(b';') | Some(b'|') | Some(b'}') | Some(b'?') | Some(b'#') => break,
                Some(b'>') => break,
                Some(b'<') if self.peek2() != Some(b'<') => break,
                Some(b'<') if self.peek2() == Some(b'<') => break,
                _ => {}
            }

            // Lex one word
            if let Some(word) = self.lex_cmd_word(errors) {
                words.push(word);
            } else {
                break;
            }
        }

        words
    }

    fn lex_cmd_word(&mut self, errors: &mut Vec<String>) -> Option<(Vec<CmdPart>, String)> {
        let mut parts: Vec<CmdPart> = Vec::new();
        let mut display = String::new();
        let mut empty = true;

        loop {
            match self.peek() {
                None | Some(b' ') | Some(b'\t') | Some(b'\n') | Some(b'\r') 
                | Some(b';') | Some(b'|') | Some(b'}') | Some(b'?') | Some(b'#')
                | Some(b'>') => break,
                Some(b'<') if self.peek2() == Some(b'<') => break,
                Some(b'<') => break,
                Some(b'"') => {
                    empty = false;
                    self.advance();
                    display.push('"');
                    // Parse double-quoted with expansions
                    loop {
                        match self.peek() {
                            None | Some(b'"') => {
                                if self.peek() == Some(b'"') {
                                    self.advance();
                                    display.push('"');
                                }
                                break;
                            }
                            Some(b'$') => {
                                self.advance();
                                display.push('$');
                                if let Some(var_name) = self.lex_var_name() {
                                    let line = self.line;
                                    let col = self.col.saturating_sub(var_name.len());
                                    display.push_str(&format!("{{{}}}", var_name));
                                    // Merge or add part
                                    push_var_part(&mut parts, &var_name, line, col);
                                } else {
                                    // $ followed by non-var - treat as literal
                                    if let Some(c) = self.peek() {
                                        self.advance();
                                        display.push(c as char);
                                        push_lit_part(&mut parts, &(c as char).to_string());
                                    }
                                }
                            }
                            Some(b'\\') => {
                                let esc_col = self.col;
                                self.advance();
                                display.push('\\');
                                match self.peek() {
                                    Some(b'n') => { self.advance(); push_lit_part(&mut parts, "\n"); display.push('n'); }
                                    Some(b't') => { self.advance(); push_lit_part(&mut parts, "\t"); display.push('t'); }
                                    Some(b'0') => { self.advance(); push_lit_part(&mut parts, "\0"); display.push('0'); }
                                    Some(b'\\') => { self.advance(); push_lit_part(&mut parts, "\\"); display.push('\\'); }
                                    Some(b'"') => { self.advance(); push_lit_part(&mut parts, "\""); display.push('"'); }
                                    Some(b'\'') => { self.advance(); push_lit_part(&mut parts, "'"); display.push('\''); }
                                    Some(b'$') => { self.advance(); push_lit_part(&mut parts, "$"); display.push('$'); }
                                    Some(b' ') => { self.advance(); push_lit_part(&mut parts, " "); display.push(' '); }
                                    Some(cc) => {
                                        let ch = cc as char;
                                        self.advance();
                                        display.push(ch);
                                        errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                                            self.path, self.line + 1, esc_col - 1, ch));
                                        push_lit_part(&mut parts, &ch.to_string());
                                    }
                                    None => {}
                                }
                            }
                            Some(cc) => {
                                let ch = cc as char;
                                self.advance();
                                push_lit_part(&mut parts, &ch.to_string());
                                display.push(ch);
                            }
                        }
                    }
                }
                Some(b'\'') => {
                    empty = false;
                    self.advance();
                    display.push('\'');
                    // Single-quoted: no expansions, but escape sequences work
                    loop {
                        match self.peek() {
                            None | Some(b'\'') => {
                                if self.peek() == Some(b'\'') {
                                    self.advance();
