                        Some(b't') => { self.advance(); push_lit_part(&mut parts, "\t"); display.push_str("\\t"); }
                        Some(b'0') => { self.advance(); push_lit_part(&mut parts, "\0"); display.push_str("\\0"); }
                        Some(b'\\') => { self.advance(); push_lit_part(&mut parts, "\\"); display.push_str("\\\\"); }
                        Some(b'\'') => { self.advance(); push_lit_part(&mut parts, "'"); display.push_str("\\'"); }
