                self.advance();
                let col = self.col - 1;
                errors.push(format!("{} (line {}, column {}) - unexpected '{}'",
                    self.path, self.line + 1, col, c as char));
                None
            }
        }
    }

    fn lex_double_quoted(&mut self, errors: &mut Vec<String>) -> (String, String) {
        let mut s = String::new();
        let mut raw = String::from("\"");
        let start_col = self.col.saturating_sub(1);

        loop {
            match self.peek() {
                None => {
                    errors.push(format!("{} (line {}, column {}) - unterminated string",
                        self.path, self.line + 1, start_col));
                    break;
                }
                Some(b'"') => {
                    self.advance();
                    raw.push('"');
                    break;
                }
                Some(b'\\') => {
                    let esc_col = self.col;
                    self.advance();
                    raw.push('\\');
                    match self.peek() {
                        Some(b'n') => { self.advance(); s.push('\n'); raw.push('n'); }
                        Some(b't') => { self.advance(); s.push('\t'); raw.push('t'); }
                        Some(b'0') => { self.advance(); s.push('\0'); raw.push('0'); }
                        Some(b'\\') => { self.advance(); s.push('\\'); raw.push('\\'); }
                        Some(b'"') => { self.advance(); s.push('"'); raw.push('"'); }
                        Some(b'\'') => { self.advance(); s.push('\''); raw.push('\''); }
                        Some(cc) => {
                            let ch = cc as char;
                            self.advance();
                            raw.push(ch);
                            errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                                self.path, self.line + 1, esc_col - 1, ch));
                        }
                        None => {}
                    }
                }
                Some(cc) => {
                    let ch = cc as char;
                    self.advance();
                    s.push(ch);
                    raw.push(ch);
                }
            }
        }

        (s, raw)
    }

    fn lex_char(&mut self, errors: &mut Vec<String>) -> (Option<u8>, String) {
        let start_col = self.col.saturating_sub(1);
        let mut raw = String::from("'");

        let byte = match self.peek() {
            Some(b'\\') => {
                self.advance();
                raw.push('\\');
                match self.peek() {
                    Some(b'n') => { self.advance(); raw.push('n'); b'\n' }
                    Some(b't') => { self.advance(); raw.push('t'); b'\t' }
                    Some(b'0') => { self.advance(); raw.push('0'); b'\0' }
                    Some(b'\\') => { self.advance(); raw.push('\\'); b'\\' }
                    Some(b'\'') => { self.advance(); raw.push('\''); b'\'' }
                    Some(b'"') => { self.advance(); raw.push('"'); b'"' }
                    Some(cc) => {
                        let ch = cc as char;
                        let esc_col = self.col;
                        self.advance();
                        raw.push(ch);
                        // consume rest until '
                        while let Some(c) = self.peek() {
                            if c == b'\'' { self.advance(); break; }
                            self.advance();
                        }
                        errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                            self.path, self.line + 1, esc_col - 1, ch));
                        return (None, raw);
                    }
                    None => {
                        errors.push(format!("{} (line {}, column {}) - unterminated char",
                            self.path, self.line + 1, start_col));
                        return (None, raw);
                    }
                }
            }
            Some(cc) => {
                let b = cc;
                self.advance();
                raw.push(b as char);
                b
            }
            None => {
                errors.push(format!("{} (line {}, column {}) - unterminated char",
                    self.path, self.line + 1, start_col));
                return (None, raw);
            }
        };

        match self.peek() {
            Some(b'\'') => {
                self.advance();
                raw.push('\'');
            }
            _ => {
                errors.push(format!("{} (line {}, column {}) - unterminated char literal",
                    self.path, self.line + 1, start_col));
            }
        }

        (Some(byte), raw)
    }

    fn lex_number(&mut self, first: u8) -> (TokenKind, String) {
        let mut s = String::new();
        s.push(first as char);

        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                s.push(c as char);
                self.advance();
            } else {
                break;
            }
        }

        // Check for decimal or exponent
        let has_dot = self.peek() == Some(b'.') && 
            self.source.get(self.pos + 1).map_or(false, |c| c.is_ascii_digit());
        let has_exp = matches!(self.peek(), Some(b'e') | Some(b'E'));

        if has_dot || has_exp {
            if has_dot {
                s.push('.');
                self.advance(); // consume '.'
                while let Some(c) = self.peek() {
                    if c.is_ascii_digit() {
                        s.push(c as char);
                        self.advance();
                    } else {
                        break;
                    }
                }
            }

            if matches!(self.peek(), Some(b'e') | Some(b'E')) {
                self.advance(); // consume 'e'
                let mut exp_s = String::new();
                if self.peek() == Some(b'-') {
                    exp_s.push('-');
                    self.advance();
                } else if self.peek() == Some(b'+') {
                    self.advance();
                }
                while let Some(c) = self.peek() {
                    if c.is_ascii_digit() {
                        exp_s.push(c as char);
                        self.advance();
                    } else {
                        break;
                    }
                }

                let base: f64 = s.parse().unwrap_or(0.0);
                let exp: i32 = exp_s.parse().unwrap_or(0);
                let result = base * 10f64.powi(exp);

                // If result is a whole number, return as int
                if result.fract() == 0.0 && result.is_finite() && result.abs() < 9.007199254740992e15 {
                    let i = result as i64;
                    return (TokenKind::Int(i), format!("{}", i));
                } else {
                    // Display the float value
                    let display = format!("{}", result);
                    return (TokenKind::Float(result), display);
                }
            }

            let val: f64 = s.parse().unwrap_or(0.0);
            let display = format!("{}", val);
            (TokenKind::Float(val), display)
        } else {
            let val: i64 = s.parse().unwrap_or(0);
            (TokenKind::Int(val), s)
        }
    }

    fn lex_ident(&mut self, first: u8) -> (TokenKind, String) {
        let mut s = String::new();
        s.push(first as char);

        while let Some(c) = self.peek() {
            if c.is_ascii_alphanumeric() || c == b'_' {
                s.push(c as char);
                self.advance();
            } else {
                break;
            }
        }

        let kind = match s.as_str() {
            "nil" => TokenKind::Nil,
            "true" => TokenKind::True,
            "false" => TokenKind::False,
            "let" => TokenKind::Let,
            "function" => TokenKind::Function,
            "if" => TokenKind::If,
            "then" => TokenKind::Then,
            "else" => TokenKind::Else,
            "elseif" => TokenKind::ElseIf,
            "end" => TokenKind::End,
            "while" => TokenKind::While,
            "do" => TokenKind::Do,
            "for" => TokenKind::For,
            "in" => TokenKind::In,
            "return" => TokenKind::Return,
            "break" => TokenKind::Break,
            "and" => TokenKind::And,
            "or" => TokenKind::Or,
            "not" => TokenKind::Not,
            _ => TokenKind::Ident(s.clone()),
        };

        (kind, s)
    }

    // Lex command words (in command block context)
    // Returns list of (parts, display_string) for each word
    pub fn lex_cmd_words(&mut self, errors: &mut Vec<String>) -> Vec<(Vec<CmdPart>, String)> {
        let mut words = Vec::new();

        loop {
            // skip spaces (not newlines)
            while matches!(self.peek(), Some(b' ') | Some(b'\t')) {
                self.advance();
            }

            match self.peek() {
                None | Some(b'\n') | Some(b'\r') | Some(b';') | Some(b'|') | Some(b'}') | Some(b'?') | Some(b'#') => break,
                Some(b'>') => break,
                Some(b'<') if self.peek2() != Some(b'<') => break,
                Some(b'<') if self.peek2() == Some(b'<') => break,
                _ => {}
            }

            // Lex one word
            if let Some(word) = self.lex_cmd_word(errors) {
                words.push(word);
            } else {
                break;
            }
        }

        words
    }

    fn lex_cmd_word(&mut self, errors: &mut Vec<String>) -> Option<(Vec<CmdPart>, String)> {
        let mut parts: Vec<CmdPart> = Vec::new();
        let mut display = String::new();
        let mut empty = true;

        loop {
            match self.peek() {
                None | Some(b' ') | Some(b'\t') | Some(b'\n') | Some(b'\r') 
                | Some(b';') | Some(b'|') | Some(b'}') | Some(b'?') | Some(b'#')
                | Some(b'>') => break,
                Some(b'<') if self.peek2() == Some(b'<') => break,
                Some(b'<') => break,
                Some(b'"') => {
                    empty = false;
                    self.advance();
                    display.push('"');
                    // Parse double-quoted with expansions
                    loop {
                        match self.peek() {
                            None | Some(b'"') => {
                                if self.peek() == Some(b'"') {
                                    self.advance();
                                    display.push('"');
                                }
                                break;
                            }
                            Some(b'$') => {
                                self.advance();
                                display.push('$');
                                if let Some(var_name) = self.lex_var_name() {
                                    let line = self.line;
                                    let col = self.col.saturating_sub(var_name.len());
                                    display.push_str(&format!("{{{}}}", var_name));
                                    // Merge or add part
                                    push_var_part(&mut parts, &var_name, line, col);
                                } else {
                                    // $ followed by non-var - treat as literal
                                    if let Some(c) = self.peek() {
                                        self.advance();
                                        display.push(c as char);
                                        push_lit_part(&mut parts, &(c as char).to_string());
                                    }
                                }
                            }
                            Some(b'\\') => {
                                let esc_col = self.col;
                                self.advance();
                                display.push('\\');
                                match self.peek() {
                                    Some(b'n') => { self.advance(); push_lit_part(&mut parts, "\n"); display.push('n'); }
                                    Some(b't') => { self.advance(); push_lit_part(&mut parts, "\t"); display.push('t'); }
                                    Some(b'0') => { self.advance(); push_lit_part(&mut parts, "\0"); display.push('0'); }
                                    Some(b'\\') => { self.advance(); push_lit_part(&mut parts, "\\"); display.push('\\'); }
                                    Some(b'"') => { self.advance(); push_lit_part(&mut parts, "\""); display.push('"'); }
                                    Some(b'\'') => { self.advance(); push_lit_part(&mut parts, "'"); display.push('\''); }
                                    Some(b'$') => { self.advance(); push_lit_part(&mut parts, "$"); display.push('$'); }
                                    Some(b' ') => { self.advance(); push_lit_part(&mut parts, " "); display.push(' '); }
                                    Some(cc) => {
                                        let ch = cc as char;
                                        self.advance();
                                        display.push(ch);
                                        errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                                            self.path, self.line + 1, esc_col - 1, ch));
                                        push_lit_part(&mut parts, &ch.to_string());
                                    }
                                    None => {}
                                }
                            }
                            Some(cc) => {
                                let ch = cc as char;
                                self.advance();
                                push_lit_part(&mut parts, &ch.to_string());
                                display.push(ch);
                            }
                        }
                    }
                }
                Some(b'\'') => {
                    empty = false;
                    self.advance();
                    display.push('\'');
                    // Single-quoted: no expansions, but escape sequences work
                    loop {
                        match self.peek() {
                            None | Some(b'\'') => {
                                if self.peek() == Some(b'\'') {
                                    self.advance();
                                    display.push('\'');
                                }
                                break;
                            }
                            Some(b'\\') => {
                                let esc_col = self.col;
                                self.advance();
                                display.push('\\');
                                match self.peek() {
                                    Some(b'\'') => { self.advance(); push_lit_part(&mut parts, "'"); display.push('\''); }
                                    Some(b'\\') => { self.advance(); push_lit_part(&mut parts, "\\"); display.push('\\'); }
                                    Some(b'n') => { self.advance(); push_lit_part(&mut parts, "\n"); display.push('n'); }
                                    Some(b't') => { self.advance(); push_lit_part(&mut parts, "\t"); display.push('t'); }
                                    Some(b'0') => { self.advance(); push_lit_part(&mut parts, "\0"); display.push('0'); }
                                    Some(cc) => {
                                        let ch = cc as char;
                                        self.advance();
                                        display.push(ch);
                                        errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                                            self.path, self.line + 1, esc_col - 1, ch));
                                        push_lit_part(&mut parts, &ch.to_string());
                                    }
                                    None => break,
                                }
                            }
                            Some(cc) => {
                                let ch = cc as char;
                                self.advance();
                                push_lit_part(&mut parts, &ch.to_string());
                                display.push(ch);
                            }
                        }
                    }
                }
                Some(b'$') => {
                    self.advance();
                    display.push('$');
                    empty = false;
                    if let Some(var_name) = self.lex_var_name() {
                        let line = self.line;
                        let col = self.col.saturating_sub(var_name.len());
                        display.push_str(&format!("{{{}}}", var_name));
                        push_var_part(&mut parts, &var_name, line, col);
                    } else if self.peek() == Some(b'\'') {
                        // $' ... ' - dollar-single-quoted (backslash escapes)
                        self.advance();
                        display.push('\'');
                        loop {
                            match self.peek() {
                                None | Some(b'\'') => {
                                    if self.peek() == Some(b'\'') {
                                        self.advance();
                                        display.push('\'');
                                    }
                                    break;
                                }
                                Some(b'\\') => {
                                    self.advance();
                                    display.push('\\');
                                    match self.peek() {
                                        Some(b'\'') => { self.advance(); push_lit_part(&mut parts, "'"); display.push('\''); }
                                        Some(b'\\') => { self.advance(); push_lit_part(&mut parts, "\\"); display.push('\\'); }
                                        Some(b'n') => { self.advance(); push_lit_part(&mut parts, "\n"); display.push('n'); }
                                        Some(b't') => { self.advance(); push_lit_part(&mut parts, "\t"); display.push('t'); }
                                        Some(b'0') => { self.advance(); push_lit_part(&mut parts, "\0"); display.push('0'); }
                                        Some(cc) => {
                                            let ch = cc as char;
                                            self.advance();
                                            display.push(ch);
                                            push_lit_part(&mut parts, &ch.to_string());
                                        }
                                        None => break,
                                    }
                                }
                                Some(cc) => {
                                    let ch = cc as char;
                                    self.advance();
                                    push_lit_part(&mut parts, &ch.to_string());
                                    display.push(ch);
                                }
                            }
                        }
                    } else {
                        // literal $
                        push_lit_part(&mut parts, "$");
                    }
                }
                Some(b'\\') => {
                    let esc_col = self.col;
                    self.advance();
                    empty = false;
                    // Backslash in unquoted context
                    match self.peek() {
                        Some(b' ') => { self.advance(); push_lit_part(&mut parts, " "); display.push_str("\\ "); }
                        Some(b'n') => { self.advance(); push_lit_part(&mut parts, "\n"); display.push_str("\\n"); }
                        Some(b't') => { self.advance(); push_lit_part(&mut parts, "\t"); display.push_str("\\t"); }
                        Some(b'0') => { self.advance(); push_lit_part(&mut parts, "\0"); display.push_str("\\0"); }
                        Some(b'\\') => { self.advance(); push_lit_part(&mut parts, "\\"); display.push_str("\\\\"); }
                        Some(b'\'') => { self.advance(); push_lit_part(&mut parts, "'"); display.push_str("\\'"); }
                        Some(b'"') => { self.advance(); push_lit_part(&mut parts, "\""); display.push_str("\\\""); }
                        Some(cc) => {
                            let ch = cc as char;
                            self.advance();
                            display.push('\\');
                            display.push(ch);
                            errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                                self.path, self.line + 1, esc_col, ch));
                            push_lit_part(&mut parts, &ch.to_string());
                        }
                        None => {}
                    }
                }
                Some(cc) => {
                    let ch = cc as char;
                    self.advance();
                    empty = false;
                    push_lit_part(&mut parts, &ch.to_string());
                    display.push(ch);
                }
            }
        }

        if empty {
            None
        } else {
            Some((parts, display))
        }
    }

    fn lex_var_name(&mut self) -> Option<String> {
        if self.peek() == Some(b'{') {
            self.advance();
            let mut name = String::new();
            loop {
                match self.peek() {
                    Some(b'}') => {
                        self.advance();
                        break;
                    }
                    Some(c) if c.is_ascii_alphanumeric() || c == b'_' => {
                        name.push(c as char);
                        self.advance();
                    }
                    _ => break,
                }
            }
            if name.is_empty() { None } else { Some(name) }
        } else if self.peek().map_or(false, |c| c.is_ascii_alphabetic() || c == b'_') {
            let mut name = String::new();
            while let Some(c) = self.peek() {
                if c.is_ascii_alphanumeric() || c == b'_' {
                    name.push(c as char);
                    self.advance();
                } else {
                    break;
                }
            }
            if name.is_empty() { None } else { Some(name) }
        } else {
            None
        }
    }

    // Lex a heredoc string after <<
    pub fn lex_heredoc(&mut self) -> Option<String> {
        // Skip whitespace except newline
        while matches!(self.peek(), Some(b' ') | Some(b'\t')) {
            self.advance();
        }

        match self.peek() {
            Some(b'\'') => {
                self.advance();
                let mut s = String::new();
                loop {
                    match self.peek() {
                        Some(b'\'') => {
                            self.advance();
                            break;
                        }
                        Some(b'\\') => {
                            self.advance();
                            match self.peek() {
                                Some(b'\'') => { self.advance(); s.push('\''); }
                                Some(b'\\') => { self.advance(); s.push('\\'); }
                                Some(b'n') => { self.advance(); s.push('\n'); }
                                Some(c) => { s.push('\\'); s.push(c as char); self.advance(); }
                                None => break,
                            }
                        }
                        Some(c) => {
                            s.push(c as char);
                            self.advance();
                        }
                        None => break,
                    }
                }
                Some(s)
            }
            Some(b'"') => {
                self.advance();
                let mut s = String::new();
                loop {
                    match self.peek() {
                        Some(b'"') => {
                            self.advance();
                            break;
                        }
                        Some(b'\\') => {
                            self.advance();
                            match self.peek() {
                                Some(b'"') => { self.advance(); s.push('"'); }
                                Some(b'\\') => { self.advance(); s.push('\\'); }
                                Some(b'n') => { self.advance(); s.push('\n'); }
                                Some(c) => { s.push('\\'); s.push(c as char); self.advance(); }
                                None => break,
                            }
                        }
                        Some(c) => {
                            s.push(c as char);
                            self.advance();
                        }
                        None => break,
                    }
                }
                Some(s)
            }
            _ => {
                // Unquoted heredoc - read word
                let mut s = String::new();
                loop {
                    match self.peek() {
                        Some(c) if !matches!(c, b' ' | b'\t' | b'\n' | b';' | b'|' | b'}' | b'#') => {
                            s.push(c as char);
                            self.advance();
                        }
                        _ => break,
                    }
                }
                if s.is_empty() { None } else { Some(s) }
            }
        }
    }
}

fn push_lit_part(parts: &mut Vec<CmdPart>, s: &str) {
    if let Some(CmdPart::Literal(ref mut last)) = parts.last_mut() {
        last.push_str(s);
    } else {
        parts.push(CmdPart::Literal(s.to_string()));
    }
}

fn push_var_part(parts: &mut Vec<CmdPart>, name: &str, line: usize, col: usize) {
    parts.push(CmdPart::Var(name.to_string(), line, col));
}
