/// Parser for Hush language

use crate::lexer::{Token, TokenKind, CmdPart};
use crate::ast::*;

pub struct Parser<'a> {
    tokens: &'a [Token],
    pos: usize,
    path: String,
    errors: Vec<String>,
}

impl<'a> Parser<'a> {
    pub fn new(tokens: &'a [Token], path: &str) -> Self {
        Parser {
            tokens,
            pos: 0,
            path: path.to_string(),
            errors: Vec::new(),
        }
    }

    fn peek(&self) -> &Token {
        self.tokens.get(self.pos).unwrap_or(&self.tokens[self.tokens.len() - 1])
    }

    fn peek_kind(&self) -> &TokenKind {
        &self.peek().kind
    }

    fn peek_ahead(&self, offset: usize) -> &Token {
        let idx = (self.pos + offset).min(self.tokens.len() - 1);
        &self.tokens[idx]
    }

    fn advance(&mut self) -> &Token {
        let tok = &self.tokens[self.pos];
        if self.pos + 1 < self.tokens.len() {
            self.pos += 1;
        }
        tok
    }

    fn current_pos(&self) -> Pos {
        let tok = self.peek();
        Pos { line: tok.line, col: tok.col, file: self.path.clone() }
    }

    fn token_pos(&self, tok: &Token) -> Pos {
        Pos { line: tok.line, col: tok.col, file: self.path.clone() }
    }

    fn error(&mut self, msg: &str) {
        let tok = self.peek();
        self.errors.push(format!("{} (line {}, column {}) - {}",
            self.path, tok.line + 1, tok.col, msg));
    }

    fn expect(&mut self, kind: &TokenKind) -> Option<&Token> {
        if std::mem::discriminant(self.peek_kind()) == std::mem::discriminant(kind) {
            Some(self.advance())
        } else {
            let tok = self.peek();
            let got = token_display(&tok.kind);
            let expected = token_display(kind);
            self.errors.push(format!("{} (line {}, column {}) - unexpected '{}', expected '{}'",
                self.path, tok.line + 1, tok.col, got, expected));
            None
        }
    }

    fn expect_ident(&mut self) -> Option<String> {
        let tok = self.peek().clone();
        if let TokenKind::Ident(name) = &tok.kind {
            let name = name.clone();
            self.advance();
            Some(name)
        } else {
            let got = token_display(&tok.kind);
            self.errors.push(format!("{} (line {}, column {}) - unexpected '{}', expected identifier",
                self.path, tok.line + 1, tok.col, got));
            None
        }
    }

    pub fn parse_program(&mut self) -> Program {
        let stmts = self.parse_stmts(false, false);
        Program { body: stmts }
    }

    fn parse_stmts(&mut self, in_loop: bool, in_func: bool) -> Vec<Stmt> {
        let mut stmts = Vec::new();

        loop {
            match self.peek_kind() {
                TokenKind::Eof | TokenKind::End | TokenKind::Else | TokenKind::ElseIf => break,
                _ => {
                    if let Some(stmt) = self.parse_stmt(in_loop, in_func) {
                        stmts.push(stmt);
                    } else {
                        // Skip token on error to avoid infinite loop
                        if !matches!(self.peek_kind(), TokenKind::Eof | TokenKind::End | TokenKind::Else | TokenKind::ElseIf) {
                            self.advance();
                        }
                    }
                }
            }
        }

        stmts
    }

    fn parse_stmt(&mut self, in_loop: bool, in_func: bool) -> Option<Stmt> {
        let pos = self.current_pos();

        match self.peek_kind().clone() {
            TokenKind::Let => {
                self.advance();
                self.parse_let(pos)
            }
            TokenKind::Function => {
                // function name(...) body end
                let func_pos = pos.clone();
                self.advance();
                // Check if this is a named function or anonymous
                if let TokenKind::Ident(name) = self.peek_kind().clone() {
                    self.advance();
                    // Named function: desugars to let name = function(...)
                    let (params, body) = self.parse_func_params_body(in_loop)?;
                    let func_expr = Expr::Function { params, body, pos: func_pos.clone() };
                    Some(Stmt::Let {
                        name,
                        value: Some(func_expr),
                        pos: func_pos,
                    })
                } else {
                    // Anonymous function at statement level - just parse as expression
                    let (params, body) = self.parse_func_params_body(in_loop)?;
                    let func_expr = Expr::Function { params, body, pos: func_pos.clone() };
                    Some(Stmt::ExprStmt(func_expr))
                }
            }
            TokenKind::Return => {
                self.advance();
                let val = match self.peek_kind() {
                    TokenKind::Eof | TokenKind::End | TokenKind::Else | TokenKind::ElseIf => None,
                    _ => Some(self.parse_expr(in_loop)?),
                };
                Some(Stmt::Return(val, pos))
            }
            TokenKind::Break => {
                self.advance();
                if !in_loop {
                    self.errors.push(format!("{} - break statement outside loop", pos));
                }
                Some(Stmt::Break(pos))
            }
            TokenKind::LBrace => {
                // Command block as statement
                self.advance();
                let block = self.parse_cmd_block_inner()?;
                Some(Stmt::CmdBlock(block, pos))
            }
            _ => {
                // Could be expression or assignment
                let expr = self.parse_expr(in_loop)?;

                // Check if assignment
                if matches!(self.peek_kind(), TokenKind::Assign) {
                    self.advance();
                    let val = self.parse_expr(in_loop)?;
                    let target = expr_to_assign_target(expr, pos.clone());
                    if let Some(t) = target {
                        Some(Stmt::Assign { target: t, value: val, pos })
                    } else {
                        self.errors.push(format!("{} - invalid assignment target", pos));
                        None
                    }
                } else {
                    Some(Stmt::ExprStmt(expr))
                }
            }
        }
    }

    fn parse_let(&mut self, pos: Pos) -> Option<Stmt> {
        let name = self.expect_ident()?;

        let value = if matches!(self.peek_kind(), TokenKind::Assign) {
            self.advance();
            Some(self.parse_expr(false)?)
        } else {
            None
        };

        Some(Stmt::Let { name, value, pos })
    }

    fn parse_func_params_body(&mut self, in_loop: bool) -> Option<(Vec<String>, Vec<Stmt>)> {
        self.expect(&TokenKind::LParen)?;

        let mut params = Vec::new();
        loop {
            match self.peek_kind().clone() {
                TokenKind::RParen => {
                    self.advance();
                    break;
                }
                TokenKind::Ident(name) => {
                    params.push(name);
                    self.advance();
                    match self.peek_kind() {
                        TokenKind::Comma => { self.advance(); }
                        TokenKind::RParen => {}
                        _ => {
                            self.error("expected ',' or ')'");
                        }
                    }
                }
                _ => {
                    self.error("expected parameter name or ')'");
                    break;
                }
            }
        }

        let body = self.parse_stmts(false, true);
        self.expect(&TokenKind::End)?;

        Some((params, body))
    }

    fn parse_expr(&mut self, in_loop: bool) -> Option<Expr> {
        self.parse_or_expr(in_loop)
    }

    fn parse_or_expr(&mut self, in_loop: bool) -> Option<Expr> {
        let mut left = self.parse_and_expr(in_loop)?;

        while matches!(self.peek_kind(), TokenKind::Or) {
            let pos = self.current_pos();
            self.advance();
            let right = self.parse_and_expr(in_loop)?;
            left = Expr::Binary { op: BinOp::Or, left: Box::new(left), right: Box::new(right), pos };
        }

        Some(left)
    }

    fn parse_and_expr(&mut self, in_loop: bool) -> Option<Expr> {
        let mut left = self.parse_cmp_expr(in_loop)?;

        while matches!(self.peek_kind(), TokenKind::And) {
            let pos = self.current_pos();
            self.advance();
            let right = self.parse_cmp_expr(in_loop)?;
            left = Expr::Binary { op: BinOp::And, left: Box::new(left), right: Box::new(right), pos };
        }

        Some(left)
    }

    fn parse_cmp_expr(&mut self, in_loop: bool) -> Option<Expr> {
        let mut left = self.parse_concat_expr(in_loop)?;

        loop {
            let op = match self.peek_kind() {
                TokenKind::Eq => BinOp::Eq,
                TokenKind::NotEq => BinOp::NotEq,
                TokenKind::Lt => BinOp::Lt,
                TokenKind::LtEq => BinOp::LtEq,
                TokenKind::Gt => BinOp::Gt,
                TokenKind::GtEq => BinOp::GtEq,
                _ => break,
            };
            let pos = self.current_pos();
            self.advance();
            let right = self.parse_concat_expr(in_loop)?;
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right), pos };
        }

        Some(left)
    }

    fn parse_concat_expr(&mut self, in_loop: bool) -> Option<Expr> {
        let mut left = self.parse_add_expr(in_loop)?;

        while matches!(self.peek_kind(), TokenKind::PlusPlus) {
            let pos = self.current_pos();
            self.advance();
            let right = self.parse_add_expr(in_loop)?;
            left = Expr::Binary { op: BinOp::Concat, left: Box::new(left), right: Box::new(right), pos };
        }

        Some(left)
    }

    fn parse_add_expr(&mut self, in_loop: bool) -> Option<Expr> {
        let mut left = self.parse_mul_expr(in_loop)?;

        loop {
            let op = match self.peek_kind() {
                TokenKind::Plus => BinOp::Add,
                TokenKind::Minus => BinOp::Sub,
                _ => break,
            };
            let pos = self.current_pos();
            self.advance();
            let right = self.parse_mul_expr(in_loop)?;
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right), pos };
        }

        Some(left)
    }

    fn parse_mul_expr(&mut self, in_loop: bool) -> Option<Expr> {
        let mut left = self.parse_unary_expr(in_loop)?;

        loop {
            let op = match self.peek_kind() {
                TokenKind::Star => BinOp::Mul,
                TokenKind::Slash => BinOp::Div,
                TokenKind::Percent => BinOp::Mod,
                _ => break,
            };
            let pos = self.current_pos();
            self.advance();
            let right = self.parse_unary_expr(in_loop)?;
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right), pos };
        }

        Some(left)
    }

    fn parse_unary_expr(&mut self, in_loop: bool) -> Option<Expr> {
        let pos = self.current_pos();
        match self.peek_kind().clone() {
            TokenKind::Minus => {
                self.advance();
                let operand = self.parse_unary_expr(in_loop)?;
                Some(Expr::Unary { op: UnaryOp::Neg, operand: Box::new(operand), pos })
            }
            TokenKind::Not => {
                self.advance();
                let operand = self.parse_unary_expr(in_loop)?;
                Some(Expr::Unary { op: UnaryOp::Not, operand: Box::new(operand), pos })
            }
            _ => self.parse_postfix_expr(in_loop),
        }
    }

    fn parse_postfix_expr(&mut self, in_loop: bool) -> Option<Expr> {
        let mut expr = self.parse_primary_expr(in_loop)?;

        loop {
            match self.peek_kind().clone() {
                TokenKind::Dot => {
                    let pos = self.current_pos();
                    self.advance();
                    if let TokenKind::Ident(field) = self.peek_kind().clone() {
                        self.advance();
                        // Check if call
                        if matches!(self.peek_kind(), TokenKind::LParen) {
                            self.advance();
                            let args = self.parse_args(in_loop)?;
                            expr = Expr::MethodCall { obj: Box::new(expr), method: field, args, pos };
                        } else {
                            expr = Expr::Field { obj: Box::new(expr), field, pos };
                        }
                    } else {
                        let tok = self.peek().clone();
                        self.errors.push(format!("{} (line {}, column {}) - unexpected '{}', expected identifier",
                            self.path, tok.line + 1, tok.col, token_display(&tok.kind)));
                        return None;
                    }
                }
                TokenKind::LBracket => {
                    let pos = self.current_pos();
                    self.advance();
                    let key = self.parse_expr(in_loop)?;
                    self.expect(&TokenKind::RBracket)?;
                    expr = Expr::Index { obj: Box::new(expr), key: Box::new(key), pos };
                }
                TokenKind::LParen => {
                    let pos = self.current_pos();
                    self.advance();
                    let args = self.parse_args(in_loop)?;
                    expr = Expr::Call { callee: Box::new(expr), args, pos };
                }
                _ => break,
            }
        }

        Some(expr)
    }

    fn parse_args(&mut self, in_loop: bool) -> Option<Vec<Expr>> {
        let mut args = Vec::new();

        loop {
            if matches!(self.peek_kind(), TokenKind::RParen) {
                self.advance();
                break;
            }

            let arg = self.parse_expr(in_loop)?;
            args.push(arg);

            match self.peek_kind() {
                TokenKind::Comma => { self.advance(); }
                TokenKind::RParen => {
                    self.advance();
                    break;
                }
                _ => {
                    self.error("expected ',' or ')'");
                    return None;
                }
            }
        }

        Some(args)
    }

    fn parse_primary_expr(&mut self, in_loop: bool) -> Option<Expr> {
        let pos = self.current_pos();

        match self.peek_kind().clone() {
            TokenKind::Nil => { self.advance(); Some(Expr::Nil(pos)) }
            TokenKind::True => { self.advance(); Some(Expr::True(pos)) }
            TokenKind::False => { self.advance(); Some(Expr::False(pos)) }
            TokenKind::Int(n) => { self.advance(); Some(Expr::Int(n, pos)) }
            TokenKind::Float(f) => { self.advance(); Some(Expr::Float(f, pos)) }
            TokenKind::Str(s) => { let s = s.clone(); self.advance(); Some(Expr::Str(s, pos)) }
            TokenKind::Char(b) => { let b = b; self.advance(); Some(Expr::Char(b, pos)) }
            TokenKind::Ident(name) => {
                let name = name.clone();
                self.advance();
                Some(Expr::Ident(name, pos))
            }
            TokenKind::LParen => {
                self.advance();
                let expr = self.parse_expr(in_loop)?;
                self.expect(&TokenKind::RParen)?;
                Some(expr)
            }
            TokenKind::LBracket => {
                self.advance();
                let mut items = Vec::new();
                loop {
                    if matches!(self.peek_kind(), TokenKind::RBracket) {
                        self.advance();
                        break;
                    }
                    let item = self.parse_expr(in_loop)?;
                    items.push(item);
                    match self.peek_kind() {
                        TokenKind::Comma => { self.advance(); }
                        TokenKind::RBracket => {
                            self.advance();
                            break;
                        }
                        _ => {
                            self.error("expected ',' or ']'");
                            break;
                        }
                    }
                }
                Some(Expr::Array(items, pos))
            }
            TokenKind::AtLBracket => {
                self.advance();
                let mut pairs = Vec::new();
                loop {
                    if matches!(self.peek_kind(), TokenKind::RBracket) {
                        self.advance();
                        break;
                    }
                    let key = self.expect_ident()?;
                    self.expect(&TokenKind::Colon)?;
                    let val = self.parse_expr(in_loop)?;
                    pairs.push((key, val));
                    match self.peek_kind() {
                        TokenKind::Comma => { self.advance(); }
                        TokenKind::RBracket => {
                            self.advance();
                            break;
                        }
                        _ => {
                            self.error("expected ',' or ']'");
                            break;
                        }
                    }
                }
                Some(Expr::Dict(pairs, pos))
            }
            TokenKind::Function => {
                self.advance();
                let (params, body) = self.parse_func_params_body(in_loop)?;
                Some(Expr::Function { params, body, pos })
            }
            TokenKind::If => {
                self.advance();
                self.parse_if_expr(in_loop, pos)
            }
            TokenKind::While => {
                self.advance();
                let cond = self.parse_expr(in_loop)?;
                self.expect(&TokenKind::Do)?;
                let body = self.parse_stmts(true, false);
                self.expect(&TokenKind::End)?;
                Some(Expr::While { cond: Box::new(cond), body, pos })
            }
            TokenKind::For => {
                self.advance();
                let var = self.expect_ident()?;
                self.expect(&TokenKind::In)?;
                let iter = self.parse_expr(in_loop)?;
                self.expect(&TokenKind::Do)?;
                let body = self.parse_stmts(true, false);
                self.expect(&TokenKind::End)?;
                Some(Expr::For { var, iter: Box::new(iter), body, pos })
            }
            TokenKind::DollarLBrace => {
                self.advance();
                let block = self.parse_cmd_block_inner()?;
                Some(Expr::CmdCapture(block, pos))
            }
            TokenKind::AmpersandLBrace => {
                self.advance();
                let block = self.parse_cmd_block_inner()?;
                Some(Expr::AsyncCmd(block, pos))
            }
            TokenKind::LBrace => {
                // Command block as expression returns the block
                self.advance();
                let block = self.parse_cmd_block_inner()?;
                Some(Expr::CmdCapture(block, pos)) // treat as capture? No - it's a side-effecting block
                // Actually { } as expression in expr position - let's treat as side effect
                // but need to figure out the return value
                // Looking at the AST output, { } is used as statement not expression typically
                // But function bodies can return { } blocks
                // Let me just return it as CmdCapture for now
            }
            tok => {
                let display = token_display(&tok.clone());
                self.errors.push(format!("{} (line {}, column {}) - unexpected '{}', expected expression",
                    self.path, self.peek().line + 1, self.peek().col, display));
                None
            }
        }
    }

    fn parse_if_expr(&mut self, in_loop: bool, pos: Pos) -> Option<Expr> {
        let cond = self.parse_expr(in_loop)?;
        self.expect(&TokenKind::Then)?;
        let then_body = self.parse_stmts(in_loop, false);

        let mut elseif_clauses = Vec::new();
        let mut else_body = None;

        loop {
            match self.peek_kind().clone() {
                TokenKind::ElseIf => {
                    self.advance();
                    let ec = self.parse_expr(in_loop)?;
                    self.expect(&TokenKind::Then)?;
                    let eb = self.parse_stmts(in_loop, false);
                    elseif_clauses.push((ec, eb));
                }
                TokenKind::Else => {
                    self.advance();
                    else_body = Some(self.parse_stmts(in_loop, false));
                    break;
                }
                TokenKind::End => {
                    break;
                }
                _ => {
                    self.error("expected 'elseif', 'else', or 'end'");
                    return None;
                }
            }
        }

        self.expect(&TokenKind::End)?;

        Some(Expr::If { cond: Box::new(cond), then_body, elseif_clauses, else_body, pos })
    }

    // Parse command block (inside { ... })
    fn parse_cmd_block_inner(&mut self) -> Option<CmdBlock> {
        let mut cmds = Vec::new();

        loop {
            self.skip_cmd_whitespace();

            match self.peek_kind() {
                TokenKind::RBrace | TokenKind::Eof => break,
                _ => {}
            }

            // Parse a command sequence (pipeline, optionally with ?)
            match self.parse_cmd_seq() {
                Some(seq) => cmds.push(seq),
                None => {
                    // Skip to recover
                    loop {
                        match self.peek_kind() {
                            TokenKind::Semicolon | TokenKind::RBrace | TokenKind::Eof => break,
                            _ => { self.advance(); }
                        }
                    }
                }
            }

            self.skip_cmd_whitespace();

            // Either ; or end of block
            match self.peek_kind() {
                TokenKind::Semicolon => {
                    self.advance();
                    // Continue to next command
                }
                TokenKind::RBrace | TokenKind::Eof => break,
                _ => {}
            }
        }

        self.expect(&TokenKind::RBrace)?;
        Some(CmdBlock { cmds })
    }

    fn skip_cmd_whitespace(&mut self) {
        // In command context, skip whitespace but stop at significant tokens
        // The lexer already handles this for normal tokens
    }

    fn parse_cmd_seq(&mut self) -> Option<CmdSeq> {
        let pipeline = self.parse_cmd_pipeline()?;

        // Check for ? at end
        let allow_fail = if matches!(self.peek_kind(), TokenKind::Question) {
            self.advance();
            true
        } else {
            false
        };

        Some(CmdSeq { pipeline, allow_fail })
    }

    fn parse_cmd_pipeline(&mut self) -> Option<CmdPipeline> {
        let mut cmds = Vec::new();

        let cmd = self.parse_command()?;
        cmds.push(cmd);

        loop {
            match self.peek_kind() {
                TokenKind::Pipe => {
                    self.advance();
                    match self.parse_command() {
                        Some(cmd) => cmds.push(cmd),
                        None => break,
                    }
                }
                _ => break,
            }
        }

        Some(CmdPipeline { cmds })
    }

    fn parse_command(&mut self) -> Option<Command> {
        use crate::lexer::Lexer as _Lexer;

        // We need to lex command words from the current position
        // But our token stream doesn't have cmd words...
        // We need to handle this differently.
        // The trick is: after { or ${ or &{, we switch to command mode
        // In command mode, we lex words differently.

        // Actually, the lexer already lexed everything as normal tokens.
        // But in command context, identifiers etc. are parts of command words.
        // 
        // This is the fundamental challenge: we have a context-sensitive lexer.
        // 
        // We need to go back to the source and re-lex in command context.
        // OR, we need the lexer to be aware of command context.
        //
        // Let me redesign: the parser will call back into the lexer for cmd words.

        // Actually the simplest approach: have a special token type for cmd blocks
        // and parse them during lexing.

        // OR: keep track of source position in tokens and re-lex command words

        // For now, let me use the token stream but interpret tokens as cmd words
        // Identifiers, strings, numbers etc. in cmd context are command words

        let mut args: Vec<CmdWord> = Vec::new();
        let mut redirects: Vec<Redirect> = Vec::new();
        let mut allow_fail = false;

        // Collect command words until we hit a command separator
        loop {
            match self.peek_kind().clone() {
                TokenKind::Semicolon | TokenKind::RBrace | TokenKind::Eof
                | TokenKind::Pipe | TokenKind::Question => break,

                // Redirections
                TokenKind::Arrow => {
                    // > or N> redirect
                    let pos = self.current_pos();
                    self.advance();
                    // What follows?
                    let target = self.parse_cmd_word_token()?;
                    redirects.push(Redirect::Out { fd: 1, target, append: false });
                }
                TokenKind::Append => {
                    self.advance();
                    let target = self.parse_cmd_word_token()?;
                    redirects.push(Redirect::Out { fd: 1, target, append: true });
                }
                TokenKind::StdinHeredoc => {
                    self.advance();
                    // Get heredoc content
                    let content = self.parse_heredoc_content();
                    redirects.push(Redirect::Stdin(content));
                }
                TokenKind::Int(fd) => {
                    let fd = *fd as i32;
                    // Could be fd redirection: N> or N>>
                    match self.peek_ahead(1).kind.clone() {
                        TokenKind::Arrow => {
                            self.advance(); // consume N
                            self.advance(); // consume >
                            // Check if target is a digit (fd)
                            match self.peek_kind().clone() {
                                TokenKind::Int(target_fd) => {
                                    // fd>N means redirect fd to N
                                    let target_fd = *target_fd as i32;
                                    self.advance();
                                    if fd == 2 && target_fd == 1 {
                                        redirects.push(Redirect::Err2Out);
                                    } else if fd == 1 && target_fd == 2 {
                                        redirects.push(Redirect::Out2Err);
                                    } else {
                                        // Generic fd redirect - treat as Err2Out/Out2Err for common cases
                                        redirects.push(Redirect::Out { 
                                            fd, 
                                            target: CmdWord::Literal(target_fd.to_string()), 
                                            append: false 
                                        });
                                    }
                                }
                                _ => {
                                    // fd> file
                                    let target = self.parse_cmd_word_token()?;
                                    redirects.push(Redirect::Out { fd, target, append: false });
                                }
                            }
                        }
                        TokenKind::Append => {
                            self.advance(); // consume N
                            self.advance(); // consume >>
                            let target = self.parse_cmd_word_token()?;
                            redirects.push(Redirect::Out { fd, target, append: true });
                        }
                        _ => {
                            // Just a number as argument
                            let word = CmdWord::Literal(fd.to_string());
                            args.push(word);
                            self.advance();
                        }
                    }
                }
                TokenKind::LBrace => {
                    // Nested command block? - shouldn't happen in command context
                    break;
                }
                _ => {
                    // Regular command word
                    if let Some(word) = self.parse_cmd_word_token() {
                        args.push(word);
                    } else {
                        break;
                    }
                }
            }
        }

        if args.is_empty() && redirects.is_empty() {
            return None;
        }

        // Check for ? (handled in parse_cmd_seq, but also after pipe in pipeline)
        Some(Command { args, redirects, allow_fail: false })
    }

    fn parse_cmd_word_token(&mut self) -> Option<CmdWord> {
        let tok = self.peek().clone();

        match &tok.kind {
            TokenKind::Ident(s) => {
                let s = s.clone();
                self.advance();
                // Check if it has variable parts in display
                Some(CmdWord::Literal(s))
            }
            TokenKind::Str(s) => {
                let s = s.clone();
                self.advance();
                Some(CmdWord::Literal(s))
            }
            TokenKind::Int(n) => {
                let s = n.to_string();
                self.advance();
                Some(CmdWord::Literal(s))
            }
            TokenKind::Float(f) => {
                let s = format!("{}", f);
                self.advance();
                Some(CmdWord::Literal(s))
            }
            TokenKind::CmdWord(parts) => {
                let parts = parts.clone();
                self.advance();
                // Convert CmdPart to CmdWord
                Some(cmd_parts_to_word(parts, &tok))
            }
            _ => None,
        }
    }

    fn parse_heredoc_content(&mut self) -> String {
        // The next token should be the heredoc content
        // It could be a string literal or identifier
        match self.peek_kind().clone() {
            TokenKind::Str(s) => { self.advance(); s }
            TokenKind::Ident(s) => { self.advance(); s }
            _ => String::new(),
        }
    }
}

fn cmd_parts_to_word(parts: Vec<CmdPart>, tok: &Token) -> CmdWord {
    if parts.len() == 1 {
        match &parts[0] {
            CmdPart::Literal(s) => return CmdWord::Literal(s.clone()),
            CmdPart::Var(name, line, col) => {
                return CmdWord::Variable(name.clone(), Pos {
                    line: *line,
                    col: *col,
                    file: String::new(), // will be filled in
                });
            }
        }
    }

    let word_parts: Vec<crate::ast::CmdWordPart> = parts.into_iter().map(|p| match p {
        CmdPart::Literal(s) => crate::ast::CmdWordPart::Literal(s),
        CmdPart::Var(name, line, col) => crate::ast::CmdWordPart::Variable(name, Pos {
            line,
            col,
            file: String::new(),
        }),
    }).collect();

    CmdWord::Unquoted(word_parts)
}

fn expr_to_assign_target(expr: Expr, pos: Pos) -> Option<AssignTarget> {
    match expr {
        Expr::Ident(name, p) => Some(AssignTarget::Ident(name, p)),
        Expr::Index { obj, key, pos } => Some(AssignTarget::Index(obj, key, pos)),
        Expr::Field { obj, field, pos } => Some(AssignTarget::Field(obj, Box::new(Expr::Str(field.clone(), pos.clone())), pos)),
        _ => None,
    }
}

fn token_display(kind: &TokenKind) -> String {
    match kind {
        TokenKind::Nil => "nil".to_string(),
        TokenKind::True => "true".to_string(),
        TokenKind::False => "false".to_string(),
        TokenKind::Int(n) => n.to_string(),
        TokenKind::Float(f) => format!("{}", f),
        TokenKind::Str(s) => format!("\"{}\"", s),
        TokenKind::Char(b) => format!("'{}'", *b as char),
        TokenKind::Ident(s) => s.clone(),
        TokenKind::Let => "let".to_string(),
        TokenKind::Function => "function".to_string(),
        TokenKind::If => "if".to_string(),
        TokenKind::Then => "then".to_string(),
        TokenKind::Else => "else".to_string(),
        TokenKind::ElseIf => "elseif".to_string(),
        TokenKind::End => "end".to_string(),
        TokenKind::While => "while".to_string(),
        TokenKind::Do => "do".to_string(),
        TokenKind::For => "for".to_string(),
        TokenKind::In => "in".to_string(),
        TokenKind::Return => "return".to_string(),
        TokenKind::Break => "break".to_string(),
        TokenKind::Plus => "+".to_string(),
        TokenKind::Minus => "-".to_string(),
        TokenKind::Star => "*".to_string(),
        TokenKind::Slash => "/".to_string(),
        TokenKind::Percent => "%".to_string(),
        TokenKind::Eq => "==".to_string(),
        TokenKind::NotEq => "!=".to_string(),
        TokenKind::Lt => "<".to_string(),
        TokenKind::LtEq => "<=".to_string(),
        TokenKind::Gt => ">".to_string(),
        TokenKind::GtEq => ">=".to_string(),
        TokenKind::And => "and".to_string(),
        TokenKind::Or => "or".to_string(),
        TokenKind::Not => "not".to_string(),
        TokenKind::Assign => "=".to_string(),
        TokenKind::PlusPlus => "++".to_string(),
        TokenKind::LParen => "(".to_string(),
        TokenKind::RParen => ")".to_string(),
        TokenKind::LBracket => "[".to_string(),
        TokenKind::RBracket => "]".to_string(),
        TokenKind::LBrace => "{".to_string(),
        TokenKind::RBrace => "}".to_string(),
        TokenKind::AtLBracket => "@[".to_string(),
        TokenKind::Comma => ",".to_string(),
        TokenKind::Colon => ":".to_string(),
        TokenKind::Dot => ".".to_string(),
        TokenKind::Semicolon => ";".to_string(),
        TokenKind::DollarLBrace => "${".to_string(),
        TokenKind::AmpersandLBrace => "&{".to_string(),
        TokenKind::Pipe => "|".to_string(),
        TokenKind::Arrow => ">".to_string(),
        TokenKind::Append => ">>".to_string(),
        TokenKind::StdinHeredoc => "<<".to_string(),
        TokenKind::Question => "?".to_string(),
        TokenKind::CmdWord(_) => "word".to_string(),
        TokenKind::Eof => "end of file".to_string(),
    }
}

pub fn parse(tokens: &[Token], path: &str) -> (Program, Vec<String>) {
    let mut parser = Parser::new(tokens, path);
    let program = parser.parse_program();
    (program, parser.errors)
}
