#![allow(dead_code, unused_variables, unused_mut, unused_imports)]

mod lexer;
mod parser;
mod ast;
mod semantic;
mod interpreter;

use std::io::Read;
use std::process;

fn print_help() {
    eprintln!("Hush 0.1.4");
    eprintln!("gahag <gabriel.s.b@live.com>");
    eprintln!("Hush is a unix shell scripting language based on the Lua programming language");
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("    hush [FLAGS] [arguments]...");
    eprintln!();
    eprintln!("FLAGS:");
    eprintln!("        --ast        Print the AST");
    eprintln!("        --check      Perform only static analysis instead of executing.");
    eprintln!("    -h, --help       Prints help information");
    eprintln!("        --lex        Print the lexemes");
    eprintln!("        --program    Print the PROGAM");
    eprintln!("    -V, --version    Prints version information");
    eprintln!();
    eprintln!("ARGS:");
    eprintln!("    <arguments>...    Script and/or arguments");
}

fn main() {
    let all_args: Vec<String> = std::env::args().collect();

    let mut show_ast = false;
    let mut show_lex = false;
    let mut show_program = false;
    let mut check_only = false;
    let mut script_and_args: Vec<String> = Vec::new();

    let mut i = 1;
    while i < all_args.len() {
        match all_args[i].as_str() {
            "--ast" => show_ast = true,
            "--lex" => show_lex = true,
            "--program" => show_program = true,
            "--check" => check_only = true,
            "-h" | "--help" => {
                print_help();
                process::exit(0);
            }
            "-V" | "--version" => {
                println!("Hush 0.1.4");
                process::exit(0);
            }
            _ => script_and_args.push(all_args[i].clone()),
        }
        i += 1;
    }

    if script_and_args.is_empty() {
        // REPL mode
        let mut source = String::new();
        std::io::stdin().read_to_string(&mut source).ok();
        if !source.is_empty() {
            let code = run_source(&source, "<stdin>", vec![], show_lex, show_ast, show_program, check_only);
            process::exit(code);
        }
    } else {
        let script_path = script_and_args[0].clone();
        let script_args: Vec<String> = script_and_args[1..].to_vec();

        let source = match std::fs::read_to_string(&script_path) {
            Ok(s) => s,
            Err(e) => {
                eprintln!("Error reading '{}': {}", script_path, e);
                process::exit(1);
            }
        };

        let code = run_source(&source, &script_path, script_args, show_lex, show_ast, show_program, check_only);
        process::exit(code);
    }
}

fn run_source(source: &str, path: &str, args: Vec<String>, show_lex: bool, show_ast: bool, show_program: bool, check_only: bool) -> i32 {
    let mut had_lex_err = false;

    // Lex
    let (tokens, lex_errors) = lexer::lex(source, path);
    for err in &lex_errors {
        eprintln!("{}", err);
        had_lex_err = true;
    }

    if show_lex {
        println!("--------------------------------------------------");
        for tok in &tokens {
            if !matches!(tok.kind, lexer::TokenKind::Eof) {
                println!("{} (line {}, column {}):\t{}", 
                    path, tok.line + 1, tok.col, tok.display);
            }
        }
        println!("--------------------------------------------------");
    }

    // Parse
    let (program, parse_errors) = parser::parse(&tokens, path);
    let mut had_parse_err = !parse_errors.is_empty();
    for err in &parse_errors {
        eprintln!("{}", err);
    }

    if show_ast {
        println!("--------------------------------------------------");
        println!("AST for {}", path);
        if had_parse_err && !parse_errors.is_empty() {
            // Show what we have even if error
        }
        ast::print_program(&program);
        println!("--------------------------------------------------");
    }

    // Semantic analysis
    let (sem_errors, scopes) = semantic::analyze(&program, path);
    for err in &sem_errors {
        eprintln!("{}", err);
    }
    let had_sem_err = !sem_errors.is_empty();

    if show_program {
        println!("--------------------------------------------------");
        println!("Program for {}", path);
        semantic::print_program(&program, &scopes);
        println!("--------------------------------------------------");
    }

    let had_error = had_lex_err || had_parse_err || had_sem_err;

    if had_error {
        return 2;
    }

    if check_only {
        return 0;
    }

    // Execute
    interpreter::execute(&program, path, args)
}
