// Hush Lexer
// Context-sensitive lexer that switches to command mode inside { } blocks

#[derive(Debug, Clone, PartialEq)]
pub enum TokenKind {
    // Literals
    Nil,
    True, 
    False,
    Int(i64),
    Float(f64),
    Str(String),
    Char(u8),
    // Identifier
    Ident(String),
    // Keywords
    Let, Function, If, Then, Else, ElseIf, End,
    While, Do, For, In, Return, Break,
    // Operators
    Plus, Minus, Star, Slash, Percent,
    Eq, NotEq, Lt, LtEq, Gt, GtEq,
    And, Or, Not,
    Assign,   // =
    Concat,   // ++
    // Punctuation
    LParen, RParen, LBracket, RBracket,
    AtLBracket,  // @[
    Comma, Colon, Dot,
    // Command block starters
    LBrace,           // {
    RBrace,           // }
    DollarLBrace,     // ${
    AmpersandLBrace,  // &{
    // Command-specific tokens
    Semicolon,   // ;
    Pipe,        // |
    Arrow,       // >
    Append,      // >>
    Stdin,       // <<
    Question,    // ?
    // Command word (contains string parts and variable references)
    CmdWord(Vec<CmdPart>),
    // EOF
    Eof,
}

#[derive(Debug, Clone, PartialEq)]
pub enum CmdPart {
    Lit(String),
    Var(String, usize, usize),  // name, line, col of $ sign
}

#[derive(Debug, Clone)]
pub struct Token {
    pub kind: TokenKind,
    pub line: usize,  // 0-indexed
    pub col: usize,
    pub display: String,
}

pub fn lex(source: &str, path: &str) -> (Vec<Token>, Vec<String>) {
    let mut l = Lexer::new(source, path);
    let mut tokens = Vec::new();
    let mut errors = Vec::new();

    l.tokenize(&mut tokens, &mut errors);

    (tokens, errors)
}

struct Lexer {
    src: Vec<u8>,
    pos: usize,
    line: usize,
    col: usize,
    path: String,
}

impl Lexer {
    fn new(source: &str, path: &str) -> Self {
        Lexer {
            src: source.as_bytes().to_vec(),
            pos: 0,
            line: 0,
            col: 0,
            path: path.to_string(),
        }
    }

    fn peek(&self) -> Option<u8> {
        self.src.get(self.pos).copied()
    }

    fn peek_at(&self, offset: usize) -> Option<u8> {
        self.src.get(self.pos + offset).copied()
    }

    fn advance(&mut self) -> Option<u8> {
        let c = self.src.get(self.pos).copied()?;
        self.pos += 1;
        if c == b'\n' {
            self.line += 1;
            self.col = 0;
        } else {
            self.col += 1;
        }
        Some(c)
    }

    fn skip_ws_and_comments(&mut self) {
        loop {
            match self.peek() {
                Some(b' ') | Some(b'\t') | Some(b'\r') | Some(b'\n') => { self.advance(); }
                Some(b'#') => {
                    while self.peek().map_or(false, |c| c != b'\n') {
                        self.advance();
                    }
                }
                _ => break,
            }
        }
    }

    fn tokenize(&mut self, tokens: &mut Vec<Token>, errors: &mut Vec<String>) {
        // cmd_depth tracks how many { } layers we're in (for command context)
        let mut cmd_depth: usize = 0;

        loop {
            // Skip whitespace (including newlines, EXCEPT in cmd mode where
            // newlines are actually just whitespace and not separators)
            self.skip_ws_and_comments();

            if self.peek().is_none() {
                tokens.push(Token {
                    kind: TokenKind::Eof,
                    line: self.line,
                    col: self.col,
                    display: String::new(),
                });
                break;
            }

            let line = self.line;
            let col = self.col;

            if cmd_depth > 0 {
                // Command context
                match self.peek() {
                    Some(b'}') => {
                        self.advance();
                        cmd_depth -= 1;
                        tokens.push(Token { kind: TokenKind::RBrace, line, col, display: "}".into() });
                    }
                    Some(b';') => {
                        self.advance();
                        tokens.push(Token { kind: TokenKind::Semicolon, line, col, display: ";".into() });
                    }
                    Some(b'|') => {
                        self.advance();
                        tokens.push(Token { kind: TokenKind::Pipe, line, col, display: "|".into() });
                    }
                    Some(b'>') => {
                        self.advance();
                        if self.peek() == Some(b'>') {
                            self.advance();
                            tokens.push(Token { kind: TokenKind::Append, line, col, display: ">>".into() });
                        } else {
                            tokens.push(Token { kind: TokenKind::Arrow, line, col, display: ">".into() });
                        }
                    }
                    Some(b'<') if self.peek_at(1) == Some(b'<') => {
                        self.advance();
                        self.advance();
                        tokens.push(Token { kind: TokenKind::Stdin, line, col, display: "<<".into() });
                        // Skip whitespace and lex the heredoc string
                        while matches!(self.peek(), Some(b' ') | Some(b'\t')) { self.advance(); }
                        let (heredoc_str, raw) = self.lex_heredoc_content(errors);
                        tokens.push(Token {
                            kind: TokenKind::CmdWord(vec![CmdPart::Lit(heredoc_str)]),
                            line: self.line,
                            col: self.col.saturating_sub(raw.len()),
                            display: raw,
                        });
                    }
                    Some(b'?') => {
                        self.advance();
                        tokens.push(Token { kind: TokenKind::Question, line, col, display: "?".into() });
                    }
                    Some(b'#') => {
                        // Comment in cmd context
                        while self.peek().map_or(false, |c| c != b'\n') {
                            self.advance();
                        }
                    }
                    Some(c) if c.is_ascii_digit() => {
                        // Could be fd number for redirection or a command word
                        // Check if followed by > or >>
                        let mut num_s = String::new();
                        while let Some(d) = self.peek() {
                            if d.is_ascii_digit() {
                                num_s.push(d as char);
                                self.advance();
                            } else {
                                break;
                            }
                        }
                        // Check if followed by > or >>
                        if matches!(self.peek(), Some(b'>')) || (self.peek() == Some(b'>') && self.peek_at(1) == Some(b'>')) {
                            // It's a redirection fd number
                            let n: i64 = num_s.parse().unwrap_or(0);
                            tokens.push(Token { kind: TokenKind::Int(n), line, col, display: num_s.clone() });
                            // The > will be lexed next iteration
                        } else {
                            // It's part of a command word - continue collecting
                            let (more_parts, more_raw) = self.lex_cmd_word_continue(errors);
                            let display = if more_parts.is_empty() {
                                num_s.clone()
                            } else {
                                format!("{}{}", num_s, more_raw)
                            };
                            let mut parts = vec![CmdPart::Lit(num_s)];
                            parts.extend(more_parts);
                            let parts = merge_lits(parts);
                            tokens.push(Token { kind: TokenKind::CmdWord(parts), line, col, display });
                        }
                    }
                    _ => {
                        // Lex a command word
                        if let Some((parts, display)) = self.lex_cmd_word(errors) {
                            tokens.push(Token { kind: TokenKind::CmdWord(parts), line, col, display });
                        }
                    }
                }
            } else {
                // Normal (expression) context
                match self.peek() {
                    Some(b'{') => {
                        self.advance();
                        cmd_depth += 1;
                        tokens.push(Token { kind: TokenKind::LBrace, line, col, display: "{".into() });
                    }
                    Some(b'$') if self.peek_at(1) == Some(b'{') => {
                        self.advance();
                        self.advance();
                        cmd_depth += 1;
                        tokens.push(Token { kind: TokenKind::DollarLBrace, line, col, display: "${".into() });
                    }
                    Some(b'&') if self.peek_at(1) == Some(b'{') => {
                        self.advance();
                        self.advance();
                        cmd_depth += 1;
                        tokens.push(Token { kind: TokenKind::AmpersandLBrace, line, col, display: "&{".into() });
                    }
                    Some(c) => {
                        if let Some((kind, display)) = self.lex_normal_token(c, errors) {
                            tokens.push(Token { kind, line, col, display });
                        }
                    }
                    None => break,
                }
            }
        }
    }

    fn lex_normal_token(&mut self, c: u8, errors: &mut Vec<String>) -> Option<(TokenKind, String)> {
        match c {
            b'+' => {
                self.advance();
                if self.peek() == Some(b'+') {
                    self.advance();
                    Some((TokenKind::Concat, "++".into()))
                } else {
                    Some((TokenKind::Plus, "+".into()))
                }
            }
            b'-' => { self.advance(); Some((TokenKind::Minus, "-".into())) }
            b'*' => { self.advance(); Some((TokenKind::Star, "*".into())) }
            b'/' => { self.advance(); Some((TokenKind::Slash, "/".into())) }
            b'%' => { self.advance(); Some((TokenKind::Percent, "%".into())) }
            b'=' => {
                self.advance();
                if self.peek() == Some(b'=') {
                    self.advance();
                    Some((TokenKind::Eq, "==".into()))
                } else {
                    Some((TokenKind::Assign, "=".into()))
                }
            }
            b'!' => {
                self.advance();
                if self.peek() == Some(b'=') {
                    self.advance();
                    Some((TokenKind::NotEq, "!=".into()))
                } else {
                    let col = self.col - 1;
                    errors.push(format!("{} (line {}, column {}) - unexpected '!'",
                        self.path, self.line + 1, col));
                    None
                }
            }
            b'<' => {
                self.advance();
                if self.peek() == Some(b'=') {
                    self.advance();
                    Some((TokenKind::LtEq, "<=".into()))
                } else if self.peek() == Some(b'<') {
                    self.advance();
                    Some((TokenKind::Stdin, "<<".into()))
                } else {
                    Some((TokenKind::Lt, "<".into()))
                }
            }
            b'>' => {
                self.advance();
                if self.peek() == Some(b'=') {
                    self.advance();
                    Some((TokenKind::GtEq, ">=".into()))
                } else if self.peek() == Some(b'>') {
                    self.advance();
                    Some((TokenKind::Append, ">>".into()))
                } else {
                    Some((TokenKind::Arrow, ">".into()))
                }
            }
            b'(' => { self.advance(); Some((TokenKind::LParen, "(".into())) }
            b')' => { self.advance(); Some((TokenKind::RParen, ")".into())) }
            b'[' => { self.advance(); Some((TokenKind::LBracket, "[".into())) }
            b']' => { self.advance(); Some((TokenKind::RBracket, "]".into())) }
            b'@' => {
                self.advance();
                if self.peek() == Some(b'[') {
                    self.advance();
                    Some((TokenKind::AtLBracket, "@[".into()))
                } else {
                    let col = self.col - 1;
                    errors.push(format!("{} (line {}, column {}) - unexpected '@'",
                        self.path, self.line + 1, col));
                    None
                }
            }
            b',' => { self.advance(); Some((TokenKind::Comma, ",".into())) }
            b':' => { self.advance(); Some((TokenKind::Colon, ":".into())) }
            b'.' => { self.advance(); Some((TokenKind::Dot, ".".into())) }
            b';' => {
                self.advance();
                let col = self.col - 1;
                errors.push(format!("{} (line {}, column {}) - unexpected ';'",
                    self.path, self.line + 1, col));
                None
            }
            b'|' => {
                self.advance();
                let col = self.col - 1;
                errors.push(format!("{} (line {}, column {}) - unexpected '|'",
                    self.path, self.line + 1, col));
                None
            }
            b'?' => {
                self.advance();
                let col = self.col - 1;
                errors.push(format!("{} (line {}, column {}) - unexpected '?'",
                    self.path, self.line + 1, col));
                None
            }
            b'$' => {
                self.advance();
                let col = self.col - 1;
                errors.push(format!("{} (line {}, column {}) - unexpected '$'",
                    self.path, self.line + 1, col));
                None
            }
            b'&' => {
                self.advance();
                let col = self.col - 1;
                errors.push(format!("{} (line {}, column {}) - unexpected '&'",
                    self.path, self.line + 1, col));
                None
            }
            b'}' => {
                self.advance();
                let col = self.col - 1;
                errors.push(format!("{} (line {}, column {}) - unexpected '}}'",
                    self.path, self.line + 1, col));
                None
            }
            b'"' => {
                self.advance();
                let (s, raw) = self.lex_dquote(errors);
                Some((TokenKind::Str(s), raw))
            }
            b'\'' => {
                self.advance();
                let start_col = self.col.saturating_sub(1);
                match self.lex_char_literal(start_col, errors) {
                    Some((b, raw)) => Some((TokenKind::Char(b), raw)),
                    None => None,
                }
            }
            c if c.is_ascii_digit() => {
                self.advance();
                let (kind, raw) = self.lex_number(c);
                Some((kind, raw))
            }
            c if c.is_ascii_alphabetic() || c == b'_' => {
                self.advance();
                let (kind, raw) = self.lex_ident(c);
                Some((kind, raw))
            }
            c => {
                self.advance();
                let col = self.col - 1;
                errors.push(format!("{} (line {}, column {}) - unexpected '{}'",
                    self.path, self.line + 1, col, c as char));
                None
            }
        }
    }

    fn lex_dquote(&mut self, errors: &mut Vec<String>) -> (String, String) {
        let start_col = self.col.saturating_sub(1);
        let mut s = String::new();
        let mut raw = String::from("\"");

        loop {
            match self.peek() {
                None => {
                    errors.push(format!("{} (line {}, column {}) - unterminated string",
                        self.path, self.line + 1, start_col));
                    break;
                }
                Some(b'"') => {
                    self.advance();
                    raw.push('"');
                    break;
                }
                Some(b'\\') => {
                    let esc_col = self.col;
                    self.advance();
                    raw.push('\\');
                    match self.peek() {
                        Some(b'n') => { self.advance(); s.push('\n'); raw.push('n'); }
                        Some(b't') => { self.advance(); s.push('\t'); raw.push('t'); }
                        Some(b'0') => { self.advance(); s.push('\0'); raw.push('0'); }
                        Some(b'\\') => { self.advance(); s.push('\\'); raw.push('\\'); }
                        Some(b'"') => { self.advance(); s.push('"'); raw.push('"'); }
                        Some(b'\'') => { self.advance(); s.push('\''); raw.push('\''); }
                        Some(cc) => {
                            let ch = cc as char;
                            self.advance();
                            raw.push(ch);
                            errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                                self.path, self.line + 1, esc_col - 1, ch));
                        }
                        None => {}
                    }
                }
                Some(cc) => {
                    let ch = cc as char;
                    self.advance();
                    s.push(ch);
                    raw.push(ch);
                }
            }
        }
        (s, raw)
    }

    fn lex_char_literal(&mut self, start_col: usize, errors: &mut Vec<String>) -> Option<(u8, String)> {
        let mut raw = String::from("'");

        let byte = match self.peek() {
            Some(b'\\') => {
                self.advance();
                raw.push('\\');
                match self.peek() {
                    Some(b'n') => { self.advance(); raw.push('n'); b'\n' }
                    Some(b't') => { self.advance(); raw.push('t'); b'\t' }
                    Some(b'0') => { self.advance(); raw.push('0'); b'\0' }
                    Some(b'\\') => { self.advance(); raw.push('\\'); b'\\' }
                    Some(b'\'') => { self.advance(); raw.push('\''); b'\'' }
                    Some(b'"') => { self.advance(); raw.push('"'); b'"' }
                    Some(cc) => {
                        let ch = cc as char;
                        let esc_col = self.col;
                        self.advance();
                        raw.push(ch);
                        // consume to close quote
                        while let Some(c) = self.peek() {
                            if c == b'\'' { self.advance(); break; }
                            self.advance();
                        }
                        errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                            self.path, self.line + 1, esc_col - 1, ch));
                        return None;
                    }
                    None => {
                        errors.push(format!("{} (line {}, column {}) - unterminated char literal",
                            self.path, self.line + 1, start_col));
                        return None;
                    }
                }
            }
            Some(cc) => {
                let b = cc;
                self.advance();
                raw.push(b as char);
                b
            }
            None => {
                errors.push(format!("{} (line {}, column {}) - unterminated char literal",
                    self.path, self.line + 1, start_col));
                return None;
            }
        };

        match self.peek() {
            Some(b'\'') => {
                self.advance();
                raw.push('\'');
            }
            _ => {
                errors.push(format!("{} (line {}, column {}) - unterminated char literal",
                    self.path, self.line + 1, start_col));
            }
        }

        Some((byte, raw))
    }

    fn lex_number(&mut self, first: u8) -> (TokenKind, String) {
        let mut s = String::new();
        s.push(first as char);

        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                s.push(c as char);
                self.advance();
            } else {
                break;
            }
        }

        let has_dot = self.peek() == Some(b'.') && 
            self.peek_at(1).map_or(false, |c| c.is_ascii_digit());
        let has_exp = matches!(self.peek(), Some(b'e') | Some(b'E'));

        if !has_dot && !has_exp {
            let val: i64 = s.parse().unwrap_or(0);
            return (TokenKind::Int(val), s);
        }

        // Float
        if has_dot {
            s.push('.');
            self.advance();
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() { s.push(c as char); self.advance(); }
                else { break; }
            }
        }

        if matches!(self.peek(), Some(b'e') | Some(b'E')) {
            self.advance();
            let mut exp = String::new();
            if self.peek() == Some(b'+') { self.advance(); }
            else if self.peek() == Some(b'-') {
                // Negative exponent is an error in this language
                // (from our observation: 1.5e-2 gives "unexpected '-'")
                // Actually looking at the error output, it says "unexpected '-'"
                // at column of the '-'. So we parse the number part before 'e'
                // and leave the minus for the expression parser.
                // Let's just parse the float without the exponent.
                let val: f64 = s.parse().unwrap_or(0.0);
                return (TokenKind::Float(val), float_display(val));
            }
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() { exp.push(c as char); self.advance(); }
                else { break; }
            }
            let base: f64 = s.parse().unwrap_or(0.0);
            let e: i32 = exp.parse().unwrap_or(0);
            let val = base * 10f64.powi(e);
            return (TokenKind::Float(val), float_display(val));
        }

        let val: f64 = s.parse().unwrap_or(0.0);
        (TokenKind::Float(val), float_display(val))
    }

    fn lex_ident(&mut self, first: u8) -> (TokenKind, String) {
        let mut s = String::new();
        s.push(first as char);

        while let Some(c) = self.peek() {
            if c.is_ascii_alphanumeric() || c == b'_' {
                s.push(c as char);
                self.advance();
            } else {
                break;
            }
        }

        let kind = match s.as_str() {
            "nil" => TokenKind::Nil,
            "true" => TokenKind::True,
            "false" => TokenKind::False,
            "let" => TokenKind::Let,
            "function" => TokenKind::Function,
            "if" => TokenKind::If,
            "then" => TokenKind::Then,
            "else" => TokenKind::Else,
            "elseif" => TokenKind::ElseIf,
            "end" => TokenKind::End,
            "while" => TokenKind::While,
            "do" => TokenKind::Do,
            "for" => TokenKind::For,
            "in" => TokenKind::In,
            "return" => TokenKind::Return,
            "break" => TokenKind::Break,
            "and" => TokenKind::And,
            "or" => TokenKind::Or,
            "not" => TokenKind::Not,
            _ => TokenKind::Ident(s.clone()),
        };

        (kind, s)
    }

    // Lex a command word (in command block context)
    fn lex_cmd_word(&mut self, errors: &mut Vec<String>) -> Option<(Vec<CmdPart>, String)> {
        let mut parts: Vec<CmdPart> = Vec::new();
        let mut display = String::new();
        let mut started = false;

        loop {
            match self.peek() {
                None | Some(b' ') | Some(b'\t') | Some(b'\n') | Some(b'\r')
                | Some(b';') | Some(b'|') | Some(b'}') | Some(b'?') | Some(b'#') => break,
                Some(b'>') => break,
                Some(b'<') if self.peek_at(1) == Some(b'<') => break,
                Some(b'<') => break,

                Some(b'"') => {
                    started = true;
                    self.advance();
                    display.push('"');
                    self.lex_cmd_dquote_into(&mut parts, &mut display, errors);
                    display.push('"');
                }
                Some(b'\'') => {
                    started = true;
                    self.advance();
                    display.push('\'');
                    self.lex_cmd_squote_into(&mut parts, &mut display, errors);
                    display.push('\'');
                }
                Some(b'$') => {
                    started = true;
                    self.advance();
                    display.push('$');
                    if self.peek() == Some(b'\'') {
                        // $'...' dollar-single-quoted
                        self.advance();
                        display.push('\'');
                        self.lex_cmd_dollar_squote_into(&mut parts, &mut display, errors);
                        display.push('\'');
                    } else if let Some(name) = self.lex_var_name() {
                        let var_col = self.col.saturating_sub(name.len() + 1);
                        display.push_str(&format!("{{{}}}", name));
                        parts.push(CmdPart::Var(name, self.line, var_col));
                    } else {
                        // Literal $
                        push_lit(&mut parts, "$");
                    }
                }
                Some(b'\\') => {
                    started = true;
                    let esc_col = self.col;
                    self.advance();
                    display.push('\\');
                    match self.peek() {
                        Some(b' ') => { self.advance(); push_lit(&mut parts, " "); display.push(' '); }
                        Some(b'n') => { self.advance(); push_lit(&mut parts, "\n"); display.push('n'); }
                        Some(b't') => { self.advance(); push_lit(&mut parts, "\t"); display.push('t'); }
                        Some(b'0') => { self.advance(); push_lit(&mut parts, "\0"); display.push('0'); }
                        Some(b'\\') => { self.advance(); push_lit(&mut parts, "\\"); display.push('\\'); }
                        Some(b'\'') => { self.advance(); push_lit(&mut parts, "'"); display.push('\''); }
                        Some(b'"') => { self.advance(); push_lit(&mut parts, "\""); display.push('"'); }
                        Some(b';') => { self.advance(); push_lit(&mut parts, ";"); display.push(';'); }
                        Some(b'|') => { self.advance(); push_lit(&mut parts, "|"); display.push('|'); }
                        Some(b'>') => { self.advance(); push_lit(&mut parts, ">"); display.push('>'); }
                        Some(b'?') => { self.advance(); push_lit(&mut parts, "?"); display.push('?'); }
                        Some(b'}') => { self.advance(); push_lit(&mut parts, "}"); display.push('}'); }
                        Some(cc) => {
                            let ch = cc as char;
                            self.advance();
                            display.push(ch);
                            errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                                self.path, self.line + 1, esc_col, ch));
                            push_lit(&mut parts, &ch.to_string());
                        }
                        None => {}
                    }
                }
                Some(cc) => {
                    started = true;
                    let ch = cc as char;
                    self.advance();
                    push_lit(&mut parts, &ch.to_string());
                    display.push(ch);
                }
            }
        }

        if !started {
            return None;
        }

        Some((merge_lits(parts), display))
    }

    // Continue lexing cmd word (after an initial digit)
    fn lex_cmd_word_continue(&mut self, errors: &mut Vec<String>) -> (Vec<CmdPart>, String) {
        let mut parts: Vec<CmdPart> = Vec::new();
        let mut display = String::new();

        loop {
            match self.peek() {
                None | Some(b' ') | Some(b'\t') | Some(b'\n') | Some(b'\r')
                | Some(b';') | Some(b'|') | Some(b'}') | Some(b'?') | Some(b'#') => break,
                Some(b'>') => break,
                Some(b'<') if self.peek_at(1) == Some(b'<') => break,
                Some(b'<') => break,
                Some(b'"') => {
                    self.advance();
                    display.push('"');
                    self.lex_cmd_dquote_into(&mut parts, &mut display, errors);
                    display.push('"');
                }
                Some(b'\'') => {
                    self.advance();
                    display.push('\'');
                    self.lex_cmd_squote_into(&mut parts, &mut display, errors);
                    display.push('\'');
                }
                Some(b'$') => {
                    self.advance();
                    display.push('$');
                    if let Some(name) = self.lex_var_name() {
                        display.push_str(&format!("{{{}}}", name));
                        parts.push(CmdPart::Var(name, self.line, self.col));
                    } else {
                        push_lit(&mut parts, "$");
                    }
                }
                Some(cc) => {
                    let ch = cc as char;
                    self.advance();
                    push_lit(&mut parts, &ch.to_string());
                    display.push(ch);
                }
            }
        }

        (parts, display)
    }

    fn lex_cmd_dquote_into(&mut self, parts: &mut Vec<CmdPart>, display: &mut String, errors: &mut Vec<String>) {
        loop {
            match self.peek() {
                None | Some(b'"') => { 
                    if self.peek() == Some(b'"') { self.advance(); }
                    break; 
                }
                Some(b'\\') => {
                    let esc_col = self.col;
                    self.advance();
                    display.push('\\');
                    match self.peek() {
                        Some(b'n') => { self.advance(); push_lit(parts, "\n"); display.push('n'); }
                        Some(b't') => { self.advance(); push_lit(parts, "\t"); display.push('t'); }
                        Some(b'0') => { self.advance(); push_lit(parts, "\0"); display.push('0'); }
                        Some(b'\\') => { self.advance(); push_lit(parts, "\\"); display.push('\\'); }
                        Some(b'"') => { self.advance(); push_lit(parts, "\""); display.push('"'); }
                        Some(b'\'') => { self.advance(); push_lit(parts, "'"); display.push('\''); }
                        Some(b'$') => { self.advance(); push_lit(parts, "$"); display.push('$'); }
                        Some(b' ') => { self.advance(); push_lit(parts, " "); display.push(' '); }
                        Some(cc) => {
                            let ch = cc as char;
                            self.advance();
                            display.push(ch);
                            errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                                self.path, self.line + 1, esc_col - 1, ch));
                            push_lit(parts, &ch.to_string());
                        }
                        None => break,
                    }
                }
                Some(b'$') => {
                    self.advance();
                    display.push('$');
                    if let Some(name) = self.lex_var_name() {
                        display.push_str(&format!("{{{}}}", name));
                        parts.push(CmdPart::Var(name, self.line, self.col));
                    } else {
                        push_lit(parts, "$");
                    }
                }
                Some(cc) => {
                    let ch = cc as char;
                    self.advance();
                    push_lit(parts, &ch.to_string());
                    display.push(ch);
                }
            }
        }
    }

    fn lex_cmd_squote_into(&mut self, parts: &mut Vec<CmdPart>, display: &mut String, errors: &mut Vec<String>) {
        loop {
            match self.peek() {
                None | Some(b'\'') => {
                    if self.peek() == Some(b'\'') { self.advance(); }
                    break;
                }
                Some(b'\\') => {
                    let esc_col = self.col;
                    self.advance();
                    display.push('\\');
                    match self.peek() {
                        Some(b'\'') => { self.advance(); push_lit(parts, "'"); display.push('\''); }
                        Some(b'\\') => { self.advance(); push_lit(parts, "\\"); display.push('\\'); }
                        Some(b'n') => { self.advance(); push_lit(parts, "\n"); display.push('n'); }
                        Some(b't') => { self.advance(); push_lit(parts, "\t"); display.push('t'); }
                        Some(b'0') => { self.advance(); push_lit(parts, "\0"); display.push('0'); }
                        Some(cc) => {
                            let ch = cc as char;
                            self.advance();
                            display.push(ch);
                            errors.push(format!("{} (line {}, column {}) - invalid escape sequence '\\{}'.",
                                self.path, self.line + 1, esc_col - 1, ch));
                            push_lit(parts, &ch.to_string());
                        }
                        None => break,
                    }
                }
                Some(cc) => {
                    let ch = cc as char;
                    self.advance();
                    push_lit(parts, &ch.to_string());
                    display.push(ch);
                }
            }
        }
    }

    fn lex_cmd_dollar_squote_into(&mut self, parts: &mut Vec<CmdPart>, display: &mut String, errors: &mut Vec<String>) {
        // Same as squote but $ is not special
        self.lex_cmd_squote_into(parts, display, errors);
    }

    fn lex_heredoc_content(&mut self, errors: &mut Vec<String>) -> (String, String) {
        match self.peek() {
            Some(b'\'') => {
                self.advance();
                let mut s = String::new();
                let mut raw = String::from("'");
                loop {
                    match self.peek() {
                        Some(b'\'') => { self.advance(); raw.push('\''); break; }
                        Some(b'\\') => {
                            self.advance();
                            raw.push('\\');
                            match self.peek() {
                                Some(b'\'') => { self.advance(); s.push('\''); raw.push('\''); }
                                Some(b'\\') => { self.advance(); s.push('\\'); raw.push('\\'); }
                                Some(b'n') => { self.advance(); s.push('\n'); raw.push('n'); }
                                Some(b't') => { self.advance(); s.push('\t'); raw.push('t'); }
                                Some(c) => { s.push('\\'); s.push(c as char); self.advance(); raw.push(c as char); }
                                None => break,
                            }
                        }
                        Some(c) => { s.push(c as char); raw.push(c as char); self.advance(); }
                        None => break,
                    }
                }
                (s, raw)
            }
            Some(b'"') => {
                self.advance();
                let mut s = String::new();
                let mut raw = String::from("\"");
                loop {
                    match self.peek() {
                        Some(b'"') => { self.advance(); raw.push('"'); break; }
                        Some(b'\\') => {
                            self.advance();
                            raw.push('\\');
                            match self.peek() {
                                Some(b'"') => { self.advance(); s.push('"'); raw.push('"'); }
                                Some(b'n') => { self.advance(); s.push('\n'); raw.push('n'); }
                                Some(c) => { s.push(c as char); self.advance(); raw.push(c as char); }
                                None => break,
                            }
                        }
                        Some(c) => { s.push(c as char); raw.push(c as char); self.advance(); }
                        None => break,
                    }
                }
                (s, raw)
            }
            _ => {
                // Unquoted word
                let mut s = String::new();
                loop {
                    match self.peek() {
                        Some(c) if !matches!(c, b' '|b'\t'|b'\n'|b';'|b'|'|b'}'|b'#'|b'>') => {
                            s.push(c as char);
                            self.advance();
                        }
                        _ => break,
                    }
                }
                let raw = s.clone();
                (s, raw)
            }
        }
    }

    fn lex_var_name(&mut self) -> Option<String> {
        if self.peek() == Some(b'{') {
            self.advance();
            let mut name = String::new();
            loop {
                match self.peek() {
                    Some(b'}') => { self.advance(); break; }
                    Some(c) if c.is_ascii_alphanumeric() || c == b'_' => {
                        name.push(c as char);
                        self.advance();
                    }
                    _ => break,
                }
            }
            if name.is_empty() { None } else { Some(name) }
        } else if self.peek().map_or(false, |c| c.is_ascii_alphabetic() || c == b'_') {
            let mut name = String::new();
            while let Some(c) = self.peek() {
                if c.is_ascii_alphanumeric() || c == b'_' {
                    name.push(c as char);
                    self.advance();
                } else {
                    break;
                }
            }
            if name.is_empty() { None } else { Some(name) }
        } else {
            None
        }
    }
}

fn float_display(f: f64) -> String {
    if f.fract() == 0.0 && f.is_finite() && f.abs() < 1e15 {
        format!("{}", f as i64)
    } else {
        format!("{}", f)
    }
}

fn push_lit(parts: &mut Vec<CmdPart>, s: &str) {
    if let Some(CmdPart::Lit(last)) = parts.last_mut() {
        last.push_str(s);
    } else {
        parts.push(CmdPart::Lit(s.to_string()));
    }
}

fn merge_lits(parts: Vec<CmdPart>) -> Vec<CmdPart> {
    let mut result: Vec<CmdPart> = Vec::new();
    for p in parts {
        match p {
            CmdPart::Lit(s) => {
                if let Some(CmdPart::Lit(last)) = result.last_mut() {
                    last.push_str(&s);
                } else {
                    result.push(CmdPart::Lit(s));
                }
            }
            other => result.push(other),
        }
    }
    result
}

pub fn display_cmd_word(parts: &[CmdPart]) -> String {
    let mut s = String::new();
    for p in parts {
        match p {
            CmdPart::Lit(l) => s.push_str(l),
            CmdPart::Var(name, _, _) => s.push_str(&format!("${{{{{}}}}}", name)),
        }
    }
    s
}

pub fn token_display_str(kind: &TokenKind) -> String {
    match kind {
        TokenKind::Nil => "nil".into(),
        TokenKind::True => "true".into(),
        TokenKind::False => "false".into(),
        TokenKind::Int(n) => n.to_string(),
        TokenKind::Float(f) => float_display(*f),
        TokenKind::Str(s) => {
            let mut r = String::from("\"");
            for c in s.chars() {
                match c {
                    '\n' => r.push_str("\\n"),
                    '\t' => r.push_str("\\t"),
                    '\0' => r.push_str("\\0"),
                    '\\' => r.push_str("\\\\"),
                    '"' => r.push_str("\\\""),
                    c => r.push(c),
                }
            }
            r.push('"');
            r
        }
        TokenKind::Char(b) => format!("'{}'", *b as char),
        TokenKind::Ident(s) => s.clone(),
        TokenKind::Let => "let".into(),
        TokenKind::Function => "function".into(),
        TokenKind::If => "if".into(),
        TokenKind::Then => "then".into(),
        TokenKind::Else => "else".into(),
        TokenKind::ElseIf => "elseif".into(),
        TokenKind::End => "end".into(),
        TokenKind::While => "while".into(),
        TokenKind::Do => "do".into(),
        TokenKind::For => "for".into(),
        TokenKind::In => "in".into(),
        TokenKind::Return => "return".into(),
        TokenKind::Break => "break".into(),
        TokenKind::Plus => "+".into(),
        TokenKind::Minus => "-".into(),
        TokenKind::Star => "*".into(),
        TokenKind::Slash => "/".into(),
        TokenKind::Percent => "%".into(),
        TokenKind::Eq => "==".into(),
        TokenKind::NotEq => "!=".into(),
        TokenKind::Lt => "<".into(),
        TokenKind::LtEq => "<=".into(),
        TokenKind::Gt => ">".into(),
        TokenKind::GtEq => ">=".into(),
        TokenKind::And => "and".into(),
        TokenKind::Or => "or".into(),
        TokenKind::Not => "not".into(),
        TokenKind::Assign => "=".into(),
        TokenKind::Concat => "++".into(),
        TokenKind::LParen => "(".into(),
        TokenKind::RParen => ")".into(),
        TokenKind::LBracket => "[".into(),
        TokenKind::RBracket => "]".into(),
        TokenKind::AtLBracket => "@[".into(),
        TokenKind::Comma => ",".into(),
        TokenKind::Colon => ":".into(),
        TokenKind::Dot => ".".into(),
        TokenKind::LBrace => "{".into(),
        TokenKind::RBrace => "}".into(),
        TokenKind::DollarLBrace => "${".into(),
        TokenKind::AmpersandLBrace => "&{".into(),
        TokenKind::Semicolon => ";".into(),
        TokenKind::Pipe => "|".into(),
        TokenKind::Arrow => ">".into(),
        TokenKind::Append => ">>".into(),
        TokenKind::Stdin => "<<".into(),
        TokenKind::Question => "?".into(),
        TokenKind::CmdWord(parts) => {
            // Display: show with ${{}varname}} notation
            let mut s = String::new();
            for p in parts {
                match p {
                    CmdPart::Lit(l) => s.push_str(l),
                    CmdPart::Var(name, _, _) => s.push_str(&format!("${{{{{}}}}}", name)),
                }
            }
            s
        }
        TokenKind::Eof => "".into(),
    }
}
