// Hush AST types and display

#[derive(Debug, Clone)]
pub struct Pos {
    pub file: String,
    pub line: usize,  // 0-indexed
    pub col: usize,
}

impl Pos {
    pub fn display(&self) -> String {
        format!("{} (line {}, column {})", self.file, self.line + 1, self.col)
    }
}

impl std::fmt::Display for Pos {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{}", self.display())
    }
}

#[derive(Debug, Clone)]
pub struct Program {
    pub stmts: Vec<Stmt>,
}

#[derive(Debug, Clone)]
pub enum Stmt {
    Let { name: String, value: Option<Expr>, pos: Pos },
    Assign { target: AssignTarget, value: Expr, pos: Pos },
    ExprStmt(Expr),
    Return(Option<Expr>, Pos),
    Break(Pos),
    CmdBlock(CmdBlock),
}

#[derive(Debug, Clone)]
pub enum AssignTarget {
    Var(String, Pos),
    Index(Box<Expr>, Box<Expr>, Pos),
    Field(Box<Expr>, String, Pos),
}

#[derive(Debug, Clone)]
pub enum Expr {
    Nil(Pos),
    True(Pos),
    False(Pos),
    Int(i64, Pos),
    Float(f64, Pos),
    Str(String, Pos),
    Char(u8, Pos),
    Ident(String, Pos),

    UnaryNeg(Box<Expr>, Pos),
    UnaryNot(Box<Expr>, Pos),

    Binary(Box<Expr>, BinOp, Box<Expr>, Pos),

    Array(Vec<Expr>, Pos),
    Dict(Vec<(String, Expr)>, Pos),

    Function { params: Vec<String>, body: Vec<Stmt>, pos: Pos },

    Call(Box<Expr>, Vec<Expr>, Pos),
    MethodCall(Box<Expr>, String, Vec<Expr>, Pos),
    Index(Box<Expr>, Box<Expr>, Pos),
    Field(Box<Expr>, String, Pos),

    If {
        cond: Box<Expr>,
        then_body: Vec<Stmt>,
        else_body: Option<Vec<Stmt>>,
        pos: Pos,
    },

    While(Box<Expr>, Vec<Stmt>, Pos),
    For(String, Box<Expr>, Vec<Stmt>, Pos),

    CmdCapture(CmdBlock, Pos),
    CmdAsync(CmdBlock, Pos),

    Ill,  // parse error placeholder
}

impl Expr {
    pub fn pos(&self) -> &Pos {
        static DUMMY: std::sync::OnceLock<Pos> = std::sync::OnceLock::new();
        let dummy = DUMMY.get_or_init(|| Pos { file: String::new(), line: 0, col: 0 });
        match self {
