            Expr::Binary(_, _, _, p) => p,
            Expr::Array(_, p) | Expr::Dict(_, p) => p,
            Expr::Function { pos, .. } => pos,
            Expr::Call(_, _, p) | Expr::MethodCall(_, _, _, p) => p,
            Expr::Index(_, _, p) | Expr::Field(_, _, p) => p,
            Expr::If { pos, .. } | Expr::While(_, _, p) | Expr::For(_, _, _, p) => pos,
            Expr::CmdCapture(_, p) | Expr::CmdAsync(_, p) => p,
            Expr::Ill => dummy,
        }
    }
}

