        AssignTarget::Index(obj, key, _) => format!("{}[{}]", fmt_expr(obj, indent), fmt_expr(key, indent)),
        AssignTarget::Field(obj, field, _) => format!("{}.{}", fmt_expr(obj, indent), field),
    }
