pub fn fmt_expr(e: &Expr, indent: usize) -> String {
    match e {
        Expr::Nil(_) => "nil".to_string(),
        Expr::True(_) => "true".to_string(),
        Expr::False(_) => "false".to_string(),
        Expr::Int(n, _) => format!("{}", n),
        Expr::Float(f, _) => fmt_float(*f),
        Expr::Str(s, _) => format!("\"{}\"", escape_str_ast(s)),
        Expr::Char(b, _) => format!("'{}'", *b as char),
        Expr::Ident(name, _) => name.clone(),
        Expr::UnaryNeg(e, _) => format!("(-{})", fmt_expr(e, indent)),
        Expr::UnaryNot(e, _) => format!("(not {})", fmt_expr(e, indent)),
        Expr::Binary(l, op, r, _) => {
            let op_s = match op {
                BinOp::Add => "+", BinOp::Sub => "-", BinOp::Mul => "*",
                BinOp::Div => "/", BinOp::Mod => "%",
                BinOp::Eq => "==", BinOp::NotEq => "!=",
                BinOp::Lt => "<", BinOp::LtEq => "<=",
                BinOp::Gt => ">", BinOp::GtEq => ">=",
                BinOp::And => "and", BinOp::Or => "or",
                BinOp::Concat => "++",
            };
            format!("({} {} {})", fmt_expr(l, indent), op_s, fmt_expr(r, indent))
        }
        Expr::Array(items, _) => {
            if items.is_empty() {
                return "[]".to_string();
            }
            let ind = indent_str(indent + 1);
            let ind_close = indent_str(indent);
            let mut s = String::from("[\n");
            for (i, item) in items.iter().enumerate() {
                s.push_str(&format!("{}{}", ind, fmt_expr(item, indent + 1)));
                if i + 1 < items.len() {
                    s.push(',');
                }
                s.push('\n');
            }
            s.push_str(&format!("{}]", ind_close));
            s
        }
        Expr::Dict(pairs, _) => {
            if pairs.is_empty() {
                return "@[]".to_string();
            }
            let ind = indent_str(indent + 1);
            let ind_close = indent_str(indent);
            let mut s = String::from("@[\n");
            for (i, (k, v)) in pairs.iter().enumerate() {
                s.push_str(&format!("{}{}: {}", ind, k, fmt_expr(v, indent + 1)));
                if i + 1 < pairs.len() {
                    s.push(',');
                }
                s.push('\n');
            }
            s.push_str(&format!("{}]", ind_close));
            s
        }
        Expr::Function { params, body, pos } => {
            let params_s = params.join(", ");
            let ind = indent_str(indent);
            let ind_body = indent_str(indent + 1);
            let mut s = format!("function({})\n", params_s);
            for stmt in body {
                let mut buf = String::new();
                fmt_stmt_to_buf(stmt, indent + 1, &mut buf);
                s.push_str(&buf);
            }
            s.push_str(&format!("{}end", ind));
            s
        }
        Expr::Call(callee, args, _) => {
            let args_s: Vec<String> = args.iter().map(|a| fmt_expr(a, indent)).collect();
            format!("{}({})", fmt_expr(callee, indent), args_s.join(", "))
        }
        Expr::MethodCall(obj, method, args, _) => {
            let args_s: Vec<String> = args.iter().map(|a| fmt_expr(a, indent)).collect();
            format!("{}.{}({})", fmt_expr(obj, indent), method, args_s.join(", "))
        }
        Expr::Index(obj, key, _) => {
            format!("{}[{}]", fmt_expr(obj, indent), fmt_expr(key, indent))
        }
        Expr::Field(obj, field, _) => {
            format!("{}.{}", fmt_expr(obj, indent), field)
        }
        Expr::If { cond, then_body, else_body, .. } => {
            let ind = indent_str(indent);
            let ind1 = indent_str(indent + 1);
            let mut s = format!("if {} then\n", fmt_expr(cond, indent));
            for stmt in then_body {
                let mut buf = String::new();
                fmt_stmt_to_buf(stmt, indent + 1, &mut buf);
                s.push_str(&buf);
            }
            if let Some(eb) = else_body {
                s.push_str(&format!("{}else\n", ind));
                for stmt in eb {
                    let mut buf = String::new();
                    fmt_stmt_to_buf(stmt, indent + 1, &mut buf);
                    s.push_str(&buf);
                }
            }
            s.push_str(&format!("{}end", ind));
            s
        }
        Expr::While(cond, body, _) => {
            let ind = indent_str(indent);
            let mut s = format!("while {} do\n", fmt_expr(cond, indent));
            for stmt in body {
                let mut buf = String::new();
                fmt_stmt_to_buf(stmt, indent + 1, &mut buf);
                s.push_str(&buf);
            }
            s.push_str(&format!("{}end", ind));
            s
        }
        Expr::For(var, iter, body, _) => {
            let ind = indent_str(indent);
            let mut s = format!("for {} in {} do\n", var, fmt_expr(iter, indent));
            for stmt in body {
                let mut buf = String::new();
                fmt_stmt_to_buf(stmt, indent + 1, &mut buf);
                s.push_str(&buf);
            }
            s.push_str(&format!("{}end", ind));
            s
        }
        Expr::CmdCapture(block, _) => {
            fmt_capture_block("$", block, indent)
        }
        Expr::CmdAsync(block, _) => {
            fmt_capture_block("&", block, indent)
        }
        Expr::Ill => "***ill-formed***".to_string(),
    }
}

fn fmt_capture_block(prefix: &str, block: &CmdBlock, indent: usize) -> String {
    let ind = indent_str(indent);
    let ind1 = indent_str(indent + 1);
    let mut s = format!("{}${{\n", ind);
    // Wait, this is called from fmt_expr which already has indent
    // Let me reconsider...
    let mut s = format!("${{\n");
    for (i, cmd) in block.cmds.iter().enumerate() {
        s.push_str(&format!("{}{}", ind1, fmt_cmd_cmd(cmd, indent + 1)));
        if i + 1 < block.cmds.len() {
            s.push(';');
        }
        s.push('\n');
    }
    s.push_str(&format!("{}}}", ind));
    s
}

fn fmt_cmd_block_display(block: &CmdBlock, indent: usize) -> String {
    let ind = indent_str(indent);
    let ind1 = indent_str(indent + 1);
    let mut s = format!("{}{{\n", ind);
    for (i, cmd) in block.cmds.iter().enumerate() {
        s.push_str(&format!("{}{}", ind1, fmt_cmd_cmd(cmd, indent + 1)));
        if i + 1 < block.cmds.len() {
            s.push(';');
        }
        s.push('\n');
    }
    s.push_str(&format!("{}}}\n", ind));
    s
}

fn fmt_cmd_cmd(cmd: &CmdCmd, indent: usize) -> String {
    let mut pipeline_parts: Vec<String> = Vec::new();

    for (i, part) in cmd.pipeline.iter().enumerate() {
        let is_last = i + 1 == cmd.pipeline.len();
        let mut s = fmt_pipe_part(part);
        if part.allow_fail && !is_last {
            s.push_str(" ?");
        }
        pipeline_parts.push(s);
    }

    let mut result = pipeline_parts.join(" | ");

    if cmd.allow_fail {
        result.push_str(" ?");
    }

    result
}

fn fmt_pipe_part(part: &CmdPipePart) -> String {
    let mut parts: Vec<String> = part.cmd.iter().map(|a| fmt_arg_ast(a)).collect();

    for redir in &part.redirects {
        match redir {
            Redirect::Out(fd, target, append) => {
                let op = if *append { ">>" } else { ">" };
                if *fd == 1 {
                    parts.push(format!("{}{}", op, fmt_arg_ast(target)));
                } else {
                    parts.push(format!("{}{}{}", fd, op, fmt_arg_ast(target)));
                }
            }
            Redirect::Err2Out => parts.push("2>1".to_string()),
            Redirect::Out2Err => parts.push("1>2".to_string()),
            Redirect::Stdin(s) => {
                let escaped = escape_str_ast(s);
                parts.push(format!("<<\"{}\"", escaped));
            }
        }
    }

    parts.join(" ")
}

fn fmt_arg_ast(arg: &CmdArg) -> String {
    match arg {
        CmdArg::Parts(parts) => {
            if parts.len() == 1 {
                match &parts[0] {
                    ArgPart::Lit(s) => {
                        // Check if it looks like a literal word (no special chars that need quoting)
                        // We use double-quoted form in AST output
                        return format!("\"{}\"", escape_str_ast(s));
                    }
                    ArgPart::Var(name, _) => {
                        return format!("\"${{{}}}\"", name);
                    }
                }
            }
            // Mixed parts - show as double-quoted
            let mut s = String::from("\"");
            for part in parts {
                match part {
                    ArgPart::Lit(l) => s.push_str(&escape_str_ast(l)),
                    ArgPart::Var(name, _) => s.push_str(&format!("${{{}}}", name)),
                }
            }
            s.push('"');
            s
        }
    }
}

fn escape_str_ast(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '\n' => result.push_str("\\n"),
            '\t' => result.push_str("\\t"),
            '\0' => result.push_str("\\0"),
            '\\' => result.push_str("\\\\"),
            '"' => result.push_str("\\\""),
            c => result.push(c),
        }
    }
    result
}

pub fn fmt_float(f: f64) -> String {
    if f.is_nan() { return "NaN".to_string(); }
    if f.is_infinite() {
        return if f > 0.0 { "inf".to_string() } else { "-inf".to_string() };
    }
    // Use Rust's default float formatting
    let s = format!("{}", f);
    // If no decimal point and no 'e', add .0
    if !s.contains('.') && !s.contains('e') && !s.contains('n') && !s.contains('i') {
        format!("{}.0", s)
    } else {
        s
    }
}

fn print_cmd_block(block: &CmdBlock, indent: usize) {
    let ind = indent_str(indent);
    let ind1 = indent_str(indent + 1);
    println!("{}{{\n{}", ind, ""); // avoid trailing newline on {
    print!("{}{{\n", ind);
    for (i, cmd) in block.cmds.iter().enumerate() {
        print!("{}{}", ind1, fmt_cmd_cmd(cmd, indent + 1));
        if i + 1 < block.cmds.len() {
            print!(";");
        }
        println!();
    }
    println!("{}}}", ind);
}

fn fmt_stmt_to_buf(stmt: &Stmt, indent: usize, buf: &mut String) {
    let ind = indent_str(indent);
    match stmt {
        Stmt::Let { name, value, .. } => {
            if let Some(v) = value {
                buf.push_str(&format!("{}let {} = {}\n", ind, name, fmt_expr(v, indent)));
            } else {
                buf.push_str(&format!("{}let {} = nil\n", ind, name));
            }
        }
        Stmt::Assign { target, value, .. } => {
            buf.push_str(&format!("{}{} = {}\n", ind, fmt_assign_target(target, indent), fmt_expr(value, indent)));
        }
        Stmt::ExprStmt(e) => {
            buf.push_str(&format!("{}{}\n", ind, fmt_expr(e, indent)));
        }
        Stmt::Return(v, _) => {
            if let Some(e) = v {
                buf.push_str(&format!("{}return {}\n", ind, fmt_expr(e, indent)));
            } else {
                buf.push_str(&format!("{}return\n", ind));
            }
        }
        Stmt::Break(_) => {
            buf.push_str(&format!("{}break\n", ind));
        }
        Stmt::CmdBlock(block) => {
            buf.push_str(&fmt_cmd_block_display(block, indent));
        }
    }
}
