fn fmt_pipe_part(part: &CmdPipePart) -> String {
    let mut parts: Vec<String> = part.cmd.iter().map(|a| fmt_arg_ast(a)).collect();

    for redir in &part.redirects {
        match redir {
            Redirect::Out(fd, target, append) => {
                let op = if *append { ">>" } else { ">" };
                if *fd == 1 {
                    parts.push(format!("{}{}", op, fmt_arg_ast(target)));
                } else {
                    parts.push(format!("{}{}{}", fd, op, fmt_arg_ast(target)));
                }
            }
            Redirect::Err2Out => parts.push("2>1".to_string()),
            Redirect::Out2Err => parts.push("1>2".to_string()),
            Redirect::Stdin(s) => {
                let escaped = escape_str_ast(s);
                parts.push(format!("<<\"{}\"", escaped));
            }
        }
    }

    parts.join(" ")
}

fn fmt_arg_ast(arg: &CmdArg) -> String {
    match arg {
        CmdArg::Parts(parts) => {
            if parts.len() == 1 {
                match &parts[0] {
                    ArgPart::Lit(s) => {
                        // Check if it looks like a literal word (no special chars that need quoting)
                        // We use double-quoted form in AST output
                        return format!("\"{}\"", escape_str_ast(s));
                    }
                    ArgPart::Var(name, _) => {
                        return format!("\"${{{}}}\"", name);
                    }
                }
            }
            // Mixed parts - show as double-quoted
            let mut s = String::from("\"");
            for part in parts {
                match part {
                    ArgPart::Lit(l) => s.push_str(&escape_str_ast(l)),
                    ArgPart::Var(name, _) => s.push_str(&format!("${{{}}}", name)),
                }
            }
            s.push('"');
            s
        }
    }
}

fn escape_str_ast(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '\n' => result.push_str("\\n"),
            '\t' => result.push_str("\\t"),
            '\0' => result.push_str("\\0"),
            '\\' => result.push_str("\\\\"),
            '"' => result.push_str("\\\""),
            c => result.push(c),
        }
    }
    result
}

pub fn fmt_float(f: f64) -> String {
    if f.is_nan() { return "NaN".to_string(); }
    if f.is_infinite() {
        return if f > 0.0 { "inf".to_string() } else { "-inf".to_string() };
    }
    // Use Rust's default float formatting
    let s = format!("{}", f);
    // If no decimal point and no 'e', add .0
    if !s.contains('.') && !s.contains('e') && !s.contains('n') && !s.contains('i') {
        format!("{}.0", s)
    } else {
        s
    }
}

fn print_cmd_block(block: &CmdBlock, indent: usize) {
    let ind = indent_str(indent);
    let ind1 = indent_str(indent + 1);
