            buf.push_str(&format!("{}{} = {}\n", ind, fmt_assign_target(target, indent), fmt_expr(value, indent)));
        }
        Stmt::ExprStmt(e) => {
            buf.push_str(&format!("{}{}\n", ind, fmt_expr(e, indent)));
        }
        Stmt::Return(v, _) => {
            if let Some(e) = v {
                buf.push_str(&format!("{}return {}\n", ind, fmt_expr(e, indent)));
            } else {
                buf.push_str(&format!("{}return\n", ind));
            }
        }
        Stmt::Break(_) => {
            buf.push_str(&format!("{}break\n", ind));
        }
        Stmt::CmdBlock(block) => {
            buf.push_str(&fmt_cmd_block_display(block, indent));
        }
    }
}
