impl Expr {
    pub fn pos(&self) -> &Pos {
        static DUMMY: std::sync::OnceLock<Pos> = std::sync::OnceLock::new();
        let dummy = DUMMY.get_or_init(|| Pos { file: String::new(), line: 0, col: 0 });
        match self {
