// Hush Parser

use crate::lexer::{Token, TokenKind, CmdPart};
use crate::ast::*;

pub fn parse(tokens: &[Token], path: &str) -> (Program, Vec<String>) {
    let mut p = Parser::new(tokens, path);
    let prog = p.parse_program();
    (prog, p.errors)
}

struct Parser<'a> {
    tokens: &'a [Token],
    pos: usize,
    path: String,
    errors: Vec<String>,
}

impl<'a> Parser<'a> {
    fn new(tokens: &'a [Token], path: &str) -> Self {
        Parser { tokens, pos: 0, path: path.to_string(), errors: Vec::new() }
    }

    fn peek(&self) -> &Token {
        let idx = self.pos.min(self.tokens.len() - 1);
        &self.tokens[idx]
    }

    fn peek_kind(&self) -> &TokenKind {
        &self.peek().kind
    }

    fn look_ahead(&self, n: usize) -> &Token {
        let idx = (self.pos + n).min(self.tokens.len() - 1);
        &self.tokens[idx]
    }

    fn advance(&mut self) -> &Token {
        let tok = &self.tokens[self.pos];
        if self.pos + 1 < self.tokens.len() {
            self.pos += 1;
        }
        tok
    }

    fn pos_of(&self, tok: &Token) -> Pos {
        Pos { file: self.path.clone(), line: tok.line, col: tok.col }
    }

    fn current_pos(&self) -> Pos {
        self.pos_of(self.peek())
    }

    fn error_at(&mut self, tok: &Token, msg: &str) {
        self.errors.push(format!("{} (line {}, column {}) - {}",
            self.path, tok.line + 1, tok.col, msg));
    }

    fn error_eof(&mut self) {
        self.errors.push("Error: unexpected end of file".to_string());
    }

    fn expect(&mut self, kind: &TokenKind) -> bool {
        if std::mem::discriminant(self.peek_kind()) == std::mem::discriminant(kind) {
            self.advance();
            true
        } else {
            let tok = self.peek().clone();
            let got = tok_display(&tok.kind);
            let want = tok_display(kind);
            self.error_at(&tok, &format!("unexpected '{}', expected '{}'", got, want));
            false
        }
    }

    fn expect_ident(&mut self) -> Option<String> {
        let tok = self.peek().clone();
        if let TokenKind::Ident(name) = &tok.kind {
            let name = name.clone();
            self.advance();
            Some(name)
        } else {
            let got = tok_display(&tok.kind);
            self.error_at(&tok, &format!("unexpected '{}', expected identifier", got));
            None
        }
    }

    fn parse_program(&mut self) -> Program {
        let stmts = self.parse_stmts(0);
        if !matches!(self.peek_kind(), TokenKind::Eof) {
            let tok = self.peek().clone();
            self.error_at(&tok, &format!("unexpected '{}'", tok_display(&tok.kind)));
        }
        Program { stmts }
    }

    fn parse_stmts(&mut self, loop_depth: usize) -> Vec<Stmt> {
        let mut stmts = Vec::new();
        loop {
            match self.peek_kind() {
                TokenKind::Eof | TokenKind::End | TokenKind::Else | TokenKind::ElseIf => break,
                _ => {
                    match self.parse_stmt(loop_depth) {
                        Some(s) => stmts.push(s),
                        None => {
                            // Recovery: skip tokens until we find something stable
                            if !matches!(self.peek_kind(), 
                                TokenKind::Eof | TokenKind::End | TokenKind::Else | TokenKind::ElseIf) {
                                self.advance();
                            } else {
                                break;
                            }
                        }
                    }
                }
            }
        }
        stmts
    }

    fn parse_stmt(&mut self, loop_depth: usize) -> Option<Stmt> {
        let tok = self.peek().clone();
        match &tok.kind {
            TokenKind::Let => {
                self.advance();
                self.parse_let_stmt(loop_depth)
            }
            TokenKind::Function => {
                let pos = self.pos_of(&tok);
                self.advance();
                // Named function: function name(...) body end
                // OR anonymous: function(...) body end
                if let TokenKind::Ident(name) = self.peek_kind().clone() {
                    self.advance();
                    let (params, body) = self.parse_func_rest(loop_depth)?;
                    let func = Expr::Function { params, body, pos: pos.clone() };
                    Some(Stmt::Let { name, value: Some(func), pos })
                } else {
                    // Anonymous function as statement
                    let (params, body) = self.parse_func_rest(loop_depth)?;
                    Some(Stmt::ExprStmt(Expr::Function { params, body, pos }))
                }
            }
            TokenKind::Return => {
                let pos = self.pos_of(&tok);
                self.advance();
                // Return value is optional - check if next token starts an expression
                let val = if can_start_expr(self.peek_kind()) {
                    Some(self.parse_expr(loop_depth)?)
                } else {
                    None
                };
                Some(Stmt::Return(val, pos))
            }
            TokenKind::Break => {
                let pos = self.pos_of(&tok);
                self.advance();
                if loop_depth == 0 {
                    self.error_at(&tok, "break statement outside loop");
                }
                Some(Stmt::Break(pos))
            }
            TokenKind::LBrace => {
                let pos = self.pos_of(&tok);
                self.advance();
                let block = self.parse_cmd_block_body()?;
                Some(Stmt::CmdBlock(block))
            }
            _ => {
                // Expression or assignment
                let expr = self.parse_expr(loop_depth)?;

                if matches!(self.peek_kind(), TokenKind::Assign) {
                    let pos = self.current_pos();
                    self.advance();
                    let val = self.parse_expr(loop_depth)?;
                    let target = expr_to_target(expr, pos.clone())?;
                    Some(Stmt::Assign { target, value: val, pos })
                } else {
                    Some(Stmt::ExprStmt(expr))
                }
            }
        }
    }

    fn parse_let_stmt(&mut self, loop_depth: usize) -> Option<Stmt> {
        let tok = self.peek().clone();
        let name = self.expect_ident()?;
        let pos = self.pos_of(&tok);

        let value = if matches!(self.peek_kind(), TokenKind::Assign) {
            self.advance();
            Some(self.parse_expr(loop_depth)?)
        } else {
            None
        };

        Some(Stmt::Let { name, value, pos })
    }

    fn parse_func_rest(&mut self, loop_depth: usize) -> Option<(Vec<String>, Vec<Stmt>)> {
        if !self.expect(&TokenKind::LParen) {
            return None;
        }

        let mut params = Vec::new();
        loop {
            match self.peek_kind().clone() {
                TokenKind::RParen => {
                    self.advance();
                    break;
                }
                TokenKind::Ident(name) => {
                    self.advance();
                    params.push(name);
                    match self.peek_kind() {
                        TokenKind::Comma => { self.advance(); }
                        TokenKind::RParen => {}
                        _ => {
                            let tok = self.peek().clone();
                            self.error_at(&tok, &format!("unexpected '{}', expected ')'", tok_display(&tok.kind)));
                        }
                    }
                }
                _ => {
                    let tok = self.peek().clone();
                    if matches!(tok.kind, TokenKind::Eof) {
                        self.error_eof();
                    } else {
                        self.error_at(&tok, &format!("unexpected '{}', expected identifier or ')'", tok_display(&tok.kind)));
                        self.advance();
                    }
                    break;
                }
            }
        }

        let body = self.parse_stmts(0);  // functions reset loop depth

        if !self.expect(&TokenKind::End) {
            if matches!(self.peek_kind(), TokenKind::Eof) {
                self.error_eof();
            }
        }

        Some((params, body))
    }

    fn parse_expr(&mut self, loop_depth: usize) -> Option<Expr> {
        self.parse_or(loop_depth)
    }

    fn parse_or(&mut self, loop_depth: usize) -> Option<Expr> {
        let mut left = self.parse_and(loop_depth)?;
        while matches!(self.peek_kind(), TokenKind::Or) {
            let pos = self.current_pos();
            self.advance();
            let right = self.parse_and(loop_depth)?;
            left = Expr::Binary(Box::new(left), BinOp::Or, Box::new(right), pos);
        }
        Some(left)
    }

    fn parse_and(&mut self, loop_depth: usize) -> Option<Expr> {
        let mut left = self.parse_cmp(loop_depth)?;
        while matches!(self.peek_kind(), TokenKind::And) {
            let pos = self.current_pos();
            self.advance();
            let right = self.parse_cmp(loop_depth)?;
            left = Expr::Binary(Box::new(left), BinOp::And, Box::new(right), pos);
        }
        Some(left)
    }

    fn parse_cmp(&mut self, loop_depth: usize) -> Option<Expr> {
        let mut left = self.parse_concat(loop_depth)?;
        loop {
            let op = match self.peek_kind() {
                TokenKind::Eq => BinOp::Eq,
                TokenKind::NotEq => BinOp::NotEq,
                TokenKind::Lt => BinOp::Lt,
                TokenKind::LtEq => BinOp::LtEq,
                TokenKind::Gt => BinOp::Gt,
                TokenKind::GtEq => BinOp::GtEq,
                _ => break,
            };
            let pos = self.current_pos();
            self.advance();
            let right = self.parse_concat(loop_depth)?;
            left = Expr::Binary(Box::new(left), op, Box::new(right), pos);
        }
        Some(left)
    }

    fn parse_concat(&mut self, loop_depth: usize) -> Option<Expr> {
        let mut left = self.parse_add(loop_depth)?;
        while matches!(self.peek_kind(), TokenKind::Concat) {
            let pos = self.current_pos();
            self.advance();
            let right = self.parse_add(loop_depth)?;
            left = Expr::Binary(Box::new(left), BinOp::Concat, Box::new(right), pos);
        }
        Some(left)
    }

    fn parse_add(&mut self, loop_depth: usize) -> Option<Expr> {
        let mut left = self.parse_mul(loop_depth)?;
        loop {
            let op = match self.peek_kind() {
                TokenKind::Plus => BinOp::Add,
                TokenKind::Minus => BinOp::Sub,
                _ => break,
            };
            let pos = self.current_pos();
            self.advance();
            let right = self.parse_mul(loop_depth)?;
            left = Expr::Binary(Box::new(left), op, Box::new(right), pos);
        }
        Some(left)
    }

    fn parse_mul(&mut self, loop_depth: usize) -> Option<Expr> {
        let mut left = self.parse_unary(loop_depth)?;
        loop {
            let op = match self.peek_kind() {
                TokenKind::Star => BinOp::Mul,
                TokenKind::Slash => BinOp::Div,
                TokenKind::Percent => BinOp::Mod,
                _ => break,
            };
            let pos = self.current_pos();
            self.advance();
            let right = self.parse_unary(loop_depth)?;
            left = Expr::Binary(Box::new(left), op, Box::new(right), pos);
        }
        Some(left)
    }

    fn parse_unary(&mut self, loop_depth: usize) -> Option<Expr> {
        let tok = self.peek().clone();
        match &tok.kind {
            TokenKind::Minus => {
                let pos = self.pos_of(&tok);
                self.advance();
                let e = self.parse_unary(loop_depth)?;
                Some(Expr::UnaryNeg(Box::new(e), pos))
            }
            TokenKind::Not => {
                let pos = self.pos_of(&tok);
                self.advance();
                let e = self.parse_unary(loop_depth)?;
                Some(Expr::UnaryNot(Box::new(e), pos))
            }
            _ => self.parse_postfix(loop_depth),
        }
    }

    fn parse_postfix(&mut self, loop_depth: usize) -> Option<Expr> {
        let mut e = self.parse_primary(loop_depth)?;

        loop {
            match self.peek_kind().clone() {
                TokenKind::Dot => {
                    let pos = self.current_pos();
                    self.advance();
                    let tok = self.peek().clone();
                    let field = self.expect_ident()?;
                    if matches!(self.peek_kind(), TokenKind::LParen) {
                        let call_pos = self.current_pos();
                        self.advance();
                        let args = self.parse_call_args(loop_depth)?;
                        e = Expr::MethodCall(Box::new(e), field, args, call_pos);
                    } else {
                        e = Expr::Field(Box::new(e), field, pos);
                    }
                }
                TokenKind::LBracket => {
                    let pos = self.current_pos();
                    self.advance();
                    let key = self.parse_expr(loop_depth)?;
                    if !self.expect(&TokenKind::RBracket) {}
                    e = Expr::Index(Box::new(e), Box::new(key), pos);
                }
                TokenKind::LParen => {
                    let pos = self.current_pos();
                    self.advance();
                    let args = self.parse_call_args(loop_depth)?;
                    e = Expr::Call(Box::new(e), args, pos);
                }
                _ => break,
            }
        }

        Some(e)
    }

    fn parse_call_args(&mut self, loop_depth: usize) -> Option<Vec<Expr>> {
        let mut args = Vec::new();
        loop {
            if matches!(self.peek_kind(), TokenKind::RParen) {
                self.advance();
                break;
            }
            let arg = self.parse_expr(loop_depth)?;
            args.push(arg);
            match self.peek_kind() {
                TokenKind::Comma => { self.advance(); }
                TokenKind::RParen => { self.advance(); break; }
                _ => {
                    let tok = self.peek().clone();
                    self.error_at(&tok, &format!("unexpected '{}', expected ')'", tok_display(&tok.kind)));
                    return None;
                }
            }
        }
        Some(args)
    }

    fn parse_primary(&mut self, loop_depth: usize) -> Option<Expr> {
        let tok = self.peek().clone();
        let pos = self.pos_of(&tok);

        match tok.kind.clone() {
            TokenKind::Nil => { self.advance(); Some(Expr::Nil(pos)) }
            TokenKind::True => { self.advance(); Some(Expr::True(pos)) }
            TokenKind::False => { self.advance(); Some(Expr::False(pos)) }
            TokenKind::Int(n) => { self.advance(); Some(Expr::Int(n, pos)) }
            TokenKind::Float(f) => { self.advance(); Some(Expr::Float(f, pos)) }
            TokenKind::Str(s) => { self.advance(); Some(Expr::Str(s, pos)) }
            TokenKind::Char(b) => { self.advance(); Some(Expr::Char(b, pos)) }
            TokenKind::Ident(name) => { self.advance(); Some(Expr::Ident(name, pos)) }

            TokenKind::LParen => {
                self.advance();
                let e = self.parse_expr(loop_depth)?;
                if !self.expect(&TokenKind::RParen) {}
                Some(e)
            }

            TokenKind::LBracket => {
                self.advance();
                let mut items = Vec::new();
                loop {
                    if matches!(self.peek_kind(), TokenKind::RBracket) {
                        self.advance();
                        break;
                    }
                    if matches!(self.peek_kind(), TokenKind::Eof) {
                        self.error_eof();
                        break;
                    }
                    let item = self.parse_expr(loop_depth)?;
                    items.push(item);
                    match self.peek_kind() {
                        TokenKind::Comma => { self.advance(); }
                        TokenKind::RBracket => { self.advance(); break; }
                        _ => {
                            let t = self.peek().clone();
                            self.error_at(&t, &format!("unexpected '{}', expected ']'", tok_display(&t.kind)));
                            break;
                        }
                    }
                }
                Some(Expr::Array(items, pos))
            }

            TokenKind::AtLBracket => {
                self.advance();
                let mut pairs = Vec::new();
                loop {
                    if matches!(self.peek_kind(), TokenKind::RBracket) {
                        self.advance();
                        break;
                    }
                    if matches!(self.peek_kind(), TokenKind::Eof) {
                        self.error_eof();
                        break;
                    }
                    let key_tok = self.peek().clone();
                    let key = self.expect_ident()?;
                    if !self.expect(&TokenKind::Colon) { return None; }
                    let val = self.parse_expr(loop_depth)?;
                    pairs.push((key, val));
                    match self.peek_kind() {
                        TokenKind::Comma => { self.advance(); }
                        TokenKind::RBracket => { self.advance(); break; }
                        _ => {
                            let t = self.peek().clone();
                            self.error_at(&t, &format!("unexpected '{}', expected ']'", tok_display(&t.kind)));
                            break;
                        }
                    }
                }
                Some(Expr::Dict(pairs, pos))
            }

            TokenKind::Function => {
                self.advance();
                // Check if named (at primary level, it's always anonymous)
                let (params, body) = self.parse_func_rest(loop_depth)?;
                Some(Expr::Function { params, body, pos })
            }

            TokenKind::If => {
                self.advance();
                self.parse_if_expr(loop_depth, pos)
            }

            TokenKind::While => {
                self.advance();
                let cond = self.parse_expr(loop_depth)?;
                if !self.expect(&TokenKind::Do) {}
                let body = self.parse_stmts(loop_depth + 1);
                if !self.expect(&TokenKind::End) {
                    if matches!(self.peek_kind(), TokenKind::Eof) {
                        self.error_eof();
                    }
                }
                Some(Expr::While(Box::new(cond), body, pos))
            }

            TokenKind::For => {
                self.advance();
                let var = self.expect_ident()?;
                if !self.expect(&TokenKind::In) {}
                let iter = self.parse_expr(loop_depth)?;
                if !self.expect(&TokenKind::Do) {}
                let body = self.parse_stmts(loop_depth + 1);
                if !self.expect(&TokenKind::End) {
                    if matches!(self.peek_kind(), TokenKind::Eof) {
                        self.error_eof();
                    }
                }
                Some(Expr::For(var, Box::new(iter), body, pos))
            }

            TokenKind::DollarLBrace => {
                self.advance();
                let block = self.parse_cmd_block_body()?;
                Some(Expr::CmdCapture(block, pos))
            }

            TokenKind::AmpersandLBrace => {
                self.advance();
                let block = self.parse_cmd_block_body()?;
                Some(Expr::CmdAsync(block, pos))
            }

            TokenKind::LBrace => {
                // Command block as expression (like in function return)
                // Treat as CmdCapture? No - it executes and produces output
                self.advance();
                let block = self.parse_cmd_block_body()?;
                // When used as expression, it's a side-effecting block
                // Looking at examples, {..} as expression pipes output
                // For now, treat as CmdCapture
                Some(Expr::CmdCapture(block, pos))
            }

            kind => {
                if matches!(kind, TokenKind::Eof) {
                    self.error_eof();
                } else {
                    self.error_at(&tok, &format!("unexpected '{}', expected expression", tok_display(&kind)));
                }
                None
            }
        }
    }

    fn parse_if_expr(&mut self, loop_depth: usize, pos: Pos) -> Option<Expr> {
        let cond = self.parse_expr(loop_depth)?;
        if !self.expect(&TokenKind::Then) {}
        let then_body = self.parse_stmts(loop_depth);

        // Process elseif and else as nested if-else
        let else_body = self.parse_else_chain(loop_depth)?;

        if !self.expect(&TokenKind::End) {
            if matches!(self.peek_kind(), TokenKind::Eof) {
                self.error_eof();
            }
        }

        Some(Expr::If { cond: Box::new(cond), then_body, else_body, pos })
    }

    fn parse_else_chain(&mut self, loop_depth: usize) -> Option<Option<Vec<Stmt>>> {
        match self.peek_kind().clone() {
            TokenKind::End => {
                // Will be consumed by caller
                Some(None)
            }
            TokenKind::Else => {
                self.advance();
                let body = self.parse_stmts(loop_depth);
                Some(Some(body))
            }
            TokenKind::ElseIf => {
                self.advance();
                let pos = self.current_pos();
                let inner = self.parse_if_expr(loop_depth, pos)?;
                // The elseif desugars to an else with a nested if
                Some(Some(vec![Stmt::ExprStmt(inner)]))
            }
            _ => {
                // Error case
                let tok = self.peek().clone();
                self.error_at(&tok, "expected 'elseif', 'else', or 'end'");
                Some(None)
            }
        }
    }

    // Parse command block body (after { has been consumed)
    fn parse_cmd_block_body(&mut self) -> Option<CmdBlock> {
        let mut cmds = Vec::new();

        loop {
            // Skip any trailing semicolons
            while matches!(self.peek_kind(), TokenKind::Semicolon) {
                self.advance();
            }

            match self.peek_kind() {
                TokenKind::RBrace | TokenKind::Eof => break,
                _ => {}
            }

            match self.parse_cmd_seq() {
                Some(cmd) => {
                    let has_semicolon = matches!(self.peek_kind(), TokenKind::Semicolon);
                    cmds.push(cmd);
                    if has_semicolon {
                        self.advance();
                    } else {
                        match self.peek_kind() {
                            TokenKind::RBrace | TokenKind::Eof => break,
                            _ => {}
                        }
                    }
                }
                None => {
                    // Error recovery
                    loop {
                        match self.peek_kind() {
                            TokenKind::Semicolon => { self.advance(); break; }
                            TokenKind::RBrace | TokenKind::Eof => break,
                            _ => { self.advance(); }
                        }
                    }
                }
            }
        }

        if matches!(self.peek_kind(), TokenKind::RBrace) {
            self.advance();
        } else {
            self.error_eof();
        }

        Some(CmdBlock { cmds })
    }

    fn parse_cmd_seq(&mut self) -> Option<CmdCmd> {
        let pipeline = self.parse_cmd_pipeline()?;

        let allow_fail = if matches!(self.peek_kind(), TokenKind::Question) {
            self.advance();
            true
        } else {
            false
        };

        Some(CmdCmd { pipeline, allow_fail })
    }

    fn parse_cmd_pipeline(&mut self) -> Option<Vec<CmdPipePart>> {
        let mut parts = Vec::new();

        let first = self.parse_cmd_part()?;
        parts.push(first);

        // Check for ? | (allow_fail in pipe)
        loop {
            let allow_fail = if matches!(self.peek_kind(), TokenKind::Question) {
                // Lookahead: is this ? followed by |?
                if matches!(self.look_ahead(1).kind, TokenKind::Pipe) {
                    self.advance(); // consume ?
                    // Mark previous part as allow_fail
                    if let Some(last) = parts.last_mut() {
                        last.allow_fail = true;
                    }
                    true
                } else {
                    break; // ? at end of sequence
                }
            } else {
                false
            };

            if matches!(self.peek_kind(), TokenKind::Pipe) {
                self.advance();
                match self.parse_cmd_part() {
                    Some(part) => parts.push(part),
                    None => {
                        let tok = self.peek().clone();
                        self.error_at(&tok, &format!("unexpected '{}', expected argument", tok_display(&tok.kind)));
                        return None;
                    }
                }
            } else {
                break;
            }
        }

        Some(parts)
    }

    fn parse_cmd_part(&mut self) -> Option<CmdPipePart> {
        let mut cmd_args: Vec<CmdArg> = Vec::new();
        let mut redirects: Vec<Redirect> = Vec::new();

        // Must have at least one argument
        loop {
            match self.peek_kind().clone() {
                TokenKind::Semicolon | TokenKind::RBrace | TokenKind::Eof
                | TokenKind::Pipe | TokenKind::Question => break,

                TokenKind::Arrow => {
                    // > redirect
                    self.advance();
                    match self.parse_cmd_arg() {
                        Some(target) => redirects.push(Redirect::Out(1, target, false)),
                        None => {
                            let tok = self.peek().clone();
                            self.error_at(&tok, &format!("unexpected '{}', expected argument", tok_display(&tok.kind)));
                            return None;
                        }
                    }
                }
                TokenKind::Append => {
                    // >> redirect
                    self.advance();
                    match self.parse_cmd_arg() {
                        Some(target) => redirects.push(Redirect::Out(1, target, true)),
                        None => {
                            let tok = self.peek().clone();
                            self.error_at(&tok, &format!("unexpected '{}', expected argument", tok_display(&tok.kind)));
                            return None;
                        }
                    }
                }
                TokenKind::Stdin => {
                    // << heredoc
                    self.advance();
                    let content = self.parse_heredoc_arg();
                    redirects.push(Redirect::Stdin(content));
                }
                TokenKind::Int(n) => {
                    let fd = n as i32;
                    // Check for fd > or fd >>
                    match self.look_ahead(1).kind.clone() {
                        TokenKind::Arrow => {
                            self.advance(); // consume fd number
                            self.advance(); // consume >
                            // Check if target is int (fd number)
                            match self.peek_kind().clone() {
                                TokenKind::Int(target_fd) => {
                                    let t = target_fd as i32;
                                    self.advance();
                                    if fd == 2 && t == 1 {
                                        redirects.push(Redirect::Err2Out);
                                    } else if fd == 1 && t == 2 {
                                        redirects.push(Redirect::Out2Err);
                                    } else {
                                        // Generic fd redirect
                                        redirects.push(Redirect::Out(fd, CmdArg::from_lit(&t.to_string()), false));
                                    }
                                }
                                _ => {
                                    match self.parse_cmd_arg() {
                                        Some(target) => redirects.push(Redirect::Out(fd, target, false)),
                                        None => {
                                            let tok = self.peek().clone();
                                            self.error_at(&tok, &format!("unexpected '{}', expected argument", tok_display(&tok.kind)));
                                            return None;
                                        }
                                    }
                                }
                            }
                        }
                        TokenKind::Append => {
                            self.advance(); // consume fd
                            self.advance(); // consume >>
                            match self.parse_cmd_arg() {
                                Some(target) => redirects.push(Redirect::Out(fd, target, true)),
                                None => {
                                    let tok = self.peek().clone();
                                    self.error_at(&tok, &format!("unexpected '{}', expected argument", tok_display(&tok.kind)));
                                    return None;
                                }
                            }
                        }
                        _ => {
                            // It's just an integer argument
                            match self.parse_cmd_arg() {
                                Some(arg) => cmd_args.push(arg),
                                None => break,
                            }
                        }
                    }
                }
                _ => {
                    match self.parse_cmd_arg() {
                        Some(arg) => cmd_args.push(arg),
                        None => break,
                    }
                }
            }
        }

        if cmd_args.is_empty() && redirects.is_empty() {
            // Empty command - error unless at start
            let tok = self.peek().clone();
            match &tok.kind {
                TokenKind::Arrow | TokenKind::Append | TokenKind::Stdin => {
                    self.error_at(&tok, &format!("unexpected '{}', expected argument", tok_display(&tok.kind)));
                    return None;
                }
                TokenKind::Pipe => {
                    self.error_at(&tok, &format!("unexpected '{}', expected argument", tok_display(&tok.kind)));
                    return None;
                }
                _ => {}
            }
            return None;
        }

        Some(CmdPipePart { cmd: cmd_args, redirects, allow_fail: false })
    }

    fn parse_cmd_arg(&mut self) -> Option<CmdArg> {
        let tok = self.peek().clone();

        match tok.kind {
            TokenKind::CmdWord(parts) => {
                self.advance();
                let path = self.path.clone();
                let line = tok.line;
                let col = tok.col;
                let arg_parts: Vec<ArgPart> = parts.into_iter().map(|p| match p {
                    CmdPart::Lit(s) => ArgPart::Lit(s),
                    CmdPart::Var(name, vl, vc) => ArgPart::Var(name, Pos { file: path.clone(), line: vl, col: vc }),
                }).collect();
                Some(CmdArg::Parts(arg_parts))
            }
            TokenKind::Str(s) => {
                self.advance();
                Some(CmdArg::Parts(vec![ArgPart::Lit(s)]))
            }
            TokenKind::Ident(s) => {
                self.advance();
                Some(CmdArg::Parts(vec![ArgPart::Lit(s)]))
            }
            TokenKind::Int(n) => {
                self.advance();
                Some(CmdArg::Parts(vec![ArgPart::Lit(n.to_string())]))
            }
            TokenKind::Float(f) => {
                self.advance();
                Some(CmdArg::Parts(vec![ArgPart::Lit(format!("{}", f))]))
            }
            _ => None,
        }
    }

    fn parse_heredoc_arg(&mut self) -> String {
        let tok = self.peek().clone();
        match tok.kind {
            TokenKind::CmdWord(parts) => {
                self.advance();
                // Just collect the literal parts
                parts.into_iter().filter_map(|p| match p {
                    CmdPart::Lit(s) => Some(s),
                    _ => None,
                }).collect()
            }
            TokenKind::Str(s) => { self.advance(); s }
            TokenKind::Ident(s) => { self.advance(); s }
            _ => String::new(),
        }
    }
}

fn can_start_expr(k: &TokenKind) -> bool {
    matches!(k,
        TokenKind::Nil | TokenKind::True | TokenKind::False |
        TokenKind::Int(_) | TokenKind::Float(_) | TokenKind::Str(_) | TokenKind::Char(_) |
        TokenKind::Ident(_) | TokenKind::Minus | TokenKind::Not |
        TokenKind::LParen | TokenKind::LBracket | TokenKind::AtLBracket |
        TokenKind::Function | TokenKind::If | TokenKind::While | TokenKind::For |
        TokenKind::DollarLBrace | TokenKind::AmpersandLBrace | TokenKind::LBrace
    )
}

fn expr_to_target(e: Expr, pos: Pos) -> Option<AssignTarget> {
    match e {
        Expr::Ident(name, p) => Some(AssignTarget::Var(name, p)),
        Expr::Index(obj, key, p) => Some(AssignTarget::Index(obj, key, p)),
        Expr::Field(obj, field, p) => Some(AssignTarget::Field(obj, field, p)),
        _ => None,
    }
}

fn tok_display(k: &TokenKind) -> &'static str {
    match k {
        TokenKind::Nil => "nil",
        TokenKind::True => "true",
        TokenKind::False => "false",
        TokenKind::Int(_) => "int",
        TokenKind::Float(_) => "float",
        TokenKind::Str(_) => "string",
        TokenKind::Char(_) => "char",
        TokenKind::Ident(_) => "identifier",
        TokenKind::Let => "let",
        TokenKind::Function => "function",
        TokenKind::If => "if",
        TokenKind::Then => "then",
        TokenKind::Else => "else",
        TokenKind::ElseIf => "elseif",
        TokenKind::End => "end",
        TokenKind::While => "while",
        TokenKind::Do => "do",
        TokenKind::For => "for",
        TokenKind::In => "in",
        TokenKind::Return => "return",
        TokenKind::Break => "break",
        TokenKind::Plus => "+",
        TokenKind::Minus => "-",
        TokenKind::Star => "*",
        TokenKind::Slash => "/",
        TokenKind::Percent => "%",
        TokenKind::Eq => "==",
        TokenKind::NotEq => "!=",
        TokenKind::Lt => "<",
        TokenKind::LtEq => "<=",
        TokenKind::Gt => ">",
        TokenKind::GtEq => ">=",
        TokenKind::And => "and",
        TokenKind::Or => "or",
        TokenKind::Not => "not",
        TokenKind::Assign => "=",
        TokenKind::Concat => "++",
        TokenKind::LParen => "(",
        TokenKind::RParen => ")",
        TokenKind::LBracket => "[",
        TokenKind::RBracket => "]",
        TokenKind::AtLBracket => "@[",
        TokenKind::Comma => ",",
        TokenKind::Colon => ":",
        TokenKind::Dot => ".",
        TokenKind::LBrace => "{",
        TokenKind::RBrace => "}",
        TokenKind::DollarLBrace => "${",
        TokenKind::AmpersandLBrace => "&{",
        TokenKind::Semicolon => ";",
        TokenKind::Pipe => "|",
        TokenKind::Arrow => ">",
        TokenKind::Append => ">>",
        TokenKind::Stdin => "<<",
        TokenKind::Question => "?",
        TokenKind::CmdWord(_) => "word",
        TokenKind::Eof => "end of file",
    }
}
