// Semantic analysis for Hush
// Checks for undeclared variables and other static errors

use crate::ast::*;
use std::collections::HashSet;

// Analyze program, return errors
// Also returns scope information for --program display
pub fn analyze(prog: &Program, path: &str) -> (Vec<String>, ScopeInfo) {
    let mut analyzer = Analyzer::new(path);
    analyzer.analyze_program(prog);
    let scopes = analyzer.scope_info;
    (analyzer.errors, scopes)
