pub struct ScopeInfo {
    pub globals: Vec<String>,  // global variable names in order
}

struct Analyzer {
    path: String,
    errors: Vec<String>,
    scope_stack: Vec<HashSet<String>>,
    scope_names_stack: Vec<Vec<String>>,  // ordered list of vars in each scope
    scope_info: ScopeInfo,
}

impl Analyzer {
    fn new(path: &str) -> Self {
        let mut a = Analyzer {
            path: path.to_string(),
            errors: Vec::new(),
            scope_stack: vec![HashSet::new()],
            scope_names_stack: vec![Vec::new()],
            scope_info: ScopeInfo { globals: Vec::new() },
        };
        // std is always in scope
        a.declare("std");
        a
    }

    fn declare(&mut self, name: &str) {
        let scope = self.scope_stack.last_mut().unwrap();
        scope.insert(name.to_string());
        self.scope_names_stack.last_mut().unwrap().push(name.to_string());
    }

    fn is_declared(&self, name: &str) -> bool {
        for scope in self.scope_stack.iter().rev() {
            if scope.contains(name) {
                return true;
            }
        }
        false
    }

    fn is_declared_in_current(&self, name: &str) -> bool {
        self.scope_stack.last().unwrap().contains(name)
    }

    fn push_scope(&mut self) {
        self.scope_stack.push(HashSet::new());
        self.scope_names_stack.push(Vec::new());
    }

    fn pop_scope(&mut self) {
        self.scope_stack.pop();
        self.scope_names_stack.pop();
    }

    fn error(&mut self, pos: &Pos, msg: &str) {
        self.errors.push(format!("Error: {} - {}", pos.display(), msg));
    }

    fn analyze_program(&mut self, prog: &Program) {
        for stmt in &prog.stmts {
            self.analyze_stmt(stmt);
        }
        // Collect global names (excluding std)
        let globals: Vec<String> = self.scope_names_stack[0].iter()
            .filter(|n| n.as_str() != "std")
            .cloned()
            .collect();
        self.scope_info.globals = globals;
    }

    fn analyze_stmt(&mut self, stmt: &Stmt) {
        match stmt {
            Stmt::Let { name, value, pos } => {
                // Check for duplicate in same scope
                if self.is_declared_in_current(name) {
                    self.error(pos, &format!("duplicate variable '{}'", name));
                }
                // Analyze value before declaring (so name isn't in scope yet)
                if let Some(v) = value {
                    self.analyze_expr(v);
                }
                self.declare(name);
            }
            Stmt::Assign { target, value, .. } => {
                self.analyze_assign_target(target);
                self.analyze_expr(value);
            }
            Stmt::ExprStmt(e) => {
                self.analyze_expr(e);
            }
            Stmt::Return(v, _) => {
                if let Some(e) = v {
                    self.analyze_expr(e);
                }
            }
            Stmt::Break(_) => {}
            Stmt::CmdBlock(block) => {
                self.analyze_cmd_block(block);
            }
        }
    }

    fn analyze_assign_target(&mut self, target: &AssignTarget) {
        match target {
            AssignTarget::Var(name, pos) => {
                if !self.is_declared(name) {
                    self.error(pos, &format!("undeclared variable '{}'", name));
                }
            }
            AssignTarget::Index(obj, key, _) => {
                self.analyze_expr(obj);
                self.analyze_expr(key);
            }
            AssignTarget::Field(obj, _, _) => {
                self.analyze_expr(obj);
            }
        }
    }

    fn analyze_expr(&mut self, expr: &Expr) {
        match expr {
            Expr::Nil(_) | Expr::True(_) | Expr::False(_) | Expr::Int(_, _) 
            | Expr::Float(_, _) | Expr::Str(_, _) | Expr::Char(_, _) | Expr::Ill => {}

            Expr::Ident(name, pos) => {
                if !self.is_declared(name) {
                    self.error(pos, &format!("undeclared variable '{}'", name));
                }
            }

            Expr::UnaryNeg(e, _) | Expr::UnaryNot(e, _) => {
                self.analyze_expr(e);
            }

            Expr::Binary(l, _, r, _) => {
                self.analyze_expr(l);
                self.analyze_expr(r);
            }

            Expr::Array(items, _) => {
                for item in items {
                    self.analyze_expr(item);
                }
            }

            Expr::Dict(pairs, _) => {
                for (_, v) in pairs {
                    self.analyze_expr(v);
                }
            }

            Expr::Function { params, body, pos } => {
                self.push_scope();
                // 'self' is available in function scope
                self.declare("self");
                for param in params {
                    self.declare(param);
                }
                for stmt in body {
                    self.analyze_stmt(stmt);
                }
                self.pop_scope();
            }

            Expr::Call(callee, args, _) => {
                self.analyze_expr(callee);
                for arg in args {
                    self.analyze_expr(arg);
                }
            }

            Expr::MethodCall(obj, _, args, _) => {
                self.analyze_expr(obj);
                for arg in args {
                    self.analyze_expr(arg);
                }
            }

            Expr::Index(obj, key, _) => {
                self.analyze_expr(obj);
                self.analyze_expr(key);
            }

            Expr::Field(obj, _, _) => {
                self.analyze_expr(obj);
            }

            Expr::If { cond, then_body, else_body, .. } => {
                self.analyze_expr(cond);
                for stmt in then_body {
                    self.analyze_stmt(stmt);
                }
                if let Some(eb) = else_body {
                    for stmt in eb {
                        self.analyze_stmt(stmt);
                    }
                }
            }

            Expr::While(cond, body, _) => {
                self.analyze_expr(cond);
                for stmt in body {
                    self.analyze_stmt(stmt);
                }
            }

            Expr::For(var, iter, body, _) => {
                self.analyze_expr(iter);
                self.push_scope();
                self.declare(var);
                for stmt in body {
                    self.analyze_stmt(stmt);
                }
                self.pop_scope();
            }

            Expr::CmdCapture(block, _) | Expr::CmdAsync(block, _) => {
                self.analyze_cmd_block(block);
            }
        }
    }

    fn analyze_cmd_block(&mut self, block: &CmdBlock) {
        for cmd in &block.cmds {
            for part in &cmd.pipeline {
                self.analyze_cmd_args(&part.cmd);
                for redir in &part.redirects {
                    match redir {
                        Redirect::Out(_, target, _) => self.analyze_cmd_args(&[target.clone()]),
                        _ => {}
                    }
                }
            }
        }
    }

    fn analyze_cmd_args(&mut self, args: &[CmdArg]) {
        for arg in args {
            match arg {
                CmdArg::Parts(parts) => {
                    for part in parts {
                        match part {
                            ArgPart::Var(name, pos) => {
                                if !self.is_declared(name) {
                                    self.error(pos, &format!("undeclared variable '{}'", name));
                                }
                            }
                            ArgPart::Lit(_) => {}
                        }
                    }
                }
            }
        }
    }
}

