fn fmt_prog_expr(e: &Expr, slots: &std::collections::HashMap<String, usize>) -> String {
    match e {
        Expr::Nil(_) => "nil".to_string(),
        Expr::True(_) => "true".to_string(),
        Expr::False(_) => "false".to_string(),
