        Expr::UnaryNot(e, _) => format!("(not {})", fmt_prog_expr(e, slots)),
        Expr::Binary(l, op, r, _) => {
            let op_s = match op {
                BinOp::Add => "+", BinOp::Sub => "-", BinOp::Mul => "*",
                BinOp::Div => "/", BinOp::Mod => "%",
                BinOp::Eq => "==", BinOp::NotEq => "!=",
                BinOp::Lt => "<", BinOp::LtEq => "<=",
                BinOp::Gt => ">", BinOp::GtEq => ">=",
                BinOp::And => "and", BinOp::Or => "or",
