        }
        false
    }

    fn is_declared_in_current(&self, name: &str) -> bool {
        self.scope_stack.last().unwrap().contains(name)
    }

    fn push_scope(&mut self) {
        self.scope_stack.push(HashSet::new());
        self.scope_names_stack.push(Vec::new());
    }

    fn pop_scope(&mut self) {
        self.scope_stack.pop();
        self.scope_names_stack.pop();
    }

    fn error(&mut self, pos: &Pos, msg: &str) {
        self.errors.push(format!("Error: {} - {}", pos.display(), msg));
    }

    fn analyze_program(&mut self, prog: &Program) {
        for stmt in &prog.stmts {
            self.analyze_stmt(stmt);
        }
        // Collect global names (excluding std)
        let globals: Vec<String> = self.scope_names_stack[0].iter()
            .filter(|n| n.as_str() != "std")
            .cloned()
            .collect();
        self.scope_info.globals = globals;
    }

    fn analyze_stmt(&mut self, stmt: &Stmt) {
        match stmt {
            Stmt::Let { name, value, pos } => {
                // Check for duplicate in same scope
                if self.is_declared_in_current(name) {
                    self.error(pos, &format!("duplicate variable '{}'", name));
                }
                // Analyze value before declaring (so name isn't in scope yet)
                if let Some(v) = value {
                    self.analyze_expr(v);
                }
                self.declare(name);
            }
            Stmt::Assign { target, value, .. } => {
                self.analyze_assign_target(target);
                self.analyze_expr(value);
            }
            Stmt::ExprStmt(e) => {
                self.analyze_expr(e);
            }
            Stmt::Return(v, _) => {
                if let Some(e) = v {
                    self.analyze_expr(e);
                }
            }
            Stmt::Break(_) => {}
            Stmt::CmdBlock(block) => {
                self.analyze_cmd_block(block);
            }
        }
    }

    fn analyze_assign_target(&mut self, target: &AssignTarget) {
        match target {
            AssignTarget::Var(name, pos) => {
                if !self.is_declared(name) {
                    self.error(pos, &format!("undeclared variable '{}'", name));
                }
            }
            AssignTarget::Index(obj, key, _) => {
                self.analyze_expr(obj);
                self.analyze_expr(key);
            }
            AssignTarget::Field(obj, _, _) => {
                self.analyze_expr(obj);
            }
        }
    }

    fn analyze_expr(&mut self, expr: &Expr) {
        match expr {
            Expr::Nil(_) | Expr::True(_) | Expr::False(_) | Expr::Int(_, _) 
            | Expr::Float(_, _) | Expr::Str(_, _) | Expr::Char(_, _) | Expr::Ill => {}

            Expr::Ident(name, pos) => {
                if !self.is_declared(name) {
                    self.error(pos, &format!("undeclared variable '{}'", name));
                }
            }

            Expr::UnaryNeg(e, _) | Expr::UnaryNot(e, _) => {
                self.analyze_expr(e);
            }

            Expr::Binary(l, _, r, _) => {
                self.analyze_expr(l);
                self.analyze_expr(r);
            }

            Expr::Array(items, _) => {
                for item in items {
                    self.analyze_expr(item);
                }
            }

            Expr::Dict(pairs, _) => {
                for (_, v) in pairs {
                    self.analyze_expr(v);
                }
            }

            Expr::Function { params, body, pos } => {
                self.push_scope();
                // 'self' is available in function scope
                self.declare("self");
                for param in params {
                    self.declare(param);
                }
                for stmt in body {
                    self.analyze_stmt(stmt);
                }
                self.pop_scope();
            }

            Expr::Call(callee, args, _) => {
                self.analyze_expr(callee);
                for arg in args {
                    self.analyze_expr(arg);
                }
            }

            Expr::MethodCall(obj, _, args, _) => {
                self.analyze_expr(obj);
                for arg in args {
                    self.analyze_expr(arg);
                }
            }

            Expr::Index(obj, key, _) => {
                self.analyze_expr(obj);
                self.analyze_expr(key);
            }

            Expr::Field(obj, _, _) => {
                self.analyze_expr(obj);
            }

            Expr::If { cond, then_body, else_body, .. } => {
                self.analyze_expr(cond);
                for stmt in then_body {
                    self.analyze_stmt(stmt);
                }
                if let Some(eb) = else_body {
                    for stmt in eb {
                        self.analyze_stmt(stmt);
                    }
                }
            }

            Expr::While(cond, body, _) => {
                self.analyze_expr(cond);
                for stmt in body {
                    self.analyze_stmt(stmt);
                }
            }

            Expr::For(var, iter, body, _) => {
                self.analyze_expr(iter);
                self.push_scope();
                self.declare(var);
                for stmt in body {
                    self.analyze_stmt(stmt);
                }
                self.pop_scope();
            }

            Expr::CmdCapture(block, _) | Expr::CmdAsync(block, _) => {
                self.analyze_cmd_block(block);
            }
        }
    }

    fn analyze_cmd_block(&mut self, block: &CmdBlock) {
        for cmd in &block.cmds {
            for part in &cmd.pipeline {
                self.analyze_cmd_args(&part.cmd);
                for redir in &part.redirects {
                    match redir {
                        Redirect::Out(_, target, _) => self.analyze_cmd_args(&[target.clone()]),
                        _ => {}
                    }
                }
            }
        }
    }

    fn analyze_cmd_args(&mut self, args: &[CmdArg]) {
        for arg in args {
            match arg {
                CmdArg::Parts(parts) => {
                    for part in parts {
                        match part {
                            ArgPart::Var(name, pos) => {
                                if !self.is_declared(name) {
                                    self.error(pos, &format!("undeclared variable '{}'", name));
                                }
                            }
                            ArgPart::Lit(_) => {}
                        }
                    }
                }
            }
        }
    }
}

// Print program IR
pub fn print_program(prog: &Program, info: &ScopeInfo) {
    // Collect all variables (std + globals)
    let all_vars: Vec<&str> = std::iter::once("std")
        .chain(info.globals.iter().map(|s| s.as_str()))
        .collect();

    // Print all let declarations
    for (i, _) in all_vars.iter().enumerate() {
        println!("let #{}: auto", i);
    }

    // Create mapping from var name to slot number
    let mut var_slots: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
    for (i, name) in all_vars.iter().enumerate() {
        var_slots.insert(name.to_string(), i);
    }

    // Print program
    let ctx = ProgramContext { 
        var_slots: var_slots.clone(),
        next_slot: all_vars.len(),
    };

    for stmt in &prog.stmts {
        print_prog_stmt(stmt, 0, &var_slots);
    }
}

struct ProgramContext {
    var_slots: std::collections::HashMap<String, usize>,
    next_slot: usize,
}

fn get_slot(var_slots: &std::collections::HashMap<String, usize>, name: &str) -> String {
    if let Some(&n) = var_slots.get(name) {
        format!("#{}", n)
    } else {
        name.to_string()
    }
}

fn print_prog_stmt(stmt: &Stmt, indent: usize, slots: &std::collections::HashMap<String, usize>) {
    let ind = "\t".repeat(indent);
    match stmt {
        Stmt::Let { name, value, .. } => {
            let slot = get_slot(slots, name);
            if let Some(v) = value {
                println!("{}{} = {}", ind, slot, fmt_prog_expr(v, slots));
            }
        }
        Stmt::Assign { target, value, .. } => {
            let t = fmt_prog_target(target, slots);
            println!("{}{} = {}", ind, t, fmt_prog_expr(value, slots));
        }
        Stmt::ExprStmt(e) => {
            println!("{}{}", ind, fmt_prog_expr(e, slots));
        }
        Stmt::Return(v, _) => {
            if let Some(e) = v {
                println!("{}return {}", ind, fmt_prog_expr(e, slots));
            } else {
                println!("{}return", ind);
            }
        }
        Stmt::Break(_) => {
            println!("{}break", ind);
        }
        Stmt::CmdBlock(block) => {
            print_prog_cmd_block(block, indent, slots);
        }
    }
}

fn print_prog_cmd_block(block: &CmdBlock, indent: usize, slots: &std::collections::HashMap<String, usize>) {
    let ind = "\t".repeat(indent);
    let ind1 = "\t".repeat(indent + 1);
    println!("{}{{\n", ind);
    // ... 
}

fn fmt_prog_target(t: &AssignTarget, slots: &std::collections::HashMap<String, usize>) -> String {
    match t {
        AssignTarget::Var(name, _) => get_slot(slots, name),
        AssignTarget::Index(obj, key, _) => format!("{}[{}]", fmt_prog_expr(obj, slots), fmt_prog_expr(key, slots)),
        AssignTarget::Field(obj, f, _) => format!("{}.{}", fmt_prog_expr(obj, slots), f),
    }
}

fn fmt_prog_expr(e: &Expr, slots: &std::collections::HashMap<String, usize>) -> String {
    match e {
        Expr::Nil(_) => "nil".to_string(),
        Expr::True(_) => "true".to_string(),
        Expr::False(_) => "false".to_string(),
        Expr::Int(n, _) => n.to_string(),
        Expr::Float(f, _) => crate::ast::fmt_float(*f),
        Expr::Str(s, _) => format!("\"{}\"", crate::ast::escape_str_for_display(s)),
        Expr::Char(b, _) => format!("'{}'", *b as char),
        Expr::Ident(name, _) => get_slot(slots, name),
        Expr::UnaryNeg(e, _) => format!("(-{})", fmt_prog_expr(e, slots)),
        Expr::UnaryNot(e, _) => format!("(not {})", fmt_prog_expr(e, slots)),
        Expr::Binary(l, op, r, _) => {
            let op_s = match op {
                BinOp::Add => "+", BinOp::Sub => "-", BinOp::Mul => "*",
                BinOp::Div => "/", BinOp::Mod => "%",
                BinOp::Eq => "==", BinOp::NotEq => "!=",
                BinOp::Lt => "<", BinOp::LtEq => "<=",
                BinOp::Gt => ">", BinOp::GtEq => ">=",
                BinOp::And => "and", BinOp::Or => "or",
                BinOp::Concat => "++",
            };
            format!("({} {} {})", fmt_prog_expr(l, slots), op_s, fmt_prog_expr(r, slots))
        }
        Expr::Array(items, _) => {
            if items.is_empty() { return "[]".to_string(); }
            let parts: Vec<String> = items.iter().map(|i| fmt_prog_expr(i, slots)).collect();
            format!("[\n\t{}\n]", parts.join(",\n\t"))
        }
        Expr::Dict(pairs, _) => {
            let parts: Vec<String> = pairs.iter().map(|(k, v)| format!("{}: {}", k, fmt_prog_expr(v, slots))).collect();
            format!("@[ {} ]", parts.join(", "))
        }
        Expr::Function { params, body, .. } => {
            // Create function-local slots
            let mut fn_slots = std::collections::HashMap::new();
            fn_slots.insert("std".to_string(), 0usize);
            for (i, p) in params.iter().enumerate() {
                fn_slots.insert(p.clone(), i + 1);
            }
            // Collect let bindings
            let mut slot_n = params.len() + 1;
            let mut fn_decls: Vec<String> = Vec::new();
            collect_fn_slots(body, &mut fn_slots, &mut slot_n, &mut fn_decls);

            let mut s = format!("function({})\n", params.len());
            // Print let declarations
            for _ in 0..=params.len() + fn_decls.len() {
                s.push_str(&format!("\tlet #{}: auto\n", s.matches("let #").count()));
            }
            // Actually redo this properly
            s = format!("function({})\n", params.len());
            let total = slot_n;
            for i in 0..total {
                s.push_str(&format!("\tlet #{}: auto\n", i));
            }
            for stmt in body {
                let mut buf = String::new();
                fmt_prog_stmt_to_buf(stmt, 1, &fn_slots, &mut buf);
                s.push_str(&buf);
            }
            s.push_str("end");
            s
        }
        Expr::Call(callee, args, _) => {
            let args_s: Vec<String> = args.iter().map(|a| fmt_prog_expr(a, slots)).collect();
            format!("{}({})", fmt_prog_expr(callee, slots), args_s.join(", "))
        }
        Expr::MethodCall(obj, method, args, _) => {
            let args_s: Vec<String> = args.iter().map(|a| fmt_prog_expr(a, slots)).collect();
            format!("{}.{}({})", fmt_prog_expr(obj, slots), method, args_s.join(", "))
        }
        Expr::Index(obj, key, _) => format!("{}[{}]", fmt_prog_expr(obj, slots), fmt_prog_expr(key, slots)),
        Expr::Field(obj, field, _) => format!("{}.{}", fmt_prog_expr(obj, slots), field),
        Expr::If { cond, then_body, else_body, .. } => {
            let mut s = format!("if {} then\n", fmt_prog_expr(cond, slots));
            for stmt in then_body {
                let mut buf = String::new();
                fmt_prog_stmt_to_buf(stmt, 1, slots, &mut buf);
                s.push_str(&buf);
            }
            if let Some(eb) = else_body {
                s.push_str("else\n");
                for stmt in eb {
                    let mut buf = String::new();
                    fmt_prog_stmt_to_buf(stmt, 1, slots, &mut buf);
                    s.push_str(&buf);
                }
            }
            s.push_str("end");
            s
        }
        Expr::While(cond, body, _) => {
            let mut s = format!("while {} do\n", fmt_prog_expr(cond, slots));
            for stmt in body {
                let mut buf = String::new();
                fmt_prog_stmt_to_buf(stmt, 1, slots, &mut buf);
                s.push_str(&buf);
            }
            s.push_str("end");
            s
        }
        Expr::For(var, iter, body, _) => {
            let var_slot = get_slot(slots, var);
            let mut s = format!("for {} in {} do\n", var_slot, fmt_prog_expr(iter, slots));
            for stmt in body {
                let mut buf = String::new();
                fmt_prog_stmt_to_buf(stmt, 1, slots, &mut buf);
                s.push_str(&buf);
            }
            s.push_str("end");
            s
        }
        Expr::CmdCapture(block, _) => {
            fmt_prog_cmd_block_inline(block, slots, "$")
        }
        Expr::CmdAsync(block, _) => {
            fmt_prog_cmd_block_inline(block, slots, "&")
        }
        Expr::Ill => "***ill-formed***".to_string(),
    }
}

fn fmt_prog_cmd_block_inline(block: &CmdBlock, slots: &std::collections::HashMap<String, usize>, prefix: &str) -> String {
    let mut s = format!("${{\n");
    for (i, cmd) in block.cmds.iter().enumerate() {
        s.push_str("\t");
        s.push_str(&fmt_prog_cmd(cmd, slots));
        if i + 1 < block.cmds.len() {
            s.push(';');
        }
        s.push('\n');
    }
    s.push('}');
    s
}

fn fmt_prog_cmd(cmd: &CmdCmd, slots: &std::collections::HashMap<String, usize>) -> String {
    let mut parts: Vec<String> = Vec::new();
    for (i, part) in cmd.pipeline.iter().enumerate() {
        let is_last = i + 1 == cmd.pipeline.len();
        let mut s = fmt_prog_pipe_part(part, slots);
        if part.allow_fail && !is_last {
            s.push_str(" ?");
        }
        parts.push(s);
    }
    let mut r = parts.join(" | ");
    if cmd.allow_fail { r.push_str(" ?"); }
    r
}

fn fmt_prog_pipe_part(part: &CmdPipePart, slots: &std::collections::HashMap<String, usize>) -> String {
    let mut parts: Vec<String> = Vec::new();
    for arg in &part.cmd {
        parts.push(fmt_prog_arg(arg, slots));
    }
    for redir in &part.redirects {
        match redir {
            Redirect::Out(fd, target, append) => {
                let op = if *append { ">>" } else { ">" };
                if *fd == 1 {
                    parts.push(format!("{}{}", op, fmt_prog_arg(target, slots)));
                } else {
                    parts.push(format!("{}{}{}", fd, op, fmt_prog_arg(target, slots)));
                }
            }
            Redirect::Err2Out => parts.push("2>1".to_string()),
            Redirect::Out2Err => parts.push("1>2".to_string()),
            Redirect::Stdin(s) => parts.push(format!("<<\"{}\"", s)),
        }
    }
    parts.join(" ")
}

fn fmt_prog_arg(arg: &CmdArg, slots: &std::collections::HashMap<String, usize>) -> String {
    match arg {
        CmdArg::Parts(parts) => {
            let mut s = String::from("\"");
            for p in parts {
                match p {
                    ArgPart::Lit(l) => s.push_str(&crate::ast::escape_str_for_display(l)),
                    ArgPart::Var(name, _) => {
                        let slot = get_slot(slots, name);
                        s.push_str(&format!("${{{}}}", slot));
                    }
                }
            }
            s.push('"');
            s
        }
    }
}

fn fmt_prog_stmt_to_buf(stmt: &Stmt, indent: usize, slots: &std::collections::HashMap<String, usize>, buf: &mut String) {
    let ind = "\t".repeat(indent);
    match stmt {
        Stmt::Let { name, value, .. } => {
            let slot = get_slot(slots, name);
            if let Some(v) = value {
                buf.push_str(&format!("{}{} = {}\n", ind, slot, fmt_prog_expr(v, slots)));
            }
        }
        Stmt::Assign { target, value, .. } => {
            buf.push_str(&format!("{}{} = {}\n", ind, fmt_prog_target(target, slots), fmt_prog_expr(value, slots)));
        }
        Stmt::ExprStmt(e) => {
            buf.push_str(&format!("{}{}\n", ind, fmt_prog_expr(e, slots)));
        }
        Stmt::Return(v, _) => {
            if let Some(e) = v {
                buf.push_str(&format!("{}return {}\n", ind, fmt_prog_expr(e, slots)));
            } else {
                buf.push_str(&format!("{}return\n", ind));
            }
        }
        Stmt::Break(_) => buf.push_str(&format!("{}break\n", ind)),
        Stmt::CmdBlock(block) => {
            // TODO: handle cmd block in program display
        }
    }
}

fn collect_fn_slots(
    stmts: &[Stmt],
    slots: &mut std::collections::HashMap<String, usize>,
    next: &mut usize,
    decls: &mut Vec<String>,
) {
    for stmt in stmts {
        match stmt {
            Stmt::Let { name, value, .. } => {
                if !slots.contains_key(name.as_str()) {
                    slots.insert(name.clone(), *next);
                    decls.push(name.clone());
                    *next += 1;
                }
                if let Some(v) = value {
                    collect_expr_slots(v, slots, next, decls);
                }
            }
            Stmt::ExprStmt(e) => collect_expr_slots(e, slots, next, decls),
            Stmt::Assign { value, .. } => collect_expr_slots(value, slots, next, decls),
            Stmt::Return(Some(e), _) => collect_expr_slots(e, slots, next, decls),
            Stmt::For(var, iter, body, _) => {
                collect_expr_slots(iter, slots, next, decls);
                if !slots.contains_key(var.as_str()) {
                    slots.insert(var.clone(), *next);
                    decls.push(var.clone());
                    *next += 1;
                }
                collect_fn_slots(body, slots, next, decls);
            }
            Stmt::While(_, _, _) => {}
            _ => {}
        }
    }
}

fn collect_expr_slots(
    e: &Expr,
    slots: &mut std::collections::HashMap<String, usize>,
    next: &mut usize,
    decls: &mut Vec<String>,
) {
    // Only look at function bodies for inner let bindings
    match e {
        Expr::Function { body, .. } => {
            // Don't traverse into nested functions for slot collection
        }
        _ => {}
    }
}
