pub struct ScopeInfo {
    pub globals: Vec<String>,
}

struct Analyzer {
    path: String,
    errors: Vec<String>,
    scopes: Vec<ScopeData>,
    global_vars: Vec<String>,
}

struct ScopeData {
    vars: HashSet<String>,
    ordered: Vec<String>,
}

impl ScopeData {
    fn new() -> Self {
        ScopeData { vars: HashSet::new(), ordered: Vec::new() }
    }

    fn add(&mut self, name: &str) {
        self.vars.insert(name.to_string());
        self.ordered.push(name.to_string());
    }

    fn has(&self, name: &str) -> bool {
        self.vars.contains(name)
    }
}

impl Analyzer {
    fn new(path: &str) -> Self {
        let mut a = Analyzer {
            path: path.to_string(),
            errors: Vec::new(),
            scopes: vec![ScopeData::new()],
            global_vars: Vec::new(),
        };
        a.scopes[0].add("std");
        a
    }

    fn declare(&mut self, name: &str) {
        self.scopes.last_mut().unwrap().add(name);
    }

    fn is_declared(&self, name: &str) -> bool {
        for scope in self.scopes.iter().rev() {
            if scope.has(name) { return true; }
        }
        false
    }

    fn is_in_current(&self, name: &str) -> bool {
        self.scopes.last().unwrap().has(name)
    }

    fn push_scope(&mut self) {
        self.scopes.push(ScopeData::new());
    }

    fn pop_scope(&mut self) {
        self.scopes.pop();
    }

    fn err(&mut self, pos: &Pos, msg: &str) {
        self.errors.push(format!("Error: {} - {}", pos.display(), msg));
    }

    fn analyze_program(&mut self, prog: &Program) {
        for stmt in &prog.stmts {
            self.analyze_stmt(stmt);
        }
        self.global_vars = self.scopes[0].ordered.iter()
            .filter(|n| n.as_str() != "std")
            .cloned()
            .collect();
    }

    fn analyze_stmt(&mut self, stmt: &Stmt) {
        match stmt {
            Stmt::Let { name, value, pos } => {
                if self.is_in_current(name) {
                    self.err(pos, &format!("duplicate variable '{}'", name));
                }
                if let Some(v) = value {
                    self.analyze_expr(v);
                }
                self.declare(name);
            }
            Stmt::Assign { target, value, .. } => {
                self.check_target(target);
                self.analyze_expr(value);
            }
            Stmt::ExprStmt(e) => self.analyze_expr(e),
            Stmt::Return(v, _) => { if let Some(e) = v { self.analyze_expr(e); } }
            Stmt::Break(_) => {}
            Stmt::CmdBlock(block) => self.analyze_cmd_block(block),
        }
    }

    fn check_target(&mut self, target: &AssignTarget) {
        match target {
            AssignTarget::Var(name, pos) => {
                if !self.is_declared(name) {
                    self.err(pos, &format!("undeclared variable '{}'", name));
                }
            }
            AssignTarget::Index(obj, key, _) => { self.analyze_expr(obj); self.analyze_expr(key); }
            AssignTarget::Field(obj, _, _) => self.analyze_expr(obj),
        }
    }

    fn analyze_expr(&mut self, e: &Expr) {
        match e {
            Expr::Nil(_) | Expr::True(_) | Expr::False(_) | Expr::Int(_, _) 
            | Expr::Float(_, _) | Expr::Str(_, _) | Expr::Char(_, _) | Expr::Ill => {}

            Expr::Ident(name, pos) => {
                if !self.is_declared(name) {
                    self.err(pos, &format!("undeclared variable '{}'", name));
                }
            }

            Expr::UnaryNeg(e, _) | Expr::UnaryNot(e, _) => self.analyze_expr(e),
            Expr::Binary(l, _, r, _) => { self.analyze_expr(l); self.analyze_expr(r); }

            Expr::Array(items, _) => { for i in items { self.analyze_expr(i); } }
            Expr::Dict(pairs, _) => { for (_, v) in pairs { self.analyze_expr(v); } }

            Expr::Function { params, body, .. } => {
                self.push_scope();
                self.declare("self");
                for p in params { self.declare(p); }
                for s in body { self.analyze_stmt(s); }
                self.pop_scope();
            }

            Expr::Call(callee, args, _) => {
                self.analyze_expr(callee);
                for a in args { self.analyze_expr(a); }
            }
            Expr::MethodCall(obj, _, args, _) => {
                self.analyze_expr(obj);
                for a in args { self.analyze_expr(a); }
            }
            Expr::Index(obj, key, _) => { self.analyze_expr(obj); self.analyze_expr(key); }
            Expr::Field(obj, _, _) => self.analyze_expr(obj),

            Expr::If { cond, then_body, else_body, .. } => {
                self.analyze_expr(cond);
                for s in then_body { self.analyze_stmt(s); }
                if let Some(eb) = else_body {
                    for s in eb { self.analyze_stmt(s); }
                }
            }
            Expr::While(cond, body, _) => {
                self.analyze_expr(cond);
                for s in body { self.analyze_stmt(s); }
            }
            Expr::For(var, iter, body, _) => {
                self.analyze_expr(iter);
                self.push_scope();
                self.declare(var);
                for s in body { self.analyze_stmt(s); }
                self.pop_scope();
            }

            Expr::CmdCapture(block, _) | Expr::CmdAsync(block, _) => {
                self.analyze_cmd_block(block);
            }
        }
    }

    fn analyze_cmd_block(&mut self, block: &CmdBlock) {
        for cmd in &block.cmds {
            for part in &cmd.pipeline {
                self.check_cmd_args(&part.cmd);
                for redir in &part.redirects {
                    match redir {
                        Redirect::Out(_, t, _) => self.check_cmd_args(&[t.clone()]),
                        _ => {}
                    }
                }
            }
        }
    }

    fn check_cmd_args(&mut self, args: &[CmdArg]) {
        for arg in args {
            match arg {
                CmdArg::Parts(parts) => {
                    for p in parts {
                        if let ArgPart::Var(name, pos) = p {
                            if !self.is_declared(name) {
                                self.err(pos, &format!("undeclared variable '{}'", name));
                            }
                        }
                    }
                }
            }
        }
    }
}

// Program IR printing

pub fn print_program(prog: &Program, info: &ScopeInfo) {
    // Build global slot mapping: std=0, then globals in order
    let mut slots: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
    slots.insert("std".to_string(), 0);

    // Count all let variables in global scope (in order of declaration)
    // We need to collect them by traversing the program first
    let mut global_names: Vec<String> = vec!["std".to_string()];
    collect_global_vars(&prog.stmts, &mut global_names);

    let n = global_names.len();
    for (i, name) in global_names.iter().enumerate() {
        slots.insert(name.clone(), i);
        println!("let #{}: auto", i);
    }

    for stmt in &prog.stmts {
        print_prog_stmt_at(stmt, 0, &slots);
    }
}

fn collect_global_vars(stmts: &[Stmt], names: &mut Vec<String>) {
    for stmt in stmts {
        match stmt {
            Stmt::Let { name, .. } => {
                if !names.contains(name) {
                    names.push(name.clone());
                }
            }
            _ => {}
        }
    }
}

fn get_slot(slots: &std::collections::HashMap<String, usize>, name: &str) -> String {
    if let Some(&n) = slots.get(name) {
        format!("#{}", n)
    } else {
        name.to_string()
    }
}

fn print_prog_stmt_at(stmt: &Stmt, indent: usize, slots: &std::collections::HashMap<String, usize>) {
    let ind = "\t".repeat(indent);
    match stmt {
        Stmt::Let { name, value, .. } => {
            if let Some(v) = value {
                let slot = get_slot(slots, name);
                println!("{}{} = {}", ind, slot, fmt_prog_expr(v, slots));
            }
        }
        Stmt::Assign { target, value, .. } => {
            println!("{}{} = {}", ind, fmt_prog_target(target, slots), fmt_prog_expr(value, slots));
        }
        Stmt::ExprStmt(e) => {
            println!("{}{}", ind, fmt_prog_expr(e, slots));
        }
        Stmt::Return(v, _) => {
            if let Some(e) = v {
                println!("{}return {}", ind, fmt_prog_expr(e, slots));
            } else {
                println!("{}return", ind);
            }
        }
        Stmt::Break(_) => println!("{}break", ind),
        Stmt::CmdBlock(block) => {
            print_prog_cmd_block_stmt(block, indent, slots);
        }
    }
}

fn print_prog_cmd_block_stmt(block: &CmdBlock, indent: usize, slots: &std::collections::HashMap<String, usize>) {
    let ind = "\t".repeat(indent);
    let ind1 = "\t".repeat(indent + 1);
    println!("{}{{", ind);
    for (i, cmd) in block.cmds.iter().enumerate() {
        let s = fmt_prog_cmd(cmd, slots);
        if i + 1 < block.cmds.len() {
            println!("{}{};", ind1, s);
        } else {
            println!("{}{}", ind1, s);
        }
    }
    println!("{}}}", ind);
}

fn fmt_prog_target(t: &AssignTarget, slots: &std::collections::HashMap<String, usize>) -> String {
    match t {
        AssignTarget::Var(name, _) => get_slot(slots, name),
        AssignTarget::Index(obj, key, _) => format!("{}[{}]", fmt_prog_expr(obj, slots), fmt_prog_expr(key, slots)),
        AssignTarget::Field(obj, f, _) => format!("{}.{}", fmt_prog_expr(obj, slots), f),
    }
}

pub fn fmt_prog_expr(e: &Expr, slots: &std::collections::HashMap<String, usize>) -> String {
    match e {
        Expr::Nil(_) => "nil".to_string(),
        Expr::True(_) => "true".to_string(),
        Expr::False(_) => "false".to_string(),
        Expr::Int(n, _) => n.to_string(),
        Expr::Float(f, _) => crate::ast::fmt_float(*f),
        Expr::Str(s, _) => format!("\"{}\"", crate::ast::escape_str_for_display(s)),
        Expr::Char(b, _) => format!("'{}'", *b as char),
        Expr::Ident(name, _) => get_slot(slots, name),

        Expr::UnaryNeg(e, _) => format!("(-{})", fmt_prog_expr(e, slots)),
        Expr::UnaryNot(e, _) => format!("(not {})", fmt_prog_expr(e, slots)),

        Expr::Binary(l, op, r, _) => {
            let op_s = match op {
                BinOp::Add => "+", BinOp::Sub => "-", BinOp::Mul => "*",
                BinOp::Div => "/", BinOp::Mod => "%",
                BinOp::Eq => "==", BinOp::NotEq => "!=",
                BinOp::Lt => "<", BinOp::LtEq => "<=",
                BinOp::Gt => ">", BinOp::GtEq => ">=",
                BinOp::And => "and", BinOp::Or => "or",
                BinOp::Concat => "++",
            };
            format!("({} {} {})", fmt_prog_expr(l, slots), op_s, fmt_prog_expr(r, slots))
        }

        Expr::Array(items, _) => {
            if items.is_empty() { return "[\n]".to_string(); }
            let parts: Vec<String> = items.iter().map(|i| format!("\t{}", fmt_prog_expr(i, slots))).collect();
            format!("[\n{}\n]", parts.join(",\n"))
        }

        Expr::Dict(pairs, _) => {
            let parts: Vec<String> = pairs.iter().map(|(k, v)| format!("{}: {}", k, fmt_prog_expr(v, slots))).collect();
            format!("@[ {} ]", parts.join(", "))
        }

        Expr::Function { params, body, .. } => {
            // Build function-local slots
            let mut fn_slots = std::collections::HashMap::new();
            fn_slots.insert("std".to_string(), 0usize);
            fn_slots.insert("self".to_string(), 0usize); // self aliases std slot? No... let's skip self
            let mut next = 1usize;
            for p in params {
                fn_slots.insert(p.clone(), next);
                next += 1;
            }
            // Collect local let bindings
            let mut local_names: Vec<String> = Vec::new();
            collect_local_lets(body, &mut local_names, &fn_slots);
            for name in &local_names {
                fn_slots.insert(name.clone(), next);
                next += 1;
            }

            // Count for loop vars
            count_for_vars(body, &mut fn_slots, &mut next);

            let total = next;
            let mut s = format!("function({})\n", params.len());
            for i in 0..total {
                s.push_str(&format!("\tlet #{}: auto\n", i));
            }
            for stmt in body {
                let mut buf = String::new();
                prog_stmt_to_buf(stmt, 1, &fn_slots, &mut buf);
                s.push_str(&buf);
            }
            s.push_str("end");
            s
        }

        Expr::Call(callee, args, _) => {
            let args_s: Vec<String> = args.iter().map(|a| fmt_prog_expr(a, slots)).collect();
            format!("{}({})", fmt_prog_expr(callee, slots), args_s.join(", "))
        }
        Expr::MethodCall(obj, method, args, _) => {
            let args_s: Vec<String> = args.iter().map(|a| fmt_prog_expr(a, slots)).collect();
            format!("{}.{}({})", fmt_prog_expr(obj, slots), method, args_s.join(", "))
        }
        Expr::Index(obj, key, _) => format!("{}[{}]", fmt_prog_expr(obj, slots), fmt_prog_expr(key, slots)),
        Expr::Field(obj, field, _) => format!("{}.{}", fmt_prog_expr(obj, slots), field),

        Expr::If { cond, then_body, else_body, .. } => {
            let mut s = format!("if {} then\n", fmt_prog_expr(cond, slots));
            for stmt in then_body {
                let mut buf = String::new();
                prog_stmt_to_buf(stmt, 1, slots, &mut buf);
                s.push_str(&buf);
            }
            if let Some(eb) = else_body {
                s.push_str("else\n");
                for stmt in eb {
                    let mut buf = String::new();
                    prog_stmt_to_buf(stmt, 1, slots, &mut buf);
                    s.push_str(&buf);
                }
            }
            s.push_str("end");
            s
        }

        Expr::While(cond, body, _) => {
            let mut s = format!("while {} do\n", fmt_prog_expr(cond, slots));
            for stmt in body {
                let mut buf = String::new();
                prog_stmt_to_buf(stmt, 1, slots, &mut buf);
                s.push_str(&buf);
            }
            s.push_str("end");
            s
        }

        Expr::For(var, iter, body, _) => {
            let var_slot = get_slot(slots, var);
            let mut s = format!("for {} in {} do\n", var_slot, fmt_prog_expr(iter, slots));
            for stmt in body {
                let mut buf = String::new();
                prog_stmt_to_buf(stmt, 1, slots, &mut buf);
                s.push_str(&buf);
            }
            s.push_str("end");
            s
        }

        Expr::CmdCapture(block, _) => fmt_prog_cmd_block_expr(block, slots, true),
        Expr::CmdAsync(block, _) => fmt_prog_cmd_block_expr(block, slots, false),

        Expr::Ill => "***ill-formed***".to_string(),
    }
}

fn fmt_prog_cmd_block_expr(block: &CmdBlock, slots: &std::collections::HashMap<String, usize>, capture: bool) -> String {
    let prefix = if capture { "$" } else { "&" };
    let mut s = format!("${{\n");
    for (i, cmd) in block.cmds.iter().enumerate() {
        s.push_str("\t");
        s.push_str(&fmt_prog_cmd(cmd, slots));
        if i + 1 < block.cmds.len() {
            s.push(';');
        }
        s.push('\n');
    }
    s.push('}');
    s
}

fn fmt_prog_cmd(cmd: &CmdCmd, slots: &std::collections::HashMap<String, usize>) -> String {
    let mut parts: Vec<String> = Vec::new();
    for (i, part) in cmd.pipeline.iter().enumerate() {
        let is_last = i + 1 == cmd.pipeline.len();
        let mut s = fmt_prog_pipe_part(part, slots);
        if part.allow_fail && !is_last { s.push_str(" ?"); }
        parts.push(s);
    }
    let mut r = parts.join(" | ");
    if cmd.allow_fail { r.push_str(" ?"); }
    r
}

fn fmt_prog_pipe_part(part: &CmdPipePart, slots: &std::collections::HashMap<String, usize>) -> String {
    let mut parts: Vec<String> = Vec::new();
    for arg in &part.cmd {
        parts.push(fmt_prog_arg(arg, slots));
    }
    for redir in &part.redirects {
        match redir {
            Redirect::Out(fd, t, append) => {
                let op = if *append { ">>" } else { ">" };
                if *fd == 1 { parts.push(format!("{}{}", op, fmt_prog_arg(t, slots))); }
                else { parts.push(format!("{}{}{}", fd, op, fmt_prog_arg(t, slots))); }
            }
            Redirect::Err2Out => parts.push("2>1".to_string()),
            Redirect::Out2Err => parts.push("1>2".to_string()),
            Redirect::Stdin(s) => parts.push(format!("<<\"{}\"", s)),
        }
    }
    parts.join(" ")
}

fn fmt_prog_arg(arg: &CmdArg, slots: &std::collections::HashMap<String, usize>) -> String {
    match arg {
        CmdArg::Parts(parts) => {
            let mut s = String::from("\"");
            for p in parts {
                match p {
                    ArgPart::Lit(l) => s.push_str(&crate::ast::escape_str_for_display(l)),
                    ArgPart::Var(name, _) => {
                        s.push_str(&format!("${{{}}}", get_slot(slots, name)));
                    }
                }
            }
            s.push('"');
            s
        }
    }
}

fn prog_stmt_to_buf(stmt: &Stmt, indent: usize, slots: &std::collections::HashMap<String, usize>, buf: &mut String) {
    let ind = "\t".repeat(indent);
    match stmt {
        Stmt::Let { name, value, .. } => {
            if let Some(v) = value {
                let slot = get_slot(slots, name);
                buf.push_str(&format!("{}{} = {}\n", ind, slot, fmt_prog_expr(v, slots)));
            }
        }
        Stmt::Assign { target, value, .. } => {
            buf.push_str(&format!("{}{} = {}\n", ind, fmt_prog_target(target, slots), fmt_prog_expr(value, slots)));
        }
        Stmt::ExprStmt(e) => {
            buf.push_str(&format!("{}{}\n", ind, fmt_prog_expr(e, slots)));
        }
        Stmt::Return(v, _) => {
            if let Some(e) = v {
                buf.push_str(&format!("{}return {}\n", ind, fmt_prog_expr(e, slots)));
            } else {
                buf.push_str(&format!("{}return\n", ind));
            }
        }
        Stmt::Break(_) => buf.push_str(&format!("{}break\n", ind)),
        Stmt::CmdBlock(block) => {
            let ind1 = "\t".repeat(indent + 1);
            buf.push_str(&format!("{}{{\n", ind));
            for (i, cmd) in block.cmds.iter().enumerate() {
                let s = fmt_prog_cmd(cmd, slots);
                if i + 1 < block.cmds.len() {
                    buf.push_str(&format!("{}{};", ind1, s));
                } else {
                    buf.push_str(&format!("{}{}", ind1, s));
                }
                buf.push('\n');
            }
            buf.push_str(&format!("{}}}\n", ind));
        }
    }
}

fn collect_local_lets(stmts: &[Stmt], names: &mut Vec<String>, existing: &std::collections::HashMap<String, usize>) {
    for stmt in stmts {
        match stmt {
            Stmt::Let { name, value, .. } => {
                if !existing.contains_key(name.as_str()) && !names.contains(name) {
                    names.push(name.clone());
                }
                if let Some(v) = value {
                    collect_let_in_expr(v, names, existing);
                }
            }
            Stmt::ExprStmt(e) => collect_let_in_expr(e, names, existing),
            Stmt::Return(Some(e), _) => collect_let_in_expr(e, names, existing),
            Stmt::Assign { value, .. } => collect_let_in_expr(value, names, existing),
            _ => {}
        }
    }
}

fn collect_let_in_expr(e: &Expr, names: &mut Vec<String>, existing: &std::collections::HashMap<String, usize>) {
    match e {
        Expr::If { then_body, else_body, .. } => {
            collect_local_lets(then_body, names, existing);
            if let Some(eb) = else_body {
                collect_local_lets(eb, names, existing);
            }
        }
        Expr::While(_, body, _) => collect_local_lets(body, names, existing),
        Expr::For(var, _, body, _) => {
            if !existing.contains_key(var.as_str()) && !names.contains(var) {
                names.push(var.clone());
            }
            collect_local_lets(body, names, existing);
        }
        _ => {}
    }
}

fn count_for_vars(stmts: &[Stmt], slots: &mut std::collections::HashMap<String, usize>, next: &mut usize) {
    // Already handled in collect_local_lets for basic case
    // But we need to handle for vars that aren't let bindings
    for stmt in stmts {
        match stmt {
            Stmt::ExprStmt(Expr::For(var, _, body, _)) => {
                if !slots.contains_key(var.as_str()) {
                    slots.insert(var.clone(), *next);
                    *next += 1;
                }
                count_for_vars(body, slots, next);
            }
            _ => {}
        }
    }
}
