        // Same as tokenize but also records inline errors for display
        let mut cmd_depth: usize = 0;

        loop {
            self.skip_whitespace_comments();

            if self.peek().is_none() {
                tokens.push(Token {
                    kind: TokenKind::Eof,
                    line: self.line,
                    col: self.col,
                    display: String::new(),
                });
                break;
            }

            let line = self.line;
            let col = self.col;
            let mut local_errors: Vec<String> = Vec::new();

            if cmd_depth > 0 {
                match self.peek() {
