                        tokens.push(tok);
                    }
                    Some(b';') => {
                        self.advance();
                        let tok = Token { kind: TokenKind::Semicolon, line, col, display: ";".into() };
                        events.push(LexItem::Token(tok.clone()));
                        tokens.push(tok);
                    }
                    Some(b'|') => {
                        self.advance();
                        let tok = Token { kind: TokenKind::Pipe, line, col, display: "|".into() };
                        events.push(LexItem::Token(tok.clone()));
                        tokens.push(tok);
                    }
                    Some(b'>') => {
                        self.advance();
                        let kind;
                        let display;
                        if self.peek() == Some(b'>') {
                            self.advance();
                            kind = TokenKind::Append;
                            display = ">>".to_string();
                        } else {
                            kind = TokenKind::Arrow;
                            display = ">".to_string();
                        }
                        let tok = Token { kind, line, col, display };
                        events.push(LexItem::Token(tok.clone()));
                        tokens.push(tok);
                    }
                    Some(b'<') if self.peek_at(1) == Some(b'<') => {
                        self.advance(); self.advance();
                        let tok = Token { kind: TokenKind::Stdin, line, col, display: "<<".into() };
                        events.push(LexItem::Token(tok.clone()));
                        tokens.push(tok);
                        while matches!(self.peek(), Some(b' ') | Some(b'\\t')) { self.advance(); }
                        let (heredoc_str, raw) = self.lex_heredoc_content(&mut local_errors);
                        let hline = self.line;
                        let hcol = self.col.saturating_sub(raw.len());
                        for err in &local_errors {
                            all_errors.push(err.clone());
                            let inline = err.replace(&self.path, "")
                                .replace(" (line ", " line ")
                                .replace(", column ", ", column ")
                                .trim_start()
                                .to_string();
                            events.push(LexItem::Error(inline));
                        }
                        local_errors.clear();
                        let tok2 = Token { kind: TokenKind::CmdWord(vec![CmdPart::Lit(heredoc_str)]), line: hline, col: hcol, display: raw };
                        events.push(LexItem::Token(tok2.clone()));
                        tokens.push(tok2);
                    }
                    Some(b'?') => {
                        self.advance();
                        let tok = Token { kind: TokenKind::Question, line, col, display: "?".into() };
                        events.push(LexItem::Token(tok.clone()));
                        tokens.push(tok);
                    }
                    Some(b'#') => {
                        while self.peek().map_or(false, |c| c != b'\\n') { self.advance(); }
                    }
                    Some(c) if c.is_ascii_digit() => {
                        let mut num_s = String::new();
                        while let Some(d) = self.peek() {
                            if d.is_ascii_digit() { num_s.push(d as char); self.advance(); }
                            else { break; }
                        }
                        if matches!(self.peek(), Some(b'>')) {
                            let n: i64 = num_s.parse().unwrap_or(0);
                            let tok = Token { kind: TokenKind::Int(n), line, col, display: num_s };
                            events.push(LexItem::Token(tok.clone()));
                            tokens.push(tok);
                        } else {
                            let (more_parts, more_raw) = self.lex_cmd_word_continue(&mut local_errors);
                            let display = format!("{}{}", num_s, more_raw);
                            let mut parts = vec![CmdPart::Lit(num_s)];
                            parts.extend(more_parts);
                            let parts = merge_lits(parts);
                            let tok = Token { kind: TokenKind::CmdWord(parts), line, col, display };
                            for err in &local_errors {
                                all_errors.push(err.clone());
                                let inline_err = to_inline_error(err);
                                events.push(LexItem::Error(inline_err));
                            }
                            local_errors.clear();
                            events.push(LexItem::Token(tok.clone()));
                            tokens.push(tok);
                        }
                    }
                    _ => {
                        if let Some((parts, display)) = self.lex_cmd_word(&mut local_errors) {
                            for err in &local_errors {
                                all_errors.push(err.clone());
                                let inline_err = to_inline_error(err);
                                events.push(LexItem::Error(inline_err));
                            }
                            local_errors.clear();
                            let tok = Token { kind: TokenKind::CmdWord(parts), line, col, display };
                            events.push(LexItem::Token(tok.clone()));
                            tokens.push(tok);
                        }
                    }
                }
            } else {
                match self.peek() {
                    Some(b'{') => {
                        self.advance();
                        cmd_depth += 1;
                        let tok = Token { kind: TokenKind::LBrace, line, col, display: "{".into() };
                        events.push(LexItem::Token(tok.clone()));
                        tokens.push(tok);
                    }
                    Some(b'$') if self.peek_at(1) == Some(b'{') => {
                        self.advance(); self.advance();
                        cmd_depth += 1;
                        let tok = Token { kind: TokenKind::DollarLBrace, line, col, display: "${".into() };
                        events.push(LexItem::Token(tok.clone()));
                        tokens.push(tok);
                    }
                    Some(b'&') if self.peek_at(1) == Some(b'{') => {
                        self.advance(); self.advance();
                        cmd_depth += 1;
                        let tok = Token { kind: TokenKind::AmpersandLBrace, line, col, display: "&{".into() };
                        events.push(LexItem::Token(tok.clone()));
                        tokens.push(tok);
                    }
                    Some(c) => {
                        if let Some((kind, display)) = self.lex_normal_token(c, &mut local_errors) {
                            for err in &local_errors {
                                all_errors.push(err.clone());
                                let inline_err = to_inline_error(err);
                                events.push(LexItem::Error(inline_err));
                            }
                            local_errors.clear();
                            let tok = Token { kind, line, col, display };
                            events.push(LexItem::Token(tok.clone()));
                            tokens.push(tok);
                        } else {
                            for err in &local_errors {
                                all_errors.push(err.clone());
                                let inline_err = to_inline_error(err);
                                events.push(LexItem::Error(inline_err));
                            }
                            local_errors.clear();
                        }
                    }
                    None => break,
                }
            }
        }
    }

    '''

