fn to_inline_error(err: &str) -> String {
    // Convert "Error: path (line X, column Y) - msg"
    // to "Error: line X, column Y - msg"
    // Pattern: "Error: path (line X, column Y) - msg"
    if let Some(start) = err.find(" (line ") {
        let rest = &err[start + 1..]; // "(line X..."
        format!("Error: {}", rest.replacen("(", "", 1).replacen(")", "", 1).trim().to_string())
    } else {
        err.to_string()
    }
}
