# - fmt_float_ast: for AST/program display (no .0 for whole numbers)
# - fmt_float_runtime: for std.print/std.println

# Looking at the original behavior:
# AST display: 890000000000 (no .0)
# Runtime print: 890000000000.0 (with .0)

# And for 1.5:
# AST display: 1.5
# Runtime: 1.5

# So: in AST display, floats with no fractional part display as integers
# In runtime display, floats ALWAYS show .0 (or the decimal)

# Let me create a separate function for AST display:
python3 << 'PYEOF'
with open('/workspace/hush/src/ast.rs', 'r') as f:
    content = f.read()

old = '''pub fn fmt_float(f: f64) -> String {
    if f.is_nan() { return "NaN".to_string(); }
    if f.is_infinite() {
        return if f > 0.0 { "inf".to_string() } else { "-inf".to_string() };
    }
    // Use Rust\'s default float formatting
    let s = format!("{}", f);
    // If no decimal point and no \'e\', add .0
    if !s.contains(\'.\') && !s.contains(\'e\') && !s.contains(\'n\') && !s.contains(\'i\') {
        format!("{}.0", s)
    } else {
        s
    }
}'''

new = '''pub fn fmt_float(f: f64) -> String {
    // For AST display: whole-number floats show as integers
    if f.is_nan() { return "NaN".to_string(); }
    if f.is_infinite() {
        return if f > 0.0 { "inf".to_string() } else { "-inf".to_string() };
    }
    let s = format!("{}", f);
    s  // Use Rust\'s default (no extra .0)
}

pub fn fmt_float_runtime(f: f64) -> String {
    // For runtime display: always show as float with .0 if no fractional part
    if f.is_nan() { return "NaN".to_string(); }
    if f.is_infinite() {
        return if f > 0.0 { "inf".to_string() } else { "-inf".to_string() };
    }
    let s = format!("{}", f);
    if !s.contains(\'.\') && !s.contains(\'e\') && !s.contains(\'n\') && !s.contains(\'i\') {
        format!("{}.0", s)
    } else {
        s
    }
}'''

if old in content:
    content = content.replace(old, new)
    print("Fixed!")
else:
    print("Not found")

with open('/workspace/hush/src/ast.rs', 'w') as f:
