// Hush interpreter
#![allow(dead_code, unused_variables)]

use crate::ast::*;
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::io::{self, Write, Read};
use std::os::unix::io::{RawFd, FromRawFd, IntoRawFd};

pub fn execute(prog: &Program, path: &str, args: Vec<String>) -> i32 {
    let mut vm = Vm::new(path);
    vm.global_env.borrow_mut().set_var("std", Value::Std);

    // Set up script args
    let args_arr: Vec<Value> = args.iter().map(|s| Value::Str(s.clone())).collect();
    vm.script_args = args_arr;

    // Execute global statements
    match vm.exec_stmts(&prog.stmts) {
        Ok(_) => 0,
        Err(HushError::Exit(code)) => code,
        Err(HushError::Panic(msg)) => {
            eprintln!("{}", msg);
            127
        }
        Err(e) => {
            eprintln!("Error: {:?}", e);
            1
        }
    }
}

// ===== Values =====

#[derive(Clone, Debug)]
pub enum Value {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Char(u8),
    Array(Arc<Mutex<Vec<Value>>>),
    Dict(Arc<Mutex<DictData>>),
    Function(Arc<FuncData>),
    Std,
    Error(Arc<ErrorData>),
    AsyncJob(Arc<Mutex<AsyncJobData>>),
    Regex(Arc<RegexData>),
}

#[derive(Debug)]
pub struct DictData {
    pub map: HashMap<String, Value>,
    pub order: Vec<String>,
}

impl DictData {
    fn new() -> Self {
        DictData { map: HashMap::new(), order: Vec::new() }
    }

    fn get(&self, key: &str) -> Option<&Value> {
        self.map.get(key)
    }

    fn set(&mut self, key: String, val: Value) {
        if !self.map.contains_key(&key) {
            self.order.push(key.clone());
        }
        self.map.insert(key, val);
    }

    fn len(&self) -> usize {
        self.map.len()
    }
}

#[derive(Debug)]
pub struct FuncData {
    pub params: Vec<String>,
    pub body: Vec<Stmt>,
    pub captures: Vec<(String, Arc<Mutex<Value>>)>,  // closed-over variables
    pub pos: Pos,
}

#[derive(Debug, Clone)]
pub struct ErrorData {
    pub message: String,
    pub context: Value,
}

#[derive(Debug)]
pub struct AsyncJobData {
    pub thread: Option<std::thread::JoinHandle<()>>,
    pub done: bool,
}

#[derive(Debug)]
pub struct RegexData {
    pub pattern: String,
    // We'll implement regex manually
}

impl PartialEq for Value {
    fn eq(&self, other: &Value) -> bool {
        match (self, other) {
            (Value::Nil, Value::Nil) => true,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a == b,
            (Value::Str(a), Value::Str(b)) => a == b,
            (Value::Char(a), Value::Char(b)) => a == b,
            (Value::Array(a), Value::Array(b)) => Arc::ptr_eq(a, b),
            (Value::Dict(a), Value::Dict(b)) => Arc::ptr_eq(a, b),
            (Value::Function(a), Value::Function(b)) => Arc::ptr_eq(a, b),
            (Value::Std, Value::Std) => true,
            (Value::Error(a), Value::Error(b)) => Arc::ptr_eq(a, b),
            _ => false,
        }
    }
}

impl Value {
    fn type_name(&self) -> &'static str {
        match self {
            Value::Nil => "nil",
            Value::Bool(_) => "bool",
            Value::Int(_) => "int",
            Value::Float(_) => "float",
            Value::Str(_) => "string",
            Value::Char(_) => "char",
            Value::Array(_) => "array",
            Value::Dict(_) => "dict",
            Value::Function(_) => "function",
            Value::Std => "dict",
            Value::Error(_) => "error",
            Value::AsyncJob(_) => "dict",
            Value::Regex(_) => "dict",
        }
    }

    fn is_error(&self) -> bool {
        matches!(self, Value::Error(_))
    }

    fn display(&self) -> String {
        self.display_impl(false, 0)
    }

    fn display_impl(&self, in_collection: bool, depth: usize) -> String {
        match self {
            Value::Nil => "nil".to_string(),
            Value::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
            Value::Int(n) => n.to_string(),
            Value::Float(f) => crate::ast::fmt_float_runtime(*f),
            Value::Str(s) => {
                if in_collection {
                    format!("\"{}\"", escape_display(s))
                } else {
                    s.clone()
                }
            }
            Value::Char(b) => {
                (*b as char).to_string()
            }
            Value::Array(arr) => {
                let arr = arr.lock().unwrap();
                if arr.is_empty() {
                    return "[]".to_string();
                }
                let parts: Vec<String> = arr.iter().map(|v| v.display_impl(true, depth+1)).collect();
                format!("[ {} ]", parts.join(", "))
            }
            Value::Dict(dict) => {
                let dict = dict.lock().unwrap();
                if dict.map.is_empty() {
                    return "@[]".to_string();
                }
                let parts: Vec<String> = dict.order.iter()
                    .filter_map(|k| dict.map.get(k).map(|v| format!("\"{}\":{} {}", k, "", v.display_impl(true, depth+1))))
                    .collect();
                // Actually: "@[ \"key\": value, ... ]"
                let parts: Vec<String> = dict.order.iter()
                    .filter_map(|k| dict.map.get(k).map(|v| format!("\"{}\":{}{}", k, " ", v.display_impl(true, depth+1))))
                    .collect();
                format!("@[ {} ]", parts.join(", "))
            }
            Value::Function(f) => {
                format!("function{}>", f.pos.display())
                    .replace("function", "function<")
            }
            Value::Std => "std".to_string(),
            Value::Error(e) => {
                format!("error: \"{}\" ({})", escape_display(&e.message), e.context.display_impl(true, depth+1))
            }
            Value::AsyncJob(_) => {
                "@[ \"join\": <command>.join ]".to_string()
            }
            Value::Regex(r) => {
                format!("@[ regex: \"{}\" ]", r.pattern)
            }
        }
    }

    fn to_string_value(&self) -> String {
        self.display()
    }
}

fn escape_display(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '\n' => result.push_str("\\n"),
            '\t' => result.push_str("\\t"),
            '\0' => result.push_str("\\0"),
            '\\' => result.push_str("\\\\"),
            '"' => result.push_str("\\\""),
            '\'' => result.push_str("\\'"),
            c => result.push(c),
        }
    }
    result
}

// ===== Errors =====

#[derive(Debug)]
pub enum HushError {
    Panic(String),
    Exit(i32),
    Return(Value),
    Break,
    PropagateError(Value),  // Error value propagation
}

type HushResult<T> = Result<T, HushError>;

// ===== Environment =====

#[derive(Debug)]
pub struct Env {
    vars: HashMap<String, Arc<Mutex<Value>>>,
    parent: Option<Arc<Mutex<Env>>>,
}

impl Env {
    fn new() -> Self {
        Env { vars: HashMap::new(), parent: None }
    }

    fn with_parent(parent: Arc<Mutex<Env>>) -> Self {
        Env { vars: HashMap::new(), parent: Some(parent) }
    }

    fn define(&mut self, name: &str, val: Value) {
        let cell = Arc::new(Mutex::new(val));
        self.vars.insert(name.to_string(), cell);
    }

    fn set_var(&mut self, name: &str, val: Value) {
        if let Some(cell) = self.vars.get(name) {
            *cell.lock().unwrap() = val;
        } else if let Some(parent) = &self.parent {
            parent.lock().unwrap().set_var(name, val);
        }
    }

    fn get_var(&self, name: &str) -> Option<Value> {
        if let Some(cell) = self.vars.get(name) {
            return Some(cell.lock().unwrap().clone());
        }
        if let Some(parent) = &self.parent {
            return parent.lock().unwrap().get_var(name);
        }
        None
    }

    fn get_cell(&self, name: &str) -> Option<Arc<Mutex<Value>>> {
        if let Some(cell) = self.vars.get(name) {
            return Some(cell.clone());
        }
        if let Some(parent) = &self.parent {
            return parent.lock().unwrap().get_cell(name);
        }
        None
    }

    fn set_existing(&mut self, name: &str, val: Value) -> bool {
        if let Some(cell) = self.vars.get(name) {
            *cell.lock().unwrap() = val;
            return true;
        }
        if let Some(parent) = &self.parent {
            return parent.lock().unwrap().set_existing(name, val);
        }
        false
    }
}

// ===== VM =====

pub struct Vm {
    pub global_env: Arc<Mutex<Env>>,
    pub script_args: Vec<Value>,
    path: String,
    call_depth: usize,
}

impl Vm {
    fn new(path: &str) -> Self {
        let env = Arc::new(Mutex::new(Env::new()));
        Vm {
            global_env: env,
            script_args: Vec::new(),
            path: path.to_string(),
            call_depth: 0,
        }
    }

    fn panic(&self, pos: &Pos, msg: &str) -> HushError {
        HushError::Panic(format!("Panic in {}: {}", pos.display(), msg))
    }

    fn exec_stmts(&mut self) -> HushResult<Value> {
        Ok(Value::Nil)
    }
}

