            return Some(cell.lock().unwrap().clone());
        }
        if let Some(parent) = &self.parent {
            return parent.lock().unwrap().get_var(name);
        }
        None
    }

    fn get_cell(&self, name: &str) -> Option<Arc<Mutex<Value>>> {
        if let Some(cell) = self.vars.get(name) {
            return Some(cell.clone());
        }
        if let Some(parent) = &self.parent {
            return parent.lock().unwrap().get_cell(name);
        }
        None
    }

    fn set_existing(&mut self, name: &str, val: Value) -> bool {
        if let Some(cell) = self.vars.get(name) {
            *cell.lock().unwrap() = val;
            return true;
        }
        if let Some(parent) = &self.parent {
            return parent.lock().unwrap().set_existing(name, val);
        }
        false
    }
}

