// ---------- Values ----------

#[derive(Clone, Debug)]
pub enum Value {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Char(u8),
    Array(Arc<Mutex<Vec<Value>>>),
    Dict(Arc<Mutex<Dict>>),
    Function(Arc<Func>),
    Error(Arc<ErrorVal>),
    // For async jobs
    AsyncJob(Arc<Mutex<AsyncJob>>),
}

#[derive(Debug)]
pub struct Dict {
    pub map: HashMap<String, Value>,
    pub keys: Vec<String>,
}

impl Dict {
    pub fn new() -> Self { Dict { map: HashMap::new(), keys: Vec::new() } }
    pub fn get(&self, k: &str) -> Option<&Value> { self.map.get(k) }
    pub fn set(&mut self, k: String, v: Value) {
        if !self.map.contains_key(&k) { self.keys.push(k.clone()); }
        self.map.insert(k, v);
    }
    pub fn len(&self) -> usize { self.map.len() }
}

#[derive(Debug)]
pub struct Func {
    pub params: Vec<String>,
    pub body: Vec<Stmt>,
    pub env: Arc<Mutex<Env>>,
    pub pos: Pos,
}

#[derive(Debug, Clone)]
pub struct ErrorVal {
    pub msg: String,
    pub ctx: Value,
}

#[derive(Debug)]
pub struct AsyncJob {
    pub handle: Option<std::thread::JoinHandle<()>>,
    pub stdout_buf: Arc<Mutex<String>>,
    pub stderr_buf: Arc<Mutex<String>>,
    pub done: bool,
}

impl PartialEq for Value {
    fn eq(&self, other: &Value) -> bool {
        match (self, other) {
            (Value::Nil, Value::Nil) => true,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a.to_bits() == b.to_bits(),
            (Value::Str(a), Value::Str(b)) => a == b,
            (Value::Char(a), Value::Char(b)) => a == b,
            (Value::Array(a), Value::Array(b)) => Arc::ptr_eq(a, b),
            (Value::Dict(a), Value::Dict(b)) => Arc::ptr_eq(a, b),
            (Value::Function(a), Value::Function(b)) => Arc::ptr_eq(a, b),
            (Value::Error(a), Value::Error(b)) => Arc::ptr_eq(a, b),
            _ => false,
        }
    }
}

impl Value {
    pub fn type_name(&self) -> &\'static str {
        match self {
            Value::Nil => "nil",
            Value::Bool(_) => "bool",
            Value::Int(_) => "int",
            Value::Float(_) => "float",
            Value::Str(_) => "string",
            Value::Char(_) => "char",
            Value::Array(_) => "array",
            Value::Dict(_) | Value::AsyncJob(_) => "dict",
            Value::Function(_) => "function",
            Value::Error(_) => "error",
        }
    }

    pub fn is_error(&self) -> bool { matches!(self, Value::Error(_)) }

    pub fn display(&self) -> String { self.fmt_val(false) }

    pub fn fmt_val(&self, in_coll: bool) -> String {
        match self {
            Value::Nil => "nil".to_string(),
            Value::Bool(b) => if *b { "true" } else { "false" }.to_string(),
            Value::Int(n) => n.to_string(),
            Value::Float(f) => fmt_float_runtime(*f),
            Value::Str(s) => if in_coll { format!("\\"{}\\"", escape_str(s)) } else { s.clone() },
            Value::Char(b) => (*b as char).to_string(),
            Value::Array(arr) => {
                let arr = arr.lock().unwrap();
                if arr.is_empty() { return "[]".to_string(); }
                let parts: Vec<String> = arr.iter().map(|v| v.fmt_val(true)).collect();
                format!("[ {} ]", parts.join(", "))
            }
            Value::Dict(d) => {
                let d = d.lock().unwrap();
                if d.map.is_empty() { return "@[]".to_string(); }
                let parts: Vec<String> = d.keys.iter()
                    .filter_map(|k| d.map.get(k).map(|v| format!("\\"{}\\":{} {}", k, "", v.fmt_val(true))))
                    .collect();
                // Format: @[ "key": value, ... ]
                let parts: Vec<String> = d.keys.iter()
                    .filter_map(|k| d.map.get(k).map(|v| format!("\\"{}\\":{}{}", k, " ", v.fmt_val(true))))
                    .collect();
                format!("@[ {} ]", parts.join(", "))
            }
            Value::Function(f) => {
                format!("function{}>", f.pos.display()).replace("function", "function<")
            }
            Value::Error(e) => {
                format!("error: \\"{}\\" ({})", escape_str(&e.msg), e.ctx.fmt_val(true))
            }
            Value::AsyncJob(j) => {
                "@[ \\"join\\": <command>.join ]".to_string()
            }
        }
    }
}

fn fmt_float_runtime(f: f64) -> String {
    if f.is_nan() { return "NaN".to_string(); }
    if f.is_infinite() { return if f > 0.0 { "inf" } else { "-inf" }.to_string(); }
    let s = format!("{}", f);
    if !s.contains(\'.\') && !s.contains(\'e\') { format!("{}.0", s) } else { s }
}

fn escape_str(s: &str) -> String {
    let mut r = String::new();
    for c in s.chars() {
        match c {
            \'\\n\' => r.push_str("\\\\n"),
            \'\\t\' => r.push_str("\\\\t"),
            \'\\0\' => r.push_str("\\\\0"),
            \'\\\\\' => r.push_str("\\\\\\\\"),
            \'"\' => r.push_str("\\\\\\""),
            c => r.push(c),
        }
    }
    r
}

// ---------- Errors ----------

#[derive(Debug)]
pub enum HushError {
    Panic(String),
    Exit(i32),
    Return(Value),
    Break,
}

type Res<T> = Result<T, HushError>;

// ---------- Environment ----------

#[derive(Debug)]
pub struct Env {
    vars: HashMap<String, Arc<Mutex<Value>>>,
    parent: Option<Arc<Mutex<Env>>>,
}

impl Env {
    pub fn new() -> Self { Env { vars: HashMap::new(), parent: None } }

    pub fn child(parent: Arc<Mutex<Env>>) -> Self {
        Env { vars: HashMap::new(), parent: Some(parent) }
    }

    pub fn define(&mut self, name: &str, val: Value) {
        self.vars.insert(name.to_string(), Arc::new(Mutex::new(val)));
    }

    pub fn get(&self, name: &str) -> Option<Value> {
        if let Some(c) = self.vars.get(name) { return Some(c.lock().unwrap().clone()); }
        if let Some(p) = &self.parent { return p.lock().unwrap().get(name); }
        None
    }

    pub fn get_cell(&self, name: &str) -> Option<Arc<Mutex<Value>>> {
        if let Some(c) = self.vars.get(name) { return Some(c.clone()); }
        if let Some(p) = &self.parent { return p.lock().unwrap().get_cell(name); }
        None
    }

    pub fn set(&mut self, name: &str, val: Value) -> bool {
        if let Some(c) = self.vars.get(name) { *c.lock().unwrap() = val; return true; }
        if let Some(p) = &self.parent { return p.lock().unwrap().set(name, val); }
        false
    }

    pub fn set_local(&mut self, name: &str, val: Value) {
        if let Some(c) = self.vars.get(name) {
            *c.lock().unwrap() = val;
        }
    }
}

// ---------- VM ----------

pub struct Vm {
    pub env: Arc<Mutex<Env>>,
    pub script_args: Vec<Value>,
    path: String,
}

impl Vm {
    pub fn new(path: &str, args: Vec<String>) -> Self {
        let env = Arc::new(Mutex::new(Env::new()));
        // std is defined in the environment
        let mut vm = Vm { env: env.clone(), script_args: args.iter().map(|s| Value::Str(s.clone())).collect(), path: path.to_string() };
        // Define std
        env.lock().unwrap().define("std", make_std_dict(&vm.path, &vm.script_args));
        vm
    }

    pub fn run(&mut self, stmts: &[Stmt]) -> Res<Value> {
        self.exec_stmts(stmts, self.env.clone())
    }

    fn exec_stmts(&mut self, stmts: &[Stmt], env: Arc<Mutex<Env>>) -> Res<Value> {
        let mut last = Value::Nil;
        for stmt in stmts {
            last = self.exec_stmt(stmt, env.clone())?;
        }
        Ok(last)
    }

    fn exec_stmt(&mut self, stmt: &Stmt, env: Arc<Mutex<Env>>) -> Res<Value> {
        match stmt {
            Stmt::Let { name, value, .. } => {
                let val = if let Some(expr) = value {
                    self.eval_expr(expr, env.clone())?
                } else {
                    Value::Nil
                };
                env.lock().unwrap().define(name, val);
                Ok(Value::Nil)
            }
            Stmt::Assign { target, value, pos } => {
                let val = self.eval_expr(value, env.clone())?;
                self.do_assign(target, val, env, pos)?;
                Ok(Value::Nil)
            }
            Stmt::ExprStmt(expr) => {
                self.eval_expr(expr, env)
            }
            Stmt::Return(val, _) => {
                let v = if let Some(e) = val {
                    self.eval_expr(e, env)?
                } else {
                    Value::Nil
                };
                Err(HushError::Return(v))
            }
            Stmt::Break(_) => Err(HushError::Break),
            Stmt::CmdBlock(block) => {
                self.exec_cmd_block(block, env, None, None)
            }
        }
    }

    fn do_assign(&mut self, target: &AssignTarget, val: Value, env: Arc<Mutex<Env>>, pos: &Pos) -> Res<()> {
        match target {
            AssignTarget::Var(name, p) => {
                if !env.lock().unwrap().set(name, val) {
                    return Err(HushError::Panic(format!("Panic in {}: undeclared variable \'{}\'", p.display(), name)));
                }
                Ok(())
            }
            AssignTarget::Index(obj_expr, key_expr, p) => {
                let obj = self.eval_expr(obj_expr, env.clone())?;
                let key = self.eval_expr(key_expr, env.clone())?;
                match &obj {
                    Value::Array(arr) => {
                        let idx = match &key {
                            Value::Int(n) => *n as usize,
                            _ => return Err(HushError::Panic(format!("Panic in {}: array index must be integer", p.display()))),
                        };
                        let mut arr = arr.lock().unwrap();
                        if idx >= arr.len() {
                            return Err(HushError::Panic(format!("Panic in {}: index ({}) out of bounds", p.display(), idx)));
                        }
                        arr[idx] = val;
                    }
                    Value::Dict(d) => {
                        let k = match &key {
                            Value::Str(s) => s.clone(),
                            Value::Int(n) => n.to_string(),
                            _ => return Err(HushError::Panic(format!("Panic in {}: dict key must be string", p.display()))),
                        };
                        d.lock().unwrap().set(k, val);
                    }
                    _ => return Err(HushError::Panic(format!("Panic in {}: cannot index into {}", p.display(), obj.type_name()))),
                }
                Ok(())
            }
            AssignTarget::Field(obj_expr, field, p) => {
                let obj = self.eval_expr(obj_expr, env.clone())?;
                match &obj {
                    Value::Dict(d) => {
                        d.lock().unwrap().set(field.clone(), val);
                    }
                    _ => return Err(HushError::Panic(format!("Panic in {}: cannot set field on {}", p.display(), obj.type_name()))),
                }
                Ok(())
            }
        }
    }

    fn eval_expr(&mut self, expr: &Expr, env: Arc<Mutex<Env>>) -> Res<Value> {
        match expr {
            Expr::Nil(_) => Ok(Value::Nil),
            Expr::True(_) => Ok(Value::Bool(true)),
            Expr::False(_) => Ok(Value::Bool(false)),
            Expr::Int(n, _) => Ok(Value::Int(*n)),
            Expr::Float(f, _) => Ok(Value::Float(*f)),
            Expr::Str(s, _) => Ok(Value::Str(s.clone())),
            Expr::Char(b, _) => Ok(Value::Char(*b)),
            Expr::Ident(name, pos) => {
                match env.lock().unwrap().get(name) {
                    Some(v) => Ok(v),
                    None => Err(HushError::Panic(format!("Panic in {}: undeclared variable \'{}\'", pos.display(), name))),
                }
            }
            Expr::UnaryNeg(e, pos) => {
                let v = self.eval_expr(e, env)?;
                match v {
                    Value::Int(n) => Ok(Value::Int(-n)),
                    Value::Float(f) => Ok(Value::Float(-f)),
                    _ => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected int or float", pos.display(), v.display()))),
                }
            }
            Expr::UnaryNot(e, pos) => {
                let v = self.eval_expr(e, env)?;
                match v {
                    Value::Bool(b) => Ok(Value::Bool(!b)),
                    _ => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected bool", pos.display(), v.display()))),
                }
            }
            Expr::Binary(l, op, r, pos) => self.eval_binary(l, *op, r, pos, env),
            Expr::Array(items, _) => {
                let mut arr = Vec::new();
                for item in items {
                    arr.push(self.eval_expr(item, env.clone())?);
                }
                Ok(Value::Array(Arc::new(Mutex::new(arr))))
            }
            Expr::Dict(pairs, _) => {
                let mut d = Dict::new();
                for (k, v) in pairs {
                    let val = self.eval_expr(v, env.clone())?;
                    d.set(k.clone(), val);
                }
                Ok(Value::Dict(Arc::new(Mutex::new(d))))
            }
            Expr::Function { params, body, pos } => {
                Ok(Value::Function(Arc::new(Func {
                    params: params.clone(),
                    body: body.clone(),
                    env: env.clone(),
                    pos: pos.clone(),
                })))
            }
            Expr::Call(callee, args, pos) => {
                let func = self.eval_expr(callee, env.clone())?;
                let mut arg_vals = Vec::new();
                for a in args {
                    arg_vals.push(self.eval_expr(a, env.clone())?);
                }
                self.call_func(func, arg_vals, pos, None)
            }
            Expr::MethodCall(obj_expr, method, args, pos) => {
                let obj = self.eval_expr(obj_expr, env.clone())?;
                let mut arg_vals = Vec::new();
                for a in args {
                    arg_vals.push(self.eval_expr(a, env.clone())?);
                }
                self.call_method(obj, method, arg_vals, pos)
            }
            Expr::Index(obj_expr, key_expr, pos) => {
                let obj = self.eval_expr(obj_expr, env.clone())?;
                let key = self.eval_expr(key_expr, env)?;
                self.do_index(obj, key, pos)
            }
            Expr::Field(obj_expr, field, pos) => {
                let obj = self.eval_expr(obj_expr, env)?;
                self.do_field(obj, field, pos)
            }
            Expr::If { cond, then_body, else_body, pos } => {
                let c = self.eval_expr(cond, env.clone())?;
                match c {
                    Value::Bool(true) => {
                        match self.exec_stmts(then_body, Arc::new(Mutex::new(Env::child(env)))) {
                            Ok(v) | Err(HushError::Return(v)) if !matches!(Err::<Value, _>(HushError::Return(v.clone())), Err(HushError::Return(_))) => Ok(v),
                            other => other,
                        }
                    }
                    _ => { /* handled below */ Value::Nil; Ok(Value::Nil) }
                }
                .and_then(|_| Ok(Value::Nil)) // placeholder, need to rewrite
                // Actually just do it inline:
                ;
                let c2 = self.eval_expr(cond, env.clone())?;
                let result = match c2 {
                    Value::Bool(true) => {
                        self.exec_stmts_return(then_body, Arc::new(Mutex::new(Env::child(env.clone()))))?
                    }
                    Value::Bool(false) => {
                        if let Some(eb) = else_body {
                            self.exec_stmts_return(eb, Arc::new(Mutex::new(Env::child(env.clone()))))?
                        } else {
                            Value::Nil
                        }
                    }
                    _ => return Err(HushError::Panic(format!("Panic in {}: condition ({}) is not a boolean", pos.display(), c2.display()))),
                };
                Ok(result)
            }
            Expr::While(cond, body, _) => {
                loop {
                    let c = self.eval_expr(cond, env.clone())?;
                    match c {
                        Value::Bool(true) => {}
                        Value::Bool(false) => break,
                        _ => return Err(HushError::Panic(format!("condition ({}) is not a boolean", c.display()))),
                    }
                    let child = Arc::new(Mutex::new(Env::child(env.clone())));
                    match self.exec_stmts(body, child) {
                        Ok(_) => {}
                        Err(HushError::Break) => break,
                        Err(e) => return Err(e),
                    }
                }
                Ok(Value::Nil)
            }
            Expr::For(var, iter_expr, body, pos) => {
                let iter_fn = self.eval_expr(iter_expr, env.clone())?;
                match iter_fn {
                    Value::Function(_) => {}
                    _ => return Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected function", pos.display(), iter_fn.display()))),
                }
                loop {
                    let result = self.call_func(iter_fn.clone(), vec![], pos, None)?;
                    // result should be @[finished: bool, value: V]
                    let finished = match &result {
                        Value::Dict(d) => {
                            let d = d.lock().unwrap();
                            match d.get("finished") {
                                Some(Value::Bool(b)) => *b,
                                _ => false,
                            }
                        }
                        _ => return Err(HushError::Panic(format!("Panic in {}: iterator returned non-dict", pos.display()))),
                    };
                    if finished { break; }
                    let val = match &result {
                        Value::Dict(d) => d.lock().unwrap().get("value").cloned().unwrap_or(Value::Nil),
                        _ => Value::Nil,
                    };
                    let child = Arc::new(Mutex::new(Env::child(env.clone())));
                    child.lock().unwrap().define(var, val);
                    match self.exec_stmts(body, child) {
                        Ok(_) => {}
                        Err(HushError::Break) => break,
                        Err(e) => return Err(e),
                    }
                }
                Ok(Value::Nil)
            }
            Expr::CmdCapture(block, pos) => {
                self.exec_cmd_block(block, env, Some(pos), None)
            }
            Expr::CmdAsync(block, pos) => {
                self.exec_async_cmd(block, env, pos)
            }
            Expr::Ill => Err(HushError::Panic("ill-formed expression".to_string())),
        }
    }

    fn exec_stmts_return(&mut self, stmts: &[Stmt], env: Arc<Mutex<Env>>) -> Res<Value> {
        let mut last = Value::Nil;
        for stmt in stmts {
            match self.exec_stmt(stmt, env.clone()) {
                Ok(v) => last = v,
                Err(HushError::Return(v)) => return Ok(v),
                Err(e) => return Err(e),
            }
        }
        Ok(last)
    }

    fn eval_binary(&mut self, l: &Expr, op: BinOp, r: &Expr, pos: &Pos, env: Arc<Mutex<Env>>) -> Res<Value> {
        // Short-circuit for and/or
        if op == BinOp::And {
            let lv = self.eval_expr(l, env.clone())?;
            match lv {
                Value::Bool(false) => return Ok(Value::Bool(false)),
                Value::Bool(true) => return self.eval_expr(r, env),
                _ => return Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected bool", pos.display(), lv.display()))),
            }
        }
        if op == BinOp::Or {
            let lv = self.eval_expr(l, env.clone())?;
            match lv {
                Value::Bool(true) => return Ok(Value::Bool(true)),
                Value::Bool(false) => return self.eval_expr(r, env),
                _ => return Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected bool", pos.display(), lv.display()))),
            }
        }

        let lv = self.eval_expr(l, env.clone())?;
        let rv = self.eval_expr(r, env)?;

        match op {
            BinOp::Add => match (&lv, &rv) {
                (Value::Int(a), Value::Int(b)) => Ok(Value::Int(a + b)),
                (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a + b)),
                _ => {
                    let want = if matches!(lv, Value::Int(_)) { "int" } else { "float" };
                    Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected int or float", pos.display(), rv.display())))
                }
            },
            BinOp::Sub => match (&lv, &rv) {
                (Value::Int(a), Value::Int(b)) => Ok(Value::Int(a - b)),
                (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a - b)),
                _ => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected int or float", pos.display(), rv.display()))),
            },
            BinOp::Mul => match (&lv, &rv) {
                (Value::Int(a), Value::Int(b)) => Ok(Value::Int(a * b)),
                (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a * b)),
                _ => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected int or float", pos.display(), rv.display()))),
            },
            BinOp::Div => match (&lv, &rv) {
                (Value::Int(a), Value::Int(b)) => {
                    if *b == 0 { return Err(HushError::Panic(format!("Panic in {}: division by zero", pos.display()))); }
                    Ok(Value::Int(a / b))
                },
                (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a / b)),
                _ => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected int or float", pos.display(), rv.display()))),
            },
            BinOp::Mod => match (&lv, &rv) {
                (Value::Int(a), Value::Int(b)) => {
                    if *b == 0 { return Err(HushError::Panic(format!("Panic in {}: division by zero", pos.display()))); }
                    Ok(Value::Int(a % b))
                },
                (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a % b)),
                _ => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected int or float", pos.display(), rv.display()))),
            },
            BinOp::Eq => Ok(Value::Bool(lv == rv)),
            BinOp::NotEq => Ok(Value::Bool(lv != rv)),
            BinOp::Lt => self.cmp_op(&lv, &rv, pos, false, false),
            BinOp::LtEq => self.cmp_op(&lv, &rv, pos, false, true),
            BinOp::Gt => self.cmp_op(&rv, &lv, pos, false, false),  // gt = lt(rv, lv)
            BinOp::GtEq => self.cmp_op(&rv, &lv, pos, false, true), // gte = lte(rv, lv)  
            BinOp::And | BinOp::Or => unreachable!(),
            BinOp::Concat => match (&lv, &rv) {
                (Value::Str(a), Value::Str(b)) => Ok(Value::Str(format!("{}{}", a, b))),
                _ => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected string", pos.display(), lv.display()))),
            },
        }
    }

    fn cmp_op(&self, l: &Value, r: &Value, pos: &Pos, _gt: bool, eq: bool) -> Res<Value> {
        match (l, r) {
            (Value::Int(a), Value::Int(b)) => Ok(Value::Bool(if eq { a <= b } else { a < b })),
            (Value::Float(a), Value::Float(b)) => Ok(Value::Bool(if eq { a <= b } else { a < b })),
            (Value::Str(a), Value::Str(b)) => Ok(Value::Bool(if eq { a <= b } else { a < b })),
            (Value::Char(a), Value::Char(b)) => Ok(Value::Bool(if eq { a <= b } else { a < b })),
            (Value::Int(_), _) => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected int", pos.display(), r.display()))),
            (Value::Float(_), _) => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected float", pos.display(), r.display()))),
            (Value::Str(_), _) => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected string", pos.display(), r.display()))),
            _ => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected int, float, byte or string", pos.display(), l.display()))),
        }
    }

    fn do_index(&self, obj: Value, key: Value, pos: &Pos) -> Res<Value> {
        match &obj {
            Value::Array(arr) => {
                let idx = match &key {
                    Value::Int(n) => *n as usize,
                    _ => return Err(HushError::Panic(format!("Panic in {}: array index must be integer", pos.display()))),
                };
                let arr = arr.lock().unwrap();
                match arr.get(idx) {
                    Some(v) => Ok(v.clone()),
                    None => Err(HushError::Panic(format!("Panic in {}: index ({}) out of bounds", pos.display(), idx))),
                }
            }
            Value::Dict(d) => {
                let k = match &key {
                    Value::Str(s) => s.clone(),
                    Value::Int(n) => n.to_string(),
                    _ => return Err(HushError::Panic(format!("Panic in {}: dict key must be string", pos.display()))),
                };
                let d = d.lock().unwrap();
                match d.get(&k) {
                    Some(v) => Ok(v.clone()),
                    None => Err(HushError::Panic(format!("Panic in {}: index ({:?}) out of bounds", pos.display(), k))),
                }
            }
            Value::Error(e) => {
                Err(HushError::Panic(format!("Panic in {}: index ({:?}) out of bounds", pos.display(), key.display())))
            }
            _ => Err(HushError::Panic(format!("Panic in {}: cannot index into {}", pos.display(), obj.type_name()))),
        }
    }

    fn do_field(&self, obj: Value, field: &str, pos: &Pos) -> Res<Value> {
        match &obj {
            Value::Dict(d) => {
                let d = d.lock().unwrap();
                match d.get(field) {
                    Some(v) => Ok(v.clone()),
                    None => Err(HushError::Panic(format!("Panic in {}: index ({:?}) out of bounds", pos.display(), field))),
                }
            }
            Value::Error(_) => {
                Err(HushError::Panic(format!("Panic in {}: index ({:?}) out of bounds", pos.display(), field)))
            }
            _ => Err(HushError::Panic(format!("Panic in {}: cannot access field on {}", pos.display(), obj.type_name()))),
        }
    }

    pub fn call_func(&mut self, func: Value, args: Vec<Value>, pos: &Pos, self_val: Option<Value>) -> Res<Value> {
        match func {
            Value::Function(f) => {
                if f.params.len() != args.len() {
                    return Err(HushError::Panic(format!("Panic in {}: incorrect amount of function parameters -- supplied {}, expected {}", pos.display(), args.len(), f.params.len())));
                }
                let child = Arc::new(Mutex::new(Env::child(f.env.clone())));
                {
                    let mut c = child.lock().unwrap();
                    c.define("self", self_val.unwrap_or(Value::Nil));
                    for (p, v) in f.params.iter().zip(args) {
                        c.define(p, v);
                    }
                }
                match self.exec_stmts(&f.body, child) {
                    Ok(v) => Ok(v),
                    Err(HushError::Return(v)) => Ok(v),
                    Err(e) => Err(e),
                }
            }
            Value::Dict(ref d) if is_std_dict(&func) => {
                // std call
                Err(HushError::Panic(format!("Panic in {}: attempt to call std", pos.display())))
            }
            v => Err(HushError::Panic(format!("Panic in {}: attempt to call ({}), which is not a function", pos.display(), v.display()))),
        }
    }

    fn call_method(&mut self, obj: Value, method: &str, args: Vec<Value>, pos: &Pos) -> Res<Value> {
        // Handle special objects
        match &obj {
            Value::Dict(_) => {}
            Value::AsyncJob(j) => {
                if method == "join" {
                    let mut job = j.lock().unwrap();
                    if let Some(handle) = job.handle.take() {
                        drop(job);
                        let _ = handle.join();
                    }
                    return Ok(Value::Nil);
                }
                return Err(HushError::Panic(format!("Panic in {}: no method {} on async job", pos.display(), method)));
            }
            _ => {}
        }

        let method_val = self.do_field(obj.clone(), method, pos)?;
        self.call_func(method_val, args, pos, Some(obj))
    }

    // Command execution
    fn exec_cmd_block(&mut self, block: &CmdBlock, env: Arc<Mutex<Env>>, capture_pos: Option<&Pos>, stdin_data: Option<Vec<u8>>) -> Res<Value> {
        let capture = capture_pos.is_some();

        let mut stdout_buf = String::new();
        let mut stderr_buf = String::new();
        let mut had_error = false;
        let mut error_val: Option<Value> = None;

        for cmd_cmd in &block.cmds {
            let result = self.exec_pipeline(&cmd_cmd.pipeline, env.clone(), capture, stdin_data.clone());
            match result {
                Ok((stdout, stderr, success)) => {
                    if capture {
                        stdout_buf.push_str(&stdout);
                        stderr_buf.push_str(&stderr);
                    }
                    if !success && !cmd_cmd.allow_fail {
                        // Command failed - create error
                        had_error = true;
                        if error_val.is_none() {
                            let err_ctx = make_cmd_error_dict(&stdout_buf, &stderr_buf, 1, capture_pos.unwrap_or(&Pos { file: String::new(), line: 0, col: 0 }));
                            error_val = Some(Value::Error(Arc::new(ErrorVal {
                                msg: "command returned non-zero".to_string(),
                                ctx: err_ctx,
                            })));
                        }
                    }
                }
                Err(CmdError::NonZeroExit { code, stdout, stderr }) => {
                    if capture {
                        stdout_buf.push_str(&stdout);
                        stderr_buf.push_str(&stderr);
                    } else {
                        eprint!("{}", stderr);
                    }
                    had_error = true;
                    if error_val.is_none() && !cmd_cmd.allow_fail {
                        let err_ctx = make_cmd_error_dict(&stdout, &stderr, code, capture_pos.unwrap_or(&Pos { file: String::new(), line: 0, col: 0 }));
                        error_val = Some(Value::Error(Arc::new(ErrorVal {
                            msg: "command returned non-zero".to_string(),
                            ctx: err_ctx,
                        })));
                    }
                    if !cmd_cmd.allow_fail { 
                        // Stop processing further commands if no allow_fail
                        break;
                    }
                }
                Err(CmdError::CommandNotFound(prog)) => {
                    let err = format!("{}: command not found", prog);
                    eprint!("{}", err);
                    had_error = true;
                    if !cmd_cmd.allow_fail {
                        if error_val.is_none() {
                            let err_ctx = make_cmd_error_dict("", &err, 127, capture_pos.unwrap_or(&Pos { file: String::new(), line: 0, col: 0 }));
                            error_val = Some(Value::Error(Arc::new(ErrorVal {
                                msg: "command not found".to_string(),
                                ctx: err_ctx,
                            })));
                        }
                        break;
                    }
                }
                Err(e) => {
                    had_error = true;
                    if !cmd_cmd.allow_fail { break; }
                }
            }
        }

        if capture {
            if had_error {
                if let Some(e) = error_val {
                    return Ok(e);
                }
                // Create error from accumulated output
                let dummy_pos = Pos { file: self.path.clone(), line: 0, col: 0 };
                let err_ctx = make_cmd_error_dict(&stdout_buf, &stderr_buf, 1, &dummy_pos);
                return Ok(Value::Error(Arc::new(ErrorVal {
                    msg: "command returned non-zero".to_string(),
                    ctx: err_ctx,
                })));
            }
            // Return dict with stdout/stderr
            let mut d = Dict::new();
            d.set("stdout".to_string(), Value::Str(stdout_buf));
            d.set("stderr".to_string(), Value::Str(stderr_buf));
            Ok(Value::Dict(Arc::new(Mutex::new(d))))
        } else {
            if had_error {
                if let Some(e) = error_val {
                    return Ok(e);
                }
            }
            Ok(Value::Nil)
        }
    }

    fn exec_async_cmd(&mut self, block: &CmdBlock, env: Arc<Mutex<Env>>, pos: &Pos) -> Res<Value> {
        // For now, just execute synchronously
        // (True async would need threading)
        let block_clone = block.clone();
        let env_clone = env.clone();

        // Execute the block (we can\'t easily do true async without complex machinery)
        // Just execute inline, suppress output
        self.exec_cmd_block(&block_clone, env_clone, None, None)?;

        let job_data = Arc::new(Mutex::new(AsyncJob {
            handle: None,
            stdout_buf: Arc::new(Mutex::new(String::new())),
            stderr_buf: Arc::new(Mutex::new(String::new())),
            done: true,
        }));

        Ok(Value::AsyncJob(job_data))
    }

    fn exec_pipeline(&mut self, pipeline: &[CmdPipePart], env: Arc<Mutex<Env>>, capture: bool, stdin_data: Option<Vec<u8>>) -> Result<(String, String, bool), CmdError> {
        if pipeline.is_empty() {
            return Ok((String::new(), String::new(), true));
        }

        if pipeline.len() == 1 {
            // Single command
            return self.exec_single_cmd(&pipeline[0], env, capture, stdin_data);
        }

        // Pipeline: cmd1 | cmd2 | cmd3
        // Each command\'s stdout feeds the next command\'s stdin
        let mut current_input: Option<Vec<u8>> = stdin_data;
        let mut final_stdout = String::new();
        let mut final_stderr = String::new();
        let mut success = true;

        for (i, part) in pipeline.iter().enumerate() {
            let is_last = i + 1 == pipeline.len();
            let (out, err, ok) = self.exec_single_cmd(part, env.clone(), true, current_input.clone())?;

            if !ok && !part.allow_fail {
                // Failed in pipeline without allow_fail
                if !capture {
                    eprint!("{}", err);
                }
                final_stderr.push_str(&err);
                success = false;
                return Ok((final_stdout, final_stderr, success));
            }

            if is_last {
                if !capture {
                    print!("{}", out);
                    eprint!("{}", err);
                }
                final_stdout = out;
                final_stderr = err;
                success = ok || part.allow_fail;
            } else {
                current_input = Some(out.into_bytes());
                final_stderr.push_str(&err);
            }
        }

        Ok((final_stdout, final_stderr, success))
    }

    fn exec_single_cmd(&mut self, part: &CmdPipePart, env: Arc<Mutex<Env>>, capture: bool, stdin_data: Option<Vec<u8>>) -> Result<(String, String, bool), CmdError> {
        if part.cmd.is_empty() {
            return Ok((String::new(), String::new(), true));
        }

        // Expand arguments
        let mut expanded_args: Vec<String> = Vec::new();
        for arg in &part.cmd {
            let values = self.expand_cmd_arg(arg, env.clone());
            expanded_args.extend(values);
        }

        if expanded_args.is_empty() {
            return Ok((String::new(), String::new(), true));
        }

        // Handle redirects
        let mut stdin_file: Option<String> = None;
        let mut stdout_file: Option<(String, bool)> = None;
        let mut stderr_to_stdout = false;
        let mut stdout_to_stderr = false;
        let mut stdin_str: Option<String> = None;

        for redir in &part.redirects {
            match redir {
                Redirect::Out(fd, target, append) => {
                    let t = self.expand_cmd_arg(target, env.clone()).join("");
                    if *fd == 1 || *fd == 2 {
                        if *fd == 1 {
                            stdout_file = Some((t, *append));
                        }
                    }
                }
                Redirect::Err2Out => stderr_to_stdout = true,
                Redirect::Out2Err => stdout_to_stderr = true,
                Redirect::Stdin(s) => stdin_str = Some(s.clone()),
            }
        }

        // Execute the command
        let prog = &expanded_args[0];
        let args = &expanded_args[1..];

        use std::process::{Command, Stdio};

        let mut cmd = Command::new(prog);
        cmd.args(args);

        // Set up stdin
        if let Some(s) = &stdin_str {
            cmd.stdin(Stdio::piped());
        } else if let Some(data) = &stdin_data {
            cmd.stdin(Stdio::piped());
        } else {
            cmd.stdin(Stdio::inherit());
        }

        // Set up stdout/stderr
        if capture || stdout_file.is_some() {
            cmd.stdout(Stdio::piped());
        } else {
            cmd.stdout(Stdio::inherit());
        }

        if capture || stderr_to_stdout {
            cmd.stderr(Stdio::piped());
        } else {
            cmd.stderr(Stdio::inherit());
        }

        let mut child = match cmd.spawn() {
            Ok(c) => c,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                return Err(CmdError::CommandNotFound(prog.clone()));
            }
            Err(e) => return Err(CmdError::Io(e.to_string())),
        };

        // Write stdin
        if let Some(s) = &stdin_str {
            if let Some(mut stdin) = child.stdin.take() {
                let _ = stdin.write_all(s.as_bytes());
                let _ = stdin.write_all(b"\\n");
            }
        } else if let Some(data) = &stdin_data {
            if let Some(mut stdin) = child.stdin.take() {
                let _ = stdin.write_all(data);
            }
        }

        let output = match child.wait_with_output() {
            Ok(o) => o,
            Err(e) => return Err(CmdError::Io(e.to_string())),
        };

        let stdout = String::from_utf8_lossy(&output.stdout).to_string();
        let stderr = String::from_utf8_lossy(&output.stderr).to_string();

        // Handle file redirects
        if let Some((file, append)) = &stdout_file {
            use std::fs::OpenOptions;
            let mut f = OpenOptions::new().write(true).create(true).append(*append).truncate(!append).open(file)
                .map_err(|e| CmdError::Io(e.to_string()))?;
            f.write_all(stdout.as_bytes()).map_err(|e| CmdError::Io(e.to_string()))?;
        }

        // If not capturing, print stderr
        if !capture {
            if stderr_to_stdout {
                print!("{}", stderr);
            } else {
                eprint!("{}", stderr);
            }
            if stdout_file.is_none() {
                print!("{}", stdout);
            }
        } else {
            // print stderr to actual stderr if not redirected  
            if !stderr_to_stdout {
                eprint!("{}", stderr);
            }
        }

        let success = output.status.success();
        if !success {
            let code = output.status.code().unwrap_or(1);
            if !capture {
                return Ok((String::new(), stderr, false));
            }
            return Err(CmdError::NonZeroExit { code, stdout, stderr });
        }

        Ok((stdout, stderr, true))
    }

    fn expand_cmd_arg(&mut self, arg: &CmdArg, env: Arc<Mutex<Env>>) -> Vec<String> {
        match arg {
            CmdArg::Parts(parts) => {
                // Expand variable references and apply glob expansion
                let mut s = String::new();
                let mut has_glob = false;
                let mut has_var = false;

                for part in parts {
                    match part {
                        ArgPart::Lit(l) => {
                            if l.contains(\'*\') || l.contains(\'?\') || l.contains(\'%\') || l.contains("**") {
                                has_glob = true;
                            }
                            if l.starts_with(\'~\') {
                                // Tilde expansion
                                let home = std::env::var("HOME").unwrap_or_default();
                                s.push_str(&l.replacen(\'~\', &home, 1));
                            } else {
                                s.push_str(l);
                            }
                        }
                        ArgPart::Var(name, _pos) => {
                            has_var = true;
                            let val = env.lock().unwrap().get(name).unwrap_or(Value::Nil);
                            match val {
                                Value::Array(arr) => {
                                    // Array expands to multiple args
                                    let arr = arr.lock().unwrap();
                                    if arr.is_empty() {
                                        // Empty array - contribute nothing, but need to handle
                                    } else if parts.len() == 1 {
                                        // Single var: expand to multiple args
                                        return arr.iter().map(|v| v.display()).collect();
                                    } else {
                                        s.push_str(&arr.iter().map(|v| v.display()).collect::<Vec<_>>().join(" "));
                                    }
                                }
                                v => s.push_str(&v.display()),
                            }
                        }
                    }
                }

                // Apply glob expansion
                if has_glob {
                    let expanded = glob_expand(&s);
                    if expanded.is_empty() {
                        // nullglob: return nothing
                        vec![]
                    } else {
                        expanded
                    }
                } else if s.is_empty() && !parts.is_empty() {
                    // Empty expansion
                    vec![]
                } else {
                    vec![s]
                }
            }
        }
    }
}

fn is_std_dict(v: &Value) -> bool {
    false  // std is not a regular dict in our impl
}

fn make_cmd_error_dict(stdout: &str, stderr: &str, code: i32, pos: &Pos) -> Value {
    let mut d = Dict::new();
    d.set("stdout".to_string(), Value::Str(stdout.to_string()));
    d.set("stderr".to_string(), Value::Str(stderr.to_string()));
    let mut err_d = Dict::new();
    err_d.set("status".to_string(), Value::Int(code as i64));
    err_d.set("pos".to_string(), Value::Str(pos.display()));
    d.set("error".to_string(), Value::Dict(Arc::new(Mutex::new(err_d))));
    Value::Dict(Arc::new(Mutex::new(d)))
}

fn glob_expand(pattern: &str) -> Vec<String> {
    // Simple glob expansion using the standard glob patterns
    // * matches any sequence (not crossing /)
    // ** matches any sequence including /
    // ? matches single char
    // % same as *

    let pattern = if pattern.starts_with("./") {
        pattern.to_string()
    } else {
        format!("./{}", pattern)
    };

    let entries = glob_match_pattern(&pattern);
    entries
}

fn glob_match_pattern(pattern: &str) -> Vec<String> {
    use std::path::Path;

    // Use libc glob  
    unsafe {
        let c_pattern = std::ffi::CString::new(pattern).unwrap();
        let mut pglob: libc::glob_t = std::mem::zeroed();

        let flags = libc::GLOB_NOSORT | libc::GLOB_TILDE;
        let ret = libc::glob(c_pattern.as_ptr(), flags as i32, None, &mut pglob);

        let mut results = Vec::new();
        if ret == 0 {
            for i in 0..pglob.gl_pathc {
                let path = std::ffi::CStr::from_ptr(*pglob.gl_pathv.add(i));
                if let Ok(s) = path.to_str() {
                    results.push(s.to_string());
                }
            }
        }
        libc::globfree(&mut pglob);
        results
    }
}

#[derive(Debug)]
enum CmdError {
    NonZeroExit { code: i32, stdout: String, stderr: String },
    CommandNotFound(String),
    Io(String),
}

