    d.set("catch".to_string(), make_native_func("catch", path));
    d.set("typecheck".to_string(), make_native_func("typecheck", path));
    d.set("try_typecheck".to_string(), make_native_func("try_typecheck", path));
    d.set("bind".to_string(), make_native_func("bind", path));
    d.set("args".to_string(), Value::Array(Arc::new(Mutex::new(
        args.to_vec()
    ))));
    d.set("read".to_string(), make_native_func("read", path));
    d.set("import".to_string(), make_native_func("import", path));

    // Nested modules
    let json = make_json_module();
    d.set("json".to_string(), json);
    let hex = make_hex_module();
    d.set("hex".to_string(), hex);
    let base64 = make_base64_module();
    d.set("base64".to_string(), base64);

    Value::Dict(Arc::new(Mutex::new(d)))
}

fn make_native_func(name: &str, path: &str) -> Value {
    // Create a placeholder - we need a special mechanism
    // Let\'s use a special Dict with a __native__ key
    let mut d = Dict::new();
