// ---------- Values ----------

#[derive(Clone, Debug)]
pub enum Value {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Char(u8),
    Array(Arc<Mutex<Vec<Value>>>),
    Dict(Arc<Mutex<Dict>>),
    Function(Arc<Func>),
    Error(Arc<ErrorVal>),
    // For async jobs
    AsyncJob(Arc<Mutex<AsyncJob>>),
}

#[derive(Debug)]
pub struct Dict {
    pub map: HashMap<String, Value>,
    pub keys: Vec<String>,
}

impl Dict {
    pub fn new() -> Self { Dict { map: HashMap::new(), keys: Vec::new() } }
    pub fn get(&self, k: &str) -> Option<&Value> { self.map.get(k) }
    pub fn set(&mut self, k: String, v: Value) {
        if !self.map.contains_key(&k) { self.keys.push(k.clone()); }
        self.map.insert(k, v);
    }
    pub fn len(&self) -> usize { self.map.len() }
}

#[derive(Debug)]
pub struct Func {
    pub params: Vec<String>,
    pub body: Vec<Stmt>,
    pub env: Arc<Mutex<Env>>,
    pub pos: Pos,
}

#[derive(Debug, Clone)]
pub struct ErrorVal {
    pub msg: String,
    pub ctx: Value,
}

#[derive(Debug)]
pub struct AsyncJob {
    pub handle: Option<std::thread::JoinHandle<()>>,
    pub stdout_buf: Arc<Mutex<String>>,
    pub stderr_buf: Arc<Mutex<String>>,
    pub done: bool,
}

impl PartialEq for Value {
    fn eq(&self, other: &Value) -> bool {
        match (self, other) {
            (Value::Nil, Value::Nil) => true,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a.to_bits() == b.to_bits(),
            (Value::Str(a), Value::Str(b)) => a == b,
            (Value::Char(a), Value::Char(b)) => a == b,
            (Value::Array(a), Value::Array(b)) => Arc::ptr_eq(a, b),
            (Value::Dict(a), Value::Dict(b)) => Arc::ptr_eq(a, b),
            (Value::Function(a), Value::Function(b)) => Arc::ptr_eq(a, b),
            (Value::Error(a), Value::Error(b)) => Arc::ptr_eq(a, b),
            _ => false,
        }
    }
}

impl Value {
    pub fn type_name(&self) -> &\'static str {
        match self {
            Value::Nil => "nil",
            Value::Bool(_) => "bool",
            Value::Int(_) => "int",
            Value::Float(_) => "float",
            Value::Str(_) => "string",
            Value::Char(_) => "char",
            Value::Array(_) => "array",
            Value::Dict(_) | Value::AsyncJob(_) => "dict",
            Value::Function(_) => "function",
            Value::Error(_) => "error",
        }
    }

    pub fn is_error(&self) -> bool { matches!(self, Value::Error(_)) }

    pub fn display(&self) -> String { self.fmt_val(false) }

    pub fn fmt_val(&self, in_coll: bool) -> String {
        match self {
            Value::Nil => "nil".to_string(),
            Value::Bool(b) => if *b { "true" } else { "false" }.to_string(),
            Value::Int(n) => n.to_string(),
            Value::Float(f) => fmt_float_runtime(*f),
            Value::Str(s) => if in_coll { format!("\\"{}\\"", escape_str(s)) } else { s.clone() },
            Value::Char(b) => (*b as char).to_string(),
            Value::Array(arr) => {
                let arr = arr.lock().unwrap();
                if arr.is_empty() { return "[]".to_string(); }
                let parts: Vec<String> = arr.iter().map(|v| v.fmt_val(true)).collect();
                format!("[ {} ]", parts.join(", "))
            }
            Value::Dict(d) => {
                let d = d.lock().unwrap();
                if d.map.is_empty() { return "@[]".to_string(); }
                let parts: Vec<String> = d.keys.iter()
                    .filter_map(|k| d.map.get(k).map(|v| format!("\\"{}\\":{} {}", k, "", v.fmt_val(true))))
                    .collect();
                // Format: @[ "key": value, ... ]
                let parts: Vec<String> = d.keys.iter()
                    .filter_map(|k| d.map.get(k).map(|v| format!("\\"{}\\":{}{}", k, " ", v.fmt_val(true))))
                    .collect();
                format!("@[ {} ]", parts.join(", "))
            }
            Value::Function(f) => {
                format!("function{}>", f.pos.display()).replace("function", "function<")
            }
            Value::Error(e) => {
                format!("error: \\"{}\\" ({})", escape_str(&e.msg), e.ctx.fmt_val(true))
            }
            Value::AsyncJob(j) => {
                "@[ \\"join\\": <command>.join ]".to_string()
            }
        }
    }
}

fn fmt_float_runtime(f: f64) -> String {
    if f.is_nan() { return "NaN".to_string(); }
    if f.is_infinite() { return if f > 0.0 { "inf" } else { "-inf" }.to_string(); }
    let s = format!("{}", f);
    if !s.contains(\'.\') && !s.contains(\'e\') { format!("{}.0", s) } else { s }
}

fn escape_str(s: &str) -> String {
    let mut r = String::new();
    for c in s.chars() {
        match c {
            \'\\n\' => r.push_str("\\\\n"),
            \'\\t\' => r.push_str("\\\\t"),
            \'\\0\' => r.push_str("\\\\0"),
            \'\\\\\' => r.push_str("\\\\\\\\"),
            \'"\' => r.push_str("\\\\\\""),
            c => r.push(c),
        }
    }
    r
}

