fn make_std_dict(path: &str, args: &[Value]) -> Value {
    let mut d = Dict::new();
    d.set("print".to_string(), make_native_func("print", path));
    d.set("println".to_string(), make_native_func("println", path));
    d.set("type".to_string(), make_native_func("type", path));
    d.set("len".to_string(), make_native_func("len", path));
    d.set("iter".to_string(), make_native_func("iter", path));
    d.set("push".to_string(), make_native_func("push", path));
    d.set("pop".to_string(), make_native_func("pop", path));
    d.set("sort".to_string(), make_native_func("sort", path));
    d.set("to_string".to_string(), make_native_func("to_string", path));
    d.set("str".to_string(), make_native_func("str", path));
    d.set("int".to_string(), make_native_func("int", path));
    d.set("float".to_string(), make_native_func("float", path));
    d.set("bytes".to_string(), make_native_func("bytes", path));
    d.set("contains".to_string(), make_native_func("contains", path));
    d.set("substr".to_string(), make_native_func("substr", path));
    d.set("split".to_string(), make_native_func("split", path));
    d.set("trim".to_string(), make_native_func("trim", path));
    d.set("replace".to_string(), make_native_func("replace", path));
    d.set("regex".to_string(), make_native_func("regex", path));
    d.set("is_empty".to_string(), make_native_func("is_empty", path));
    d.set("range".to_string(), make_native_func("range", path));
    d.set("glob".to_string(), make_native_func("glob", path));
    d.set("env".to_string(), make_native_func("env", path));
    d.set("export".to_string(), make_native_func("export", path));
    d.set("cd".to_string(), make_native_func("cd", path));
    d.set("cwd".to_string(), make_native_func("cwd", path));
    d.set("sleep".to_string(), make_native_func("sleep", path));
    d.set("rand".to_string(), make_native_func("rand", path));
    d.set("randint".to_string(), make_native_func("randint", path));
