                            Err(e) => Err(e),
                        }
                    }
                    Value::Error(e) => Ok(Value::Error(e.clone())),
                    v => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected function", pos.display(), v.display()))),
                }
            }
            "typecheck" => {
                check_args(&name, &args, 2, pos)?;
                match &args[1] {
                    Value::Str(expected) => {
                        if args[0].type_name() == expected.as_str() {
                            Ok(Value::Nil)
                        } else {
                            Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected {}", pos.display(), args[0].display(), expected)))
                        }
                    }
                    _ => Err(HushError::Panic(format!("Panic in {}: typecheck expects string type name", pos.display()))),
                }
            }
            "try_typecheck" => {
                check_args(&name, &args, 2, pos)?;
                match &args[1] {
                    Value::Str(expected) => {
