                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Str(s) => Ok(Value::Int(s.len() as i64)),
                    Value::Array(a) => Ok(Value::Int(a.lock().unwrap().len() as i64)),
                    Value::Dict(d) => Ok(Value::Int(d.lock().unwrap().len() as i64)),
                    v => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected string, array or dict", pos.display(), v.display()))),
                }
            }
            "iter" => {
                check_args(&name, &args, 1, pos)?;
                Ok(make_iter(args[0].clone(), pos)?)
            }
            "push" => {
                check_args(&name, &args, 2, pos)?;
                match &args[0] {
                    Value::Array(a) => {
                        a.lock().unwrap().push(args[1].clone());
                        Ok(Value::Nil)
                    }
                    v => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected array", pos.display(), v.display()))),
                }
            }
            "pop" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Array(a) => {
                        let mut a = a.lock().unwrap();
                        match a.pop() {
                            Some(v) => Ok(v),
                            None => Err(HushError::Panic(format!("Panic in {}: collection is empty", pos.display()))),
                        }
                    }
                    v => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected array", pos.display(), v.display()))),
                }
            }
            "sort" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Array(a) => {
                        let mut arr = a.lock().unwrap();
                        arr.sort_by(|a, b| compare_values(a, b));
                        Ok(Value::Nil)
                    }
                    v => Err(HushError::Panic(format!("Panic in {}: expected array", pos.display()))),
                }
            }
            "to_string" => {
                check_args(&name, &args, 1, pos)?;
                Ok(Value::Str(args[0].display()))
            }
            "int" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Int(n) => Ok(Value::Int(*n)),
                    Value::Float(f) => Ok(Value::Int(*f as i64)),
                    Value::Str(s) => match s.trim().parse::<i64>() {
                        Ok(n) => Ok(Value::Int(n)),
                        Err(_) => Err(HushError::Panic(format!("Panic in {}: cannot convert \"{}\" to int", pos.display(), s))),
                    },
                    v => Err(HushError::Panic(format!("Panic in {}: cannot convert to int", pos.display()))),
                }
            }
            "float" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Float(f) => Ok(Value::Float(*f)),
                    Value::Int(n) => Ok(Value::Float(*n as f64)),
                    Value::Str(s) => match s.trim().parse::<f64>() {
                        Ok(f) => Ok(Value::Float(f)),
                        Err(_) => Err(HushError::Panic(format!("Panic in {}: cannot convert to float", pos.display()))),
                    },
                    v => Err(HushError::Panic(format!("Panic in {}: cannot convert to float", pos.display()))),
                }
            }
            "bytes" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Str(s) => {
                        let bytes: Vec<Value> = s.bytes().map(|b| Value::Char(b)).collect();
                        Ok(Value::Array(Arc::new(Mutex::new(bytes))))
                    }
                    v => Err(HushError::Panic(format!("Panic in {}: expected string", pos.display()))),
                }
            }
            "contains" => {
                check_args(&name, &args, 2, pos)?;
                match (&args[0], &args[1]) {
                    (Value::Str(s), Value::Char(c)) => Ok(Value::Bool(s.as_bytes().contains(c))),
                    (Value::Array(arr), val) => {
                        let arr = arr.lock().unwrap();
                        Ok(Value::Bool(arr.iter().any(|v| v == val)))
                    }
                    (Value::Dict(d), Value::Str(k)) => {
                        Ok(Value::Bool(d.lock().unwrap().map.contains_key(k)))
                    }
                    (Value::Str(_), v) => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected char", pos.display(), v.display()))),
                    (v, _) => Err(HushError::Panic(format!("Panic in {}: cannot search in {}", pos.display(), v.type_name()))),
                }
            }
            "substr" => {
                check_args(&name, &args, 3, pos)?;
                match (&args[0], &args[1], &args[2]) {
                    (Value::Str(s), Value::Int(start), Value::Int(len)) => {
                        let st = *start as usize;
                        let ln = *len as usize;
                        if st >= s.len() { return Ok(Value::Nil); }
                        let end = (st + ln).min(s.len());
                        if end > s.len() { return Ok(Value::Nil); }
                        Ok(Value::Str(s[st..end].to_string()))
                    }
                    _ => Err(HushError::Panic(format!("Panic in {}: invalid args to substr", pos.display()))),
                }
            }
            "split" => {
                check_args(&name, &args, 2, pos)?;
                match (&args[0], &args[1]) {
                    (Value::Str(s), Value::Str(sep)) => {
                        let parts: Vec<Value> = s.split(sep.as_str()).map(|p| Value::Str(p.to_string())).collect();
                        Ok(Value::Array(Arc::new(Mutex::new(parts))))
                    }
                    _ => Err(HushError::Panic(format!("Panic in {}: split expects string args", pos.display()))),
                }
            }
            "trim" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Str(s) => Ok(Value::Str(s.trim().to_string())),
                    v => Err(HushError::Panic(format!("Panic in {}: expected string", pos.display()))),
                }
            }
            "replace" => {
                check_args(&name, &args, 3, pos)?;
                match (&args[0], &args[1], &args[2]) {
                    (Value::Str(s), Value::Str(from), Value::Str(to)) => {
                        Ok(Value::Str(s.replace(from.as_str(), to.as_str())))
                    }
                    _ => Err(HushError::Panic(format!("Panic in {}: replace expects string args", pos.display()))),
                }
            }
            "regex" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Str(pattern) => {
                        Ok(make_regex(pattern.clone()))
                    }
                    v => Err(HushError::Panic(format!("Panic in {}: expected string pattern", pos.display()))),
                }
            }
            "is_empty" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Str(s) => Ok(Value::Bool(s.is_empty())),
                    Value::Array(a) => Ok(Value::Bool(a.lock().unwrap().is_empty())),
                    Value::Dict(d) => Ok(Value::Bool(d.lock().unwrap().map.is_empty())),
                    v => Err(HushError::Panic(format!("Panic in {}: is_empty not supported for {}", pos.display(), v.type_name()))),
                }
            }
            "range" => {
                check_args(&name, &args, 3, pos)?;
                match (&args[0], &args[1], &args[2]) {
                    (Value::Int(start), Value::Int(end), Value::Int(step)) => {
                        let start = *start;
                        let end = *end;
                        let step = *step;
                        let mut current = start;
                        let current_cell = Arc::new(Mutex::new(current));
                        let current2 = current_cell.clone();
                        let func = Value::Function(Arc::new(Func {
                            params: vec![],
                            body: vec![],
                            env: Arc::new(Mutex::new(Env::new())),
                            pos: pos.clone(),
                        }));
                        // Create closure via builtin
                        Ok(make_range_iter(start, end, step))
                    }
                    _ => Err(HushError::Panic(format!("Panic in {}: range expects int args", pos.display()))),
                }
            }
            "glob" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Str(pattern) => {
                        let results = glob_expand(pattern);
                        let vals: Vec<Value> = results.into_iter().map(Value::Str).collect();
                        Ok(Value::Array(Arc::new(Mutex::new(vals))))
                    }
                    v => Err(HushError::Panic(format!("Panic in {}: expected string pattern", pos.display()))),
                }
            }
            "env" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Str(var) => {
                        match std::env::var(var) {
                            Ok(val) => Ok(Value::Str(val)),
                            Err(_) => Ok(Value::Nil),
                        }
                    }
                    v => Err(HushError::Panic(format!("Panic in {}: expected string", pos.display()))),
                }
            }
            "export" => {
                check_args(&name, &args, 2, pos)?;
                match (&args[0], &args[1]) {
                    (Value::Str(var), val) => {
                        std::env::set_var(var, val.display());
                        Ok(Value::Nil)
                    }
                    _ => Err(HushError::Panic(format!("Panic in {}: expected string var name", pos.display()))),
                }
            }
            "cd" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Str(dir) => {
                        std::env::set_current_dir(dir).map_err(|e| HushError::Panic(format!("Panic in {}: {}", pos.display(), e)))?;
                        Ok(Value::Nil)
                    }
                    v => Err(HushError::Panic(format!("Panic in {}: expected string", pos.display()))),
                }
            }
            "cwd" => {
                check_args(&name, &args, 0, pos)?;
                match std::env::current_dir() {
                    Ok(p) => Ok(Value::Str(p.to_string_lossy().to_string())),
                    Err(e) => Err(HushError::Panic(format!("Panic in {}: {}", pos.display(), e))),
                }
            }
            "sleep" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Int(ms) => {
                        std::thread::sleep(std::time::Duration::from_millis(*ms as u64));
                        Ok(Value::Nil)
                    }
                    v => Err(HushError::Panic(format!("Panic in {}: sleep expects int (milliseconds)", pos.display()))),
                }
            }
            "rand" => {
                check_args(&name, &args, 0, pos)?;
                // Simple LCG random number generator
                let r = lcg_rand() as f64 / u64::MAX as f64;
                Ok(Value::Float(r))
            }
            "randint" => {
                check_args(&name, &args, 2, pos)?;
                match (&args[0], &args[1]) {
                    (Value::Int(lo), Value::Int(hi)) => {
                        let r = lcg_rand() % ((*hi - *lo) as u64 + 1);
                        Ok(Value::Int(*lo + r as i64))
                    }
                    _ => Err(HushError::Panic(format!("Panic in {}: randint expects int args", pos.display()))),
                }
            }
            "randseed" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Int(seed) => { set_rand_seed(*seed as u64); Ok(Value::Nil) }
                    _ => Err(HushError::Panic(format!("Panic in {}: randseed expects int", pos.display()))),
                }
            }
            "assert" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Bool(true) => Ok(Value::Nil),
                    Value::Bool(false) => Err(HushError::Panic(format!("Panic in {}: assertion failed", pos.display()))),
                    v => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected bool", pos.display(), v.display()))),
                }
            }
            "panic" => {
                check_args(&name, &args, 1, pos)?;
                let msg = match &args[0] {
                    Value::Str(s) => s.clone(),
                    v => v.display(),
                };
                Err(HushError::Panic(format!("Panic in {}: std.panic(\"{}\")", pos.display(), msg)))
            }
            "exit" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Int(n) => Err(HushError::Exit(*n as i32)),
                    v => Err(HushError::Panic(format!("Panic in {}: exit expects int", pos.display()))),
                }
            }
            "error" => {
                check_args(&name, &args, 2, pos)?;
                match &args[0] {
                    Value::Str(msg) => Ok(Value::Error(Arc::new(ErrorVal {
                        msg: msg.clone(),
                        ctx: args[1].clone(),
                    }))),
                    v => Err(HushError::Panic(format!("Panic in {}: error message must be string", pos.display()))),
                }
            }
            "has_error" => {
                check_args(&name, &args, 1, pos)?;
                Ok(Value::Bool(args[0].is_error()))
            }
            "catch" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Function(_) | Value::Builtin(_) => {
                        let func = args[0].clone();
                        match self.call_func(func, vec![], pos, None) {
                            Ok(v) => Ok(v),
                            Err(HushError::Panic(msg)) => Ok(Value::Error(Arc::new(ErrorVal {
                                msg: format!("caught panic: {}", msg),
                                ctx: Value::Str("panic".to_string()),
                            }))),
                            Err(e) => Err(e),
                        }
                    }
                    Value::Error(e) => Ok(Value::Error(e.clone())),
                    v => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected function", pos.display(), v.display()))),
                }
            }
            "typecheck" => {
                check_args(&name, &args, 2, pos)?;
                match &args[1] {
                    Value::Str(expected) => {
                        if args[0].type_name() == expected.as_str() {
                            Ok(Value::Nil)
                        } else {
                            Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected {}", pos.display(), args[0].display(), expected)))
                        }
                    }
                    _ => Err(HushError::Panic(format!("Panic in {}: typecheck expects string type name", pos.display()))),
                }
            }
            "try_typecheck" => {
                check_args(&name, &args, 2, pos)?;
                match &args[1] {
                    Value::Str(expected) => {
                        if args[0].type_name() == expected.as_str() {
                            Ok(Value::Nil)
                        } else {
                            Ok(Value::Error(Arc::new(ErrorVal {
                                msg: format!("type error: expected {}", expected),
                                ctx: Value::Nil,
                            })))
                        }
                    }
                    _ => Err(HushError::Panic(format!("Panic in {}: try_typecheck expects string type name", pos.display()))),
                }
            }
            "bind" => {
                check_args(&name, &args, 2, pos)?;
                match (&args[0], &args[1]) {
                    (Value::Function(_) | Value::Builtin(_), Value::Function(_) | Value::Builtin(_)) => {
                        let func = args[0].clone();
                        let provider = args[1].clone();
                        // bind(f, g) creates a function that calls g() and uses result
                        // Actually bind(f, g) -> function that calls f(g())
                        Ok(make_bound_func(func, provider))
                    }
                    (f, p) => Err(HushError::Panic(format!("Panic in {}: value ({}) has unexpected type, expected function", pos.display(), p.display()))),
                }
            }
            "args" => {
                // Already set as array in make_std_dict
                Ok(Value::Nil)
            }
            "read" => {
                check_args(&name, &args, 0, pos)?;
                let mut line = String::new();
                std::io::stdin().read_line(&mut line).ok();
                if line.ends_with('\n') { line.pop(); }
                Ok(Value::Str(line))
            }
            "import" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Str(path) => {
                        let source = std::fs::read_to_string(path)
                            .map_err(|e| HushError::Panic(format!("Panic in {}: {}", pos.display(), e.to_string().replace("No such file or directory (os error 2)", "No such file or directory (os error 2)"))))?;
                        let (tokens, lex_errors) = crate::lexer::lex(&source, path);
                        // Ignore errors
                        let (program, _) = crate::parser::parse(&tokens, path);
                        let old_path = self.path.clone();
                        self.path = path.clone();
                        let child_env = Arc::new(Mutex::new(Env::child(self.env.clone())));
                        let result = self.exec_stmts_return(&program.stmts, child_env);
                        self.path = old_path;
                        result
                    }
                    v => Err(HushError::Panic(format!("Panic in {}: expected string path", pos.display()))),
                }
            }
            "json.encode" => {
                check_args(&name, &args, 1, pos)?;
                Ok(Value::Str(json_encode(&args[0])))
            }
            "json.decode" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Str(s) => json_decode(s, pos),
                    v => Err(HushError::Panic(format!("Panic in {}: expected string", pos.display()))),
                }
            }
            "hex.encode" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Str(s) => {
                        let hex: String = s.bytes().map(|b| format!("{:02x}", b)).collect();
                        Ok(Value::Str(hex))
                    }
                    v => Err(HushError::Panic(format!("Panic in {}: expected string", pos.display()))),
                }
            }
            "hex.decode" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Str(s) => {
                        let bytes: Result<Vec<u8>, _> = (0..s.len()).step_by(2)
                            .map(|i| u8::from_str_radix(&s[i..i+2], 16))
                            .collect();
                        match bytes {
                            Ok(b) => Ok(Value::Str(String::from_utf8_lossy(&b).to_string())),
                            Err(_) => Err(HushError::Panic(format!("Panic in {}: invalid hex string", pos.display()))),
                        }
                    }
                    v => Err(HushError::Panic(format!("Panic in {}: expected string", pos.display()))),
                }
            }
            "base64.encode" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Str(s) => Ok(Value::Str(base64_encode(s.as_bytes()))),
                    v => Err(HushError::Panic(format!("Panic in {}: expected string", pos.display()))),
                }
            }
            "base64.decode" => {
                check_args(&name, &args, 1, pos)?;
                match &args[0] {
                    Value::Str(s) => {
                        match base64_decode(s) {
                            Ok(bytes) => Ok(Value::Str(String::from_utf8_lossy(&bytes).to_string())),
                            Err(e) => Err(HushError::Panic(format!("Panic in {}: {}", pos.display(), e))),
                        }
                    }
                    v => Err(HushError::Panic(format!("Panic in {}: expected string", pos.display()))),
                }
            }
            // Regex methods
            n if n.starts_with("regex:") => {
                let pattern = &n[6..];
                call_regex_method(pattern, &args, pos, self)
            }
            _ => Err(HushError::Panic(format!("Panic in {}: unknown builtin: {}", pos.display(), name))),
        }
    }
}

fn check_args(name: &str, args: &[Value], expected: usize, pos: &Pos) -> Res<()> {
    if args.len() != expected {
        Err(HushError::Panic(format!("Panic in {}: incorrect amount of function parameters -- supplied {}, expected {}", pos.display(), args.len(), expected)))
    } else {
        Ok(())
    }
}

fn value_to_print(v: &Value) -> String {
    match v {
        Value::Str(s) => s.clone(),
        Value::Char(b) => (*b as char).to_string(),
        other => other.display(),
    }
}

fn make_iter(val: Value, pos: &Pos) -> Res<Value> {
    match val {
        Value::Array(arr) => {
            let idx = Arc::new(Mutex::new(0usize));
            let arr2 = arr.clone();
            // Return a function that iterates
            Ok(make_array_iter(arr))
        }
        Value::Dict(d) => {
            Ok(make_dict_iter(d))
        }
        Value::Str(s) => {
            Ok(make_str_iter(s))
        }
        v => Err(HushError::Panic(format!("Panic in {}: cannot iterate over {}", pos.display(), v.type_name()))),
    }
}

fn make_array_iter(arr: Arc<Mutex<Vec<Value>>>) -> Value {
    let idx = Arc::new(Mutex::new(0usize));
    make_closure_iter(move || {
        let mut i = idx.lock().unwrap();
        let arr = arr.lock().unwrap();
        if *i >= arr.len() {
            None
        } else {
            let v = arr[*i].clone();
            *i += 1;
            Some(v)
        }
    })
}

fn make_dict_iter(d: Arc<Mutex<Dict>>) -> Value {
    let idx = Arc::new(Mutex::new(0usize));
    make_closure_iter(move || {
        let mut i = idx.lock().unwrap();
        let d = d.lock().unwrap();
        if *i >= d.keys.len() {
            None
        } else {
            let k = d.keys[*i].clone();
            let v = d.map.get(&k).cloned().unwrap_or(Value::Nil);
            *i += 1;
            let mut entry = Dict::new();
            entry.set("key".to_string(), Value::Str(k));
            entry.set("value".to_string(), v);
            Some(Value::Dict(Arc::new(Mutex::new(entry))))
        }
    })
}

fn make_str_iter(s: String) -> Value {
    let idx = Arc::new(Mutex::new(0usize));
    let bytes: Vec<u8> = s.into_bytes();
    let bytes = Arc::new(bytes);
    make_closure_iter(move || {
        let mut i = idx.lock().unwrap();
        if *i >= bytes.len() {
            None
        } else {
            let b = bytes[*i];
            *i += 1;
            Some(Value::Char(b))
        }
    })
}

fn make_range_iter(start: i64, end: i64, step: i64) -> Value {
    let current = Arc::new(Mutex::new(start));
    make_closure_iter(move || {
        let mut c = current.lock().unwrap();
        if (step > 0 && *c >= end) || (step < 0 && *c <= end) || step == 0 {
            None
        } else {
            let v = *c;
            *c += step;
            Some(Value::Int(v))
        }
    })
}

fn make_closure_iter<F>(mut next_fn: F) -> Value
where
    F: FnMut() -> Option<Value> + Send + 'static,
{
    let next_fn = Arc::new(Mutex::new(next_fn));
    // We'll create a special builtin-backed iterator
    // Store the closure in a dict with a special key
    let closure = Arc::new(Mutex::new(Box::new(move || next_fn.lock().unwrap()()) as Box<dyn FnMut() -> Option<Value> + Send>));
    let closure_id = make_iter_id(closure);
    Value::Builtin(format!("iter_next:{}", closure_id))
}

static ITER_COUNTER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

// Global storage for iterator closures
type IterClosures = std::collections::HashMap<u64, Arc<Mutex<Box<dyn FnMut() -> Option<Value> + Send>>>>;
static ITER_STORAGE: std::sync::OnceLock<Mutex<IterClosures>> = std::sync::OnceLock::new();

fn get_iter_storage() -> &'static Mutex<IterClosures> {
    ITER_STORAGE.get_or_init(|| Mutex::new(HashMap::new()))
}

fn make_iter_id(closure: Arc<Mutex<Box<dyn FnMut() -> Option<Value> + Send>>>) -> u64 {
    let id = ITER_COUNTER.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    get_iter_storage().lock().unwrap().insert(id, closure);
    id
}

fn call_iter_next(id: u64, pos: &Pos) -> Res<Value> {
    let next = {
        let mut storage = get_iter_storage().lock().unwrap();
        if let Some(closure) = storage.get_mut(&id) {
            closure.lock().unwrap()()
        } else {
            return Err(HushError::Panic(format!("Panic in {}: iterator expired", pos.display())));
        }
    };
    match next {
        None => {
            let mut d = Dict::new();
            d.set("finished".to_string(), Value::Bool(true));
            Ok(Value::Dict(Arc::new(Mutex::new(d))))
        }
        Some(val) => {
            let mut d = Dict::new();
            d.set("finished".to_string(), Value::Bool(false));
            d.set("value".to_string(), val);
            Ok(Value::Dict(Arc::new(Mutex::new(d))))
        }
    }
}

