with open('/workspace/hush/src/interpreter.rs', 'r') as f:
    lines = f.readlines()

# Aggressively fix all unbalanced lines
for i in range(len(lines)):
    line = lines[i].rstrip('\n')
    # Find lines that contain Err or Panic with unbalanced parens
    if 'Panic' in line or 'Err(' in line:
        # Don't count parens in strings
        # Simple approach: count ( and )
        opens = line.count('(')
        closes = line.count(')')
        if closes > opens:
            diff = closes - opens
            # Remove extra ) from end
            for _ in range(diff):
                # Remove from the right, before any trailing ,\n
                s = line.rstrip()
                if s.endswith(','):
                    s = s[:-1].rstrip(')')[:len(s)-1-diff+1] + ',' if len(s) > diff else s
                    # Actually simpler:
                    for j in range(diff):
                        if '),' in s:
                            s = s.replace('),', ',', 1)
                        elif s.endswith(')'):
                            s = s[:-1]
                else:
                    for j in range(diff):
                        if s.endswith(')'):
                            s = s[:-1]
                line = s
            if lines[i].rstrip('\n') != line:
                print(f"Line {i+1}: {repr(lines[i].rstrip())[-40:]} -> {repr(line)[-40:]}")
                lines[i] = line + '\n'

with open('/workspace/hush/src/interpreter.rs', 'w') as f:
    f.writelines(lines)
print("Done!")
